  ui_story_5045_50450101_20_dialog_content = "Eu só vim ao Lumo Hall da Justiça porque fui convidado aqui...",
  ui_story_5045_50450101_21_dialog_content = "<color=#737378>Bam, bam, bam!</color>",
  ui_story_5045_50450101_22_dialog_content = "Silêncio!",
  ui_story_5045_50450101_23_dialog_content = "Observe as regras do tribunal e responda às minhas perguntas com honestidade e com o melhor de seu conhecimento.",
