  ui_story_5045_50450101_25_dialog_content = "(Já é ruim o suficiente eu estar sendo empurrado para o banco das testemunhas, mas aquele olhar que ela está me dando... Ela realmente acha que eu sou um suspeito!)",
  ui_story_5045_50450101_26_dialog_content = "(Eu tenho que dizer algo para ela! Eu quero gritar do fundo do meu coração-)",
  ui_story_5045_50450101_27_option_content = "Foi tudo uma armação!",
  ui_story_5045_50450101_28_dialog_content = "Ah?",
