  ui_story_5045_50450101_40_dialog_content = "Tina, acordar!",
  ui_story_5045_50450101_41_dialog_content = "Yaaaawn... Hã? por que PlayerName tomando posição? Ele é um suspeito, não é?",
  ui_story_5045_50450101_42_dialog_content = "Ah! Oh merda, oh merda!",
  ui_story_5045_50450101_43_dialog_content = "Não me diga que perdi as declarações iniciais do julgamento?!",
  ui_story_5045_50450101_44_dialog_content = "Shhhh!!!",
  ui_story_5045_50450101_45_dialog_content = "Er, aham... Estávamos apenas confirmando que PlayerName está presente hoje.",
  ui_story_5045_50450101_46_dialog_content = "O suspeito pode voltar ao seu lugar agora.",
