  ui_story_5045_50450101_50_dialog_content = "Às duas horas desta tarde, recebi um aviso do Lorde da Cidade para comparecer a uma reunião de última hora.",
  ui_story_5045_50450101_51_dialog_content = "Depois de receber este aviso, tranquei a porta do meu escritório e saí.",
  ui_story_5045_50450101_52_dialog_content = "Mas quando voltei ao meu escritório às quatro horas, notei que uma quantidade substancial de Nightium havia desaparecido.",
  ui_story_5045_50450101_53_dialog_content = "Você notou algo incomum na cena do crime?",
  ui_story_5045_50450101_54_dialog_content = "A porta e as janelas do meu escritório não mostravam sinais de arrombamento, e a porta ainda estava trancada quando voltei.",
  ui_story_5045_50450101_55_dialog_content = "Além de minhas próprias impressões digitais, a maçaneta não tinha nenhum outro vestígio.",
  ui_story_5045_50450101_55X1_dialog_content = "(Eu realmente não entendo o que está acontecendo aqui, mas Irridon parece estar falando sobre algo importante.)",
  ui_story_5045_50450101_55X2_dialog_content = "(É melhor eu anotar esses detalhes, só por precaução!)",
  ui_story_5045_50450101_56_dialog_content = "Este parece ser um roubo bastante misterioso!",
  ui_story_5045_50450101_57_dialog_content = "Você pode, por favor, dizer ao tribunal por que você suspeita PlayerName de roubar o Nightium?",
  ui_story_5045_50450101_58_dialog_content = "Porque encontrei uma carta em meu escritório, um convite que enviei pessoalmente para PlayerName.",
  ui_story_5045_50450101_59_dialog_content = "Esse convite deveria estar em PlayerNameposse de...",
  ui_story_5045_50450101_60_dialog_content = "Então, o que ele estava fazendo dentro do meu escritório trancado?",
  ui_story_5045_50450101_61_dialog_content = "O quê?!",
  ui_story_5045_50450101_62_dialog_content = "Não só isso... Alguém atestou ter visto PlayerName nas proximidades do meu escritório na época.",
  ui_story_5045_50450101_63_dialog_content = "Isso foi porque—",
  ui_story_5045_50450101_64_dialog_content = "<color=#737378>Bam, bam, bam!</color>",
  ui_story_5045_50450101_65_dialog_content = "<size=45>Silêncio! Ordem no tribunal!</size>",
  ui_story_5045_50450101_66_dialog_content = "Hmm, agora o que vem a seguir? Ah sim! Vamos agora ouvir o depoimento da testemunha, Sr. Pittman!",
  ui_story_5045_50450101_67_dialog_content = "Às duas horas da tarde, fui ver o juiz Irridon para fazer uma série de perguntas relacionadas ao trabalho...",
  ui_story_5045_50450101_68_dialog_content = "Mas ela prontamente me disse que precisava sair para uma reunião urgente e me pediu para voltar mais tarde.",
  ui_story_5045_50450101_69_dialog_content = "Por volta das três horas, voltei ao escritório dela para ver se ela havia retornado.",
  ui_story_5045_50450101_70_dialog_content = "Mas quando me aproximei de sua porta, notei a imagem fugaz de uma figura saindo do mesmo lugar.",
  ui_story_5045_50450101_71_dialog_content = "Então eu pensei comigo mesmo, isso deve ter sido PlayerName.",
  ui_story_5045_50450101_72_dialog_content = "Excelente! E agora é hora de julgar a testemunha... Você está pronto, PlayerName?",
  ui_story_5045_50450101_73_dialog_content = "E-espere, Meritíssimo! Me dê uma chance de explicar!",
