  ui_story_5045_50450101_75_dialog_content = "A-Aham, muito bem então! Você pode oferecer sua refutação agora.",
  ui_story_5045_50450101_76_dialog_content = "Mas primeiro, por favor, apresente-se ao tribunal.",
  ui_story_5045_50450101_77_dialog_content = "Meu nome é PlayerName. Eu sou um celestita.",
  ui_story_5045_50450101_78_dialog_content = "Por favor, apresente-nos o seu <color=#1875ad>ocupação</color> também.",
  ui_story_5045_50450101_79_dialog_content = "eu, eh...",
  ui_story_5045_50450101_80_option_content = "Eu sou o mascote mais adorável do Astra.",
  ui_story_5045_50450101_81_option_content = "Eu sou o Pescador Dragonwave.",
  ui_story_5045_50450101_82_option_content = "Sou um alpinista profissional.",
  ui_story_5045_50450101_83_dialog_content = "Sou o piloto designado de Soroz.",
  ui_story_5045_50450101_84_dialog_content = "Você poderia por favor elaborar?",
  ui_story_5045_50450101_85_dialog_content = "Em outras palavras, meu trabalho é...",
  ui_story_5045_50450101_86_option_content = "Para derrubar Lumopolis e sua tirania!",
  ui_story_5045_50450101_87_dialog_content = "O-O quê?! Lumopolis está prosperando sob o governo justo do Lorde da Cidade! Como você ousa revelar suas ambições movidas pelo terror para nós!!!",
  ui_story_5045_50450101_88_dialog_content = "Eu quero que você saiba que aqueles que ameaçam a paz de Lumopolis ou seu povo... passarão o resto de suas vidas na prisão!",
  ui_story_5045_50450101_89_dialog_content = "(Eu só estava brincando, mas ela parece muito séria sobre me sentenciar...)",
  ui_story_5045_50450101_90_dialog_content = "O-Oh, vamos lá! Você sabe que eu estou sempre dizendo coisas malucas assim!",
  ui_story_5045_50450101_91_option_content = "Para espalhar uma mensagem de paz e amor!",
  ui_story_5045_50450101_92_option_content = "Para salvar o mundo!",
  ui_story_5045_50450101_93_dialog_content = "Entendido. Deixe os registros mostrarem que o suspeito não está apenas desempregado, mas também tem delírios de adolescente.",
  ui_story_5045_50450101_94_dialog_content = "Diga-nos com sinceridade - onde você estava entre as duas e as quatro horas desta tarde?",
  ui_story_5045_50450101_95_dialog_content = "Estive no Tribunal de Justiça esse tempo todo.",
  ui_story_5045_50450101_96_dialog_content = "Como um celestita, por que você veio ao Lumopolis Hall of Justice?",
  ui_story_5045_50450101_96X1_dialog_content = "(Eh, p-por que eu vim para o Tribunal de Justiça de novo?)",
  ui_story_5045_50450101_96X2_dialog_content = "(Na verdade, parado aqui agora, minha mente está totalmente em branco!)",
  ui_story_5045_50450101_96X3_dialog_content = "(Felizmente, escrevi algumas notas agora. Talvez eu me lembre de algo delas...)",
  ui_story_5045_50450101_97_dialog_content = "Noite Branca no alto, pare de tentar atrapalhar os procedimentos!",
  ui_story_5045_50450101_98_dialog_content = "M-Meu mal...",
  ui_story_5045_50450101_99_dialog_content = "Bom, agora deixe-me perguntar mais uma vez.",
  ui_story_5045_50450101_100_dialog_content = "eu recebi um <color=#1875ad>convite</color> de Irridon.",
  ui_story_5045_50450101_101_dialog_content = "Ela me pediu para ir ao Tribunal de Justiça e visitá-la em seu escritório.",
  ui_story_5045_50450101_102_dialog_content = "Ela disse que queria me mostrar como é um julgamento adequado e que tinha um trabalho para mim.",
  ui_story_5045_50450101_103_dialog_content = "Cheguei aqui às duas horas, mas ninguém estava por perto para me mostrar o caminho para o escritório dela.",
  ui_story_5045_50450101_104_dialog_content = "Depois de vagar até as três horas mais ou menos, finalmente encontrei o escritório dela. Só que... ela não estava lá na hora.",
  ui_story_5045_50450101_105_dialog_content = "Foi quando eu decidi sair.",
  ui_story_5045_50450101_106_dialog_content = "Depois disso, passei o resto da tarde tomando sol na escadaria do Tribunal de Justiça. Isto é, até que alguém me trouxe para este pequeno tribunal.",
  ui_story_5045_50450101_107_dialog_content = "Oh? Isso significa que você admite ter invadido o escritório do Juiz Irridon?",
  ui_story_5045_50450101_108_dialog_content = "Eu não invadi o escritório dela! A porta estava destrancada, então entrei!",
  ui_story_5045_50450101_109_dialog_content = "Impossível. Juiz Irridon ela mesma disse que só saiu depois de trancar a porta do escritório.",
  ui_story_5045_50450101_110_dialog_content = "Sua refutação foi uma decepção completa e absoluta, PlayerName.",
  ui_story_5045_50450101_111_dialog_content = "Sua falta de emprego o deixou desesperado por dinheiro rápido, então você decidiu tirar vantagem da confiança do Juiz Irridon.",
  ui_story_5045_50450101_112_dialog_content = "Infelizmente, você esqueceu de uma coisa importante...",
  ui_story_5045_50450101_113_dialog_content = "Esta é a Sala de Justiça de Lumopolis, onde nenhum criminoso fica impune!",
  ui_story_5045_50450101_114_dialog_content = "Como juiz, eu declaro—",
  ui_story_5045_50450101_115_dialog_content = "<size=45>Que PlayerName é <color=#1875ad>culpado</color>!</size>",
  ui_story_5045_50450201_1_dialog_content = "<size=45>Que PlayerName é <color=#1875ad>culpado</color>!</size>",
  ui_story_5045_50450201_2_dialog_content = "E-espere, eu juro que não...",
  ui_story_5045_50450201_3_dialog_content = "Huh? PlayerName é culpado?",
  ui_story_5045_50450201_4_dialog_content = "Acordar bem a tempo para a melhor parte, estou vendo? Que coisa muito conveniente.",
  ui_story_5045_50450201_5_dialog_content = "Este não é o nível normal de desempenho de Angel. Ela deve estar muito nervosa hoje.",
  ui_story_5045_50450201_6_dialog_content = "Como eu disse, os plebeus não devem se tornar juízes de Lumópolis. O fardo é simplesmente grande demais para eles suportarem.",
  ui_story_5045_50450201_7_dialog_content = "Juiz Irridon, eu falhei meu <color=#1875ad>julgamento simulado</color> novamente, eu não...",
  ui_story_5045_50450201_8_dialog_content = "Espere, isso foi um <color=#1875ad>julgamento simulado</color> durante todo esse tempo?!",
  ui_story_5045_50450201_9_dialog_content = "Você é o juiz agora, Angel.",
  ui_story_5045_50450201_10_dialog_content = "Não se esqueça, você ainda não chamou a quadra para acabar.",
  ui_story_5045_50450201_11_dialog_content = "Não fique tão nervoso, Angel!",
  ui_story_5045_50450201_12_dialog_content = "Por que você não vai para a sala de descanso e tira um tempo para clarear a cabeça?",
  ui_story_5045_50450201_13_dialog_content = "Discordo. Você deve levar alguns minutos para reunir seus pensamentos e ver se há alguma contradição nas declarações que foram dadas agora.",
  ui_story_5045_50450201_14_option_content = "Tina tem razão.",
  ui_story_5045_50450201_15_dialog_content = "Realmente? Você realmente concorda comigo, PlayerName?",
  ui_story_5045_50450201_16_dialog_content = "Sim! Vá fazer uma pausa, Angel!",
  ui_story_5045_50450201_17_dialog_content = "Eu poderia usar um também, já que vocês me assustaram muito...",
  ui_story_5045_50450201_18_dialog_content = "Obrigado por suas sugestões amáveis, todos.",
  ui_story_5045_50450201_19_option_content = "Leyn está certa.",
  ui_story_5045_50450201_20_dialog_content = "Você também acha, né? Obrigado, PlayerName.",
  ui_story_5045_50450201_21_dialog_content = "Sim! Apenas mantenha a calma e organize seus pensamentos, Angel!",
  ui_story_5045_50450201_22_dialog_content = "E mesmo que seja apenas um julgamento simulado, ainda quero que todos saibam que NÃO sou um ladrão! OK?",
  ui_story_5045_50450201_23_dialog_content = "Obrigado por suas sugestões amáveis, todos.",
  ui_story_5045_50450201_24_option_content = "Vamos seguir em frente.",
  ui_story_5045_50450201_25_dialog_content = "Vocês não acham que deveriam ter me contado sobre hoje?",
  ui_story_5045_50450201_26_dialog_content = "Eu não tinha ideia do que estava acontecendo, e você me considerou culpado logo de cara... Isso foi meio confuso, sabe?",
  ui_story_5045_50450201_27_dialog_content = "Por que não esquecemos isso desta vez, Angel? Eu prometo que vou agir muito melhor da próxima vez!",
  ui_story_5045_50450201_28_dialog_content = "Não, isso não serve de jeito nenhum!",
  ui_story_5045_50450201_29_dialog_content = "(Uau. Acho que nunca vi Angel tão trabalhado antes.)",
  ui_story_5045_50450201_30_dialog_content = "(Acho que devo ficar fora disso...)",
  ui_story_5045_50450201_31_dialog_content = "Ahem... Eu me sinto muito mais composta agora.",
  ui_story_5045_50450201_32_dialog_content = "Eu estava tão preocupado em passar no julgamento simulado que me envergonhei na frente de todos.",
  ui_story_5045_50450201_33_dialog_content = "Para um juiz do Tribunal de Justiça, boas notas nunca serão tão importantes quanto descobrir a verdade em um caso.",
  ui_story_5045_50450201_34_dialog_content = "Mas mesmo que seja apenas um julgamento simulado, devemos a nós mesmos confiar em nossas decisões e nunca desistir!",
  ui_story_5045_50450201_35_dialog_content = "Direita!",
  ui_story_5045_50450201_36_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50450201_37_dialog_content = "Entraremos agora no <color=#1875ad>fase de discussão</color> do julgamento!",
  ui_story_5045_50450201_38_dialog_content = "A palavra é aberta a qualquer pessoa que queira fazer perguntas, compartilhar reflexões ou fornecer argumentos sobre o caso.",
  ui_story_5045_50450201_39_dialog_content = "Eu não sou um ladrão!",
  ui_story_5045_50450201_40_dialog_content = "Mas este convite prova que você esteve em meu escritório em algum momento hoje.",
  ui_story_5045_50450201_41_dialog_content = "Mais importante, foi você quem admitiu isso.",
  ui_story_5045_50450201_42_dialog_content = "É verdade que entrei no seu escritório, mas não levei nada comigo quando saí! Sem falar que a porta estava destrancada quando cheguei lá!",
  ui_story_5045_50450201_43_dialog_content = "Tenho certeza absoluta de que tranquei a porta antes de sair.",
  ui_story_5045_50450201_44_dialog_content = "Meu palpite é que você usou suas habilidades psíquicas para destrancar a porta e depois trancou-a novamente antes de sair.",
  ui_story_5045_50450201_45_dialog_content = "Isso não é algo que sou capaz de fazer com meus poderes!",
  ui_story_5045_50450201_46_dialog_content = "Nenhum de nós é celestita, então não podemos ter certeza se você está mentindo ou não.",
  ui_story_5045_50450201_47_dialog_content = "Você está tentando me incriminar, não é?!",
  ui_story_5045_50450201_48_dialog_content = "Objeção! Meritíssimo, PlayerName não deve ser permitido fazer ataques pessoais contra o queixoso.",
  ui_story_5045_50450201_49_dialog_content = "Isso não é justo... Vocês estão se unindo contra mim!",
  ui_story_5045_50450201_50_dialog_content = "PlayerName, você tem o direito de explicar ou questionar quaisquer detalhes ou evidências envolvidas neste caso.",
  ui_story_5045_50450201_51_dialog_content = "Mas escolha suas palavras com cuidado... Honestidade e integridade são os pilares do Hall of Justice.",
  ui_story_5045_50450201_52_dialog_content = "...",
  ui_story_5045_50450201_53_dialog_content = "Alguém mais no tribunal tem algo a discutir?",
  ui_story_5045_50450201_54_dialog_content = "A situação atual não está a seu favor, PlayerName. Você tem mais alguma coisa a dizer?",
  ui_story_5045_50450201_55_dialog_content = "(Alguma coisa não está certa.)",
  ui_story_5045_50450201_56_dialog_content = "(É verdade que entrei no escritório dela, mas tirando aquela carta convite...)",
  ui_story_5045_50450201_57_dialog_content = "(eu deveria ter deixado algum outro <color=#1875ad>vestígios</color> atrás!)",
  ui_story_5045_50450201_58_dialog_content = "E qual é exatamente o problema disso?",
  ui_story_5045_50450201_59_dialog_content = "Huh? Acho que foi a coisa errada a mencionar.",
  ui_story_5045_50450201_60_dialog_content = "(Vamos lá, pense! Fora aquela carta convite...)",
  ui_story_5045_50450201_61_dialog_content = "Irridon disse que apenas suas impressões digitais foram encontradas na maçaneta, mas isso não pode estar certo.",
  ui_story_5045_50450201_62_dialog_content = "Porque eu definitivamente virei para entrar na sala!",
  ui_story_5045_50450201_63_dialog_content = "O que significa que minhas impressões digitais também devem estar nele!",
  ui_story_5045_50450201_64_dialog_content = "Você está absolutamente correto!",
  ui_story_5045_50450201_65_dialog_content = "Acho que o verdadeiro ladrão deve ter apagado suas próprias impressões digitais para cobrir seus rastros.",
  ui_story_5045_50450201_66_dialog_content = "Mas eles não perceberam que também apagaram minhas impressões digitais!",
  ui_story_5045_50450201_67_dialog_content = "Faz sentido...",
  ui_story_5045_50450201_68_dialog_content = "Como podemos ter certeza de que não foi você quem limpou a maçaneta?",
  ui_story_5045_50450201_69_dialog_content = "(Suspiro... Parece que a única maneira de limpar meu nome é encontrar o verdadeiro ladrão.)",
  ui_story_5045_50450201_70_dialog_content = "(Espere!)",
  ui_story_5045_50450201_71_dialog_content = "(não sou o ladrão, isso é certo... Mas <color=#1875ad>o testemunho dessa pessoa</color> pode nos dar uma pista!)",
  ui_story_5045_50450201_72_dialog_content = "E qual é exatamente o problema disso?",
  ui_story_5045_50450201_73_dialog_content = "S-Desculpe, eu falei errado agora...",
  ui_story_5045_50450201_74_dialog_content = "(Apenas se acalme e pense bem...)",
  ui_story_5045_50450201_75_dialog_content = "Quando exatamente você me viu \"se esgueirando\", Pittman?",
  ui_story_5045_50450201_76_dialog_content = "Por volta das três horas.",
  ui_story_5045_50450201_77_dialog_content = "Você pode ser mais específico sobre o tempo?",
  ui_story_5045_50450201_78_dialog_content = "Eu acho... Deve ter passado dez minutos da hora ou algo assim.",
  ui_story_5045_50450201_79_dialog_content = "Isso é estranho, considerando que saí do escritório pouco antes de o relógio dar três horas - então, como exatamente você me viu lá?",
  ui_story_5045_50450201_80_dialog_content = "Devo mencionar que o relógio deu três horas logo depois que saí do Tribunal de Justiça.",
  ui_story_5045_50450201_81_dialog_content = "Os guardas que estavam estacionados do lado de fora podem atestar isso.",
  ui_story_5045_50450201_82_dialog_content = "Th-Isto...",
  ui_story_5045_50450201_83_dialog_content = "Não tenho certeza, mas é possível que a figura que vi seja o verdadeiro ladrão.",
  ui_story_5045_50450201_84_dialog_content = "O que significaria que era outra pessoa e não eu! Certo, Pittman?",
  ui_story_5045_50450201_85_dialog_content = "Isso parece ser o caso, sim.",
  ui_story_5045_50450201_86_dialog_content = "Então você vê, Meritíssimo, Pittman não tem como confirmar que a figura que ele viu se esgueirando era realmente eu.",
  ui_story_5045_50450201_87_dialog_content = "Como tal, sua acusação deve ser desconsiderada!",
  ui_story_5045_50450201_88_dialog_content = "Parece que é assim...",
  ui_story_5045_50450201_89_dialog_content = "Mas isso não significa que você se livrou de qualquer suspeita.",
  ui_story_5045_50450201_90_dialog_content = "Por que não tentamos ver as coisas de maneira um pouco diferente? Vamos supor que eu não seja o ladrão; ao fazer isso, você pode ver claramente muitos problemas com o caso.",
  ui_story_5045_50450201_91_dialog_content = "Em primeiro lugar, como o ladrão conseguiu abrir a porta? É possível que eles tivessem uma chave extra?",
  ui_story_5045_50450201_92_dialog_content = "...",
  ui_story_5045_50450201_93_dialog_content = "Em segundo lugar, por que o ladrão se daria ao trabalho de limpar suas impressões digitais?",
  ui_story_5045_50450201_94_dialog_content = "Faria sentido se fosse alguém associado ao Hall of Justice, já que tudo o que seria necessário para expô-lo seria uma investigação rápida.",
  ui_story_5045_50450201_95_dialog_content = "...",
  ui_story_5045_50450201_96_dialog_content = "Nos digam, Pittman, é possível que você seja o ladrão?",
  ui_story_5045_50450201_97_dialog_content = "H-Como pode ser isso?",
  ui_story_5045_50450201_98_dialog_content = "Afinal, você é o subordinado de maior confiança de Irridon. Se alguém sabe que ela deixou Nightium no escritório, é você.",
  ui_story_5045_50450201_99_dialog_content = "Não só isso, mas você também viu Irridon deixar seu escritório, que teria sido o momento perfeito para pegar uma chave reserva e entrar.",
  ui_story_5045_50450201_100_dialog_content = "Mas foi só depois que você saiu com o Nightium que você percebeu. Suas impressões digitais ainda estavam na maçaneta!",
  ui_story_5045_50450201_101_dialog_content = "Foi quando você voltou correndo para limpá-los e trancou a porta novamente, fazendo parecer que o dinheiro havia desaparecido.",
  ui_story_5045_50450201_102_dialog_content = "O que você não sabia é que você também me arrastou para o seu crime!",
  ui_story_5045_50450201_103_dialog_content = "Então quando você viu isso Irridon suspeitou que eu roubei o Nightium dela, você tomou a iniciativa e tentou me fazer cair por você!",
  ui_story_5045_50450201_104_dialog_content = "Isso tudo é apenas especulação selvagem, nada mais! Você tem alguma prova?!",
  ui_story_5045_50450201_105_dialog_content = "É verdade que estou assumindo muitas coisas aqui. Mas deixa eu te perguntar uma coisa! Quando toquei em todos esses pontos...",
  ui_story_5045_50450201_106_dialog_content = "Por que de repente você começou a suar tanto? Além disso, por que você continua alcançando seu <color=#1875ad>bolso</color> a cada poucos segundos?",
  ui_story_5045_50450201_107_dialog_content = "Será que você realmente tem uma chave reserva do escritório de Irridon aí?",
  ui_story_5045_50450201_108_dialog_content = "Senhor. Pittman, por favor, mostre ao tribunal o que você tem no bolso.",
  ui_story_5045_50450201_109_dialog_content = "...",
  ui_story_5045_50450201_110_dialog_content = "Acho que não tenho escolha.",
  ui_story_5045_50450201_111_dialog_content = "Esta chave é uma cópia exata da chave do meu escritório!",
  ui_story_5045_50450201_112_dialog_content = "Senhor. Pittman, você é acusado de roubar o Nightium do Juiz Irridon. Você tem algo a dizer para si mesmo?",
  ui_story_5045_50450201_113_dialog_content = "Eu... eu não. Não tenho nada a dizer.",
  ui_story_5045_50450201_114_dialog_content = "Se for esse o caso, então eu declaro—",
  ui_story_5045_50450201_115_dialog_content = "<size=45>Pittman é <color=#1875ad>culpado</color> deste crime!</size>",
  ui_story_5045_50450201_116_dialog_content = "Ufa... Ainda bem que acabou.",
  ui_story_5045_50450201_117_dialog_content = "Eu só sabia que iria falhar no meu julgamento simulado...",
  ui_story_5045_50450201_118_dialog_content = "Não há necessidade de se sentir desanimado, Angel. Haverá mais oportunidades no futuro.",
  ui_story_5045_50450201_119_dialog_content = "Seus veteranos aqui não eram diferentes. Eles só se tornaram juízes depois de passar por inúmeros julgamentos e avaliações simuladas.",
  ui_story_5045_50450201_120_dialog_content = "É verdade. Na verdade, falhei em mais julgamentos simulados do que qualquer outra pessoa na história do Tribunal de Justiça!",
  ui_story_5045_50450201_121_dialog_content = "Não se deixe enganar pela empolgação de Leyn, Angel. Isso não é realmente algo para se orgulhar.",
  ui_story_5045_50450201_122_dialog_content = "Perdoe-me, juiz Irridon, mas eu discordo. Se você se lembra corretamente, passei na minha avaliação na minha primeira tentativa!",
  ui_story_5045_50450201_123_dialog_content = "Sim, parece que me lembro agora. Enquanto estamos no assunto, Matthieu...",
  ui_story_5045_50450201_124_dialog_content = "Como Loewe esteve de licença recentemente, Angel trabalhará com você como seu assistente nos próximos dias. Acho que ela poderia aprender muito com você.",
  ui_story_5045_50450201_125_dialog_content = "Com minha inteligência e talento, dificilmente acho que preciso de um assistente, Juiz Irridon!",
  ui_story_5045_50450201_126_dialog_content = "Você não acha que nossos melhores juízes têm a responsabilidade de treinar nossas gerações futuras para serem igualmente exemplares?",
  ui_story_5045_50450201_127_dialog_content = "Eu vejo agora...",
  ui_story_5045_50450201_128_dialog_content = "Você não poderia estar mais certo, juiz Irridon!",
  ui_story_5045_50450201_129_dialog_content = "Como um dos maiores juízes que já agraciou o Tribunal de Justiça, juro atender às suas expectativas e passar todo o meu conhecimento ao meu novo aprendiz!",
  ui_story_5045_50450201_130_dialog_content = "Apenas tente não esperar muito dela... Afinal, poucos se comparam à minha grandeza!",
  ui_story_5045_50450201_131_dialog_content = "<size=32>Mas eu quero ser a assistente do Sr. Pittman!</size>",
  ui_story_5045_50450301_1_dialog_content = "<color=#737378>Hora: 20:00</color>",
  ui_story_5045_50450301_2_dialog_content = "<color=#737378>Local: Lumo Hall of Justice</color>",
  ui_story_5045_50450301_3_dialog_content = "Eu realmente não tinha ideia de que você, de todas as pessoas, seria o único a desvendar este caso.",
  ui_story_5045_50450301_4_dialog_content = "Foi pura sorte, na verdade...",
  ui_story_5045_50450301_5_dialog_content = "(Honestamente, o desempenho convincente de Pittman foi o que realmente me salvou.)",
  ui_story_5045_50450301_6_dialog_content = "Ei, Irridon? Algo me diz que o julgamento simulado de hoje foi baseado em um caso real de roubo.",
  ui_story_5045_50450301_7_dialog_content = "De fato foi. Ainda outra suposição astuta, PlayerName.",
  ui_story_5045_50450301_8_dialog_content = "Também sei que você só me enviou aquela carta para me envolver nessa história toda!",
  ui_story_5045_50450301_9_dialog_content = "Sabe, se tivesse me dito que era para um julgamento simulado, eu poderia ter sido mais útil.",
  ui_story_5045_50450301_10_dialog_content = "Em um julgamento real, situações inesperadas surgem o tempo todo.",
  ui_story_5045_50450301_11_dialog_content = "Simplesmente queríamos introduzir algumas variáveis independentes no julgamento simulado.",
  ui_story_5045_50450301_12_dialog_content = "No entanto, foi apenas graças a você que Angel foi capaz de levar o julgamento a uma conclusão satisfatória.",
  ui_story_5045_50450301_13_dialog_content = "Entendo... Acho que isso me torna uma variável bastante confiável, hein?",
  ui_story_5045_50450301_14_dialog_content = "De fato. Seus poderes de observação são incrivelmente aguçados.",
  ui_story_5045_50450301_15_dialog_content = "Na verdade, e digo isso sem exagero, mas seu desempenho hoje esteve no mesmo nível de muitos de nossos jurados em suas avaliações.",
  ui_story_5045_50450301_16_dialog_content = "Se ao menos tivéssemos mais pessoas como você aqui no Tribunal de Justiça.",
  ui_story_5045_50450301_17_dialog_content = "Mas o suficiente sobre isso.",
  ui_story_5045_50450301_18_dialog_content = "Gostaríamos de compensá-lo por sua ajuda hoje. Considere isso um sinal de gratidão de todos nós no Tribunal de Justiça.",
  ui_story_5045_50450301_19_dialog_content = "Compensar-me?",
  ui_story_5045_50450301_20_dialog_content = "Aqui está você: os bens roubados do julgamento simulado de hoje.",
  ui_story_5045_50450301_21_dialog_content = "Uau, pensei que este Nightium estava apenas sendo usado como um suporte para o julgamento.",
  ui_story_5045_50450301_22_dialog_content = "Você está realmente me dando isso?",
  ui_story_5045_50450301_23_dialog_content = "Por que? É muito pouco?",
  ui_story_5045_50450301_24_dialog_content = "NN-De jeito nenhum! É mais do que suficiente!",
  ui_story_5045_50450301_25_dialog_content = "Na verdade, sinta-se à vontade para me ligar sempre que tiver mais trabalhos como este!",
  ui_story_5045_50450301_26_dialog_content = "Realmente? Não fazia ideia de que estavas tão interessado em trabalhar para o Tribunal de Justiça, PlayerName...",
  ui_story_5045_50450301_27_dialog_content = "Quero dizer, tirando o choque inicial...",
  ui_story_5045_50450301_28_dialog_content = "Na verdade, achei o trabalho bem interessante!",
  ui_story_5045_50450301_29_dialog_content = "Ouvir você dizer isso me traz muita alegria.",
  ui_story_5045_50450301_30_dialog_content = "Diga-me, você gostaria de passar algum tempo aqui e trabalhar conosco?",
  ui_story_5045_50450301_31_dialog_content = "Veja bem, recentemente estabeleci um novo departamento no Hall of Justice, e poderíamos usar alguém com habilidades interpessoais como as suas.",
  ui_story_5045_50450301_32_dialog_content = "Um novo departamento?",
  ui_story_5045_50450301_33_dialog_content = "Afinal, parece que você está interessado. Nesse caso, aceite isso. Você vai precisar dele em breve.",
  ui_story_5045_50450301_34_dialog_content = "Isso é um<color=#1875ad> Caderno do Juiz</color>?",
  ui_story_5045_50450301_35_dialog_content = "Deste dia em diante, você é um <color=#1875ad>juiz estagiário</color> da Sala de Justiça.",
  ui_story_5045_50450301_36_dialog_content = "<color=#737378>Hora: 8h00</color>",
  ui_story_5045_50450301_37_dialog_content = "<color=#737378>Localização: Um escritório no Lumo Hall of Justice</color>",
  ui_story_5045_50450301_38_dialog_content = "É este o lugar onde Irridon me disse para relatar?",
  ui_story_5045_50450301_39_dialog_content = "Bom Dia a todos! Como posso ajudar-",
  ui_story_5045_50450301_40_dialog_content = "Que raio de caso é este?!",
  ui_story_5045_50450301_41_dialog_content = "O autor está certo, mas o réu também...",
  ui_story_5045_50450301_42_dialog_content = "Não vejo nenhuma lei ou precedente legal que se aplique a este caso. Em quem devo acreditar aqui?!",
  ui_story_5045_50450301_43_dialog_content = "Zzz...",
  ui_story_5045_50450301_44_dialog_content = "Dê uma boa olhada, Angel.",
  ui_story_5045_50450301_45_dialog_content = "É por isso que você está estudando comigo, e não com um daqueles dois juízes inúteis.",
  ui_story_5045_50450301_46_dialog_content = "Mas senhor, até onde eu sei, suas notas não são muito melhores que as deles...",
  ui_story_5045_50450301_47_dialog_content = "<size=32>Isso explicaria por que você foi designado para um departamento menor junto com eles...</size>",
  ui_story_5045_50450301_48_dialog_content = "Meu Deus. Você é ainda pior do que Loewe, não é?!",
  ui_story_5045_50450301_49_dialog_content = "Permita-me repetir: escolhi me transferir para este departamento por puro interesse e meu enorme senso de dever!",
  ui_story_5045_50450301_50_dialog_content = "Agora, a menos que você queira continuar falhando em suas avaliações, sugiro que reúna suas coisas e venha rapidamente.",
  ui_story_5045_50450301_51_dialog_content = "Sim...",
  ui_story_5045_50450301_52_dialog_content = "Hum? Por que se não é PlayerName! O que o traz à porta do <color=#1875ad>Divisão Romance do Hall da Justiça</color> hoje?",
  ui_story_5045_50450301_53_dialog_content = "Uau, eles até deram a vocês um escritório tão legal para a Divisão de Romance...",
  ui_story_5045_50450301_54_dialog_content = "Legal, você diz? Ha!",
  ui_story_5045_50450301_55_dialog_content = "Espere até que eu seja o Juiz Chefe da Divisão de Romance, então você verá um cargo verdadeiramente digno de um nobre como eu!",
  ui_story_5045_50450301_56_dialog_content = "Juiz Chefe da Divisão Romance?",
  ui_story_5045_50450301_57_dialog_content = "Sim, e você faria bem em sair do meu caminho agora!",
  ui_story_5045_50450301_58_dialog_content = "...",
  ui_story_5045_50450301_59_dialog_content = "Suspiro... Desde que a Divisão de Romance foi estabelecida, a posição do Juiz Chefe continuou girando entre diferentes pessoas. Enquanto isso, nosso acúmulo de casos só fica maior e maior.",
  ui_story_5045_50450301_60_dialog_content = "Do jeito que está, ninguém está disposto a servir como Juiz Chefe da Divisão Romance.",
  ui_story_5045_50450301_61_dialog_content = "... Com exceção dos meus veteranos aqui, é claro. Eles estão fazendo tudo ao seu alcance para serem promovidos a Juiz Chefe.",
  ui_story_5045_50450301_62_dialog_content = "<size=45>Não me deixe esperando, Angel!!</size>",
  ui_story_5045_50450301_63_dialog_content = "Suspiro... Bem, boa sorte, PlayerName!",
  ui_story_5045_50450301_64_dialog_content = "Eu pensei que o novo departamento Irridon mencionado antes era especificamente para julgamentos simulados.",
  ui_story_5045_50450301_65_dialog_content = "O que diabos é uma Divisão Romance...?",
  ui_story_5045_50450301_66_dialog_content = "PlayerName?",
  ui_story_5045_50450301_67_dialog_content = "Então você é o mais novo membro da Divisão Romance, hein?",
  ui_story_5045_50450301_68_option_content = "Acho que houve um engano.",
  ui_story_5045_50450301_69_dialog_content = "Juiz Irridon pedi para você nos ajudar, certo?",
  ui_story_5045_50450301_70_dialog_content = "Isso mesmo.",
  ui_story_5045_50450301_71_dialog_content = "Então, por que haveria um erro? Este é o juiz Irridon afinal, estamos falando.",
  ui_story_5045_50450301_72_dialog_content = "Então você é o mais novo membro da Divisão Romance!",
  ui_story_5045_50450301_73_option_content = "Espero não piorar as coisas.",
  ui_story_5045_50450301_74_dialog_content = "Você é muito modesto.",
  ui_story_5045_50450301_75_dialog_content = "Juiz Irridon escolheu pessoalmente você como nosso mais novo membro. Tenho certeza que poderemos aprender muito com você!",
  ui_story_5045_50450301_76_option_content = "Bem, que bom que você está aqui.",
  ui_story_5045_50450301_77_dialog_content = "Ter alguém tão confiável quanto você na equipe realmente me deixa tranquilo.",
  ui_story_5045_50450301_78_dialog_content = "Estou ansioso para aprender com você!",
  ui_story_5045_50450301_79_dialog_content = "D-Não espere muito! Faz muito tempo que não trabalho na Divisão de Romance. Eu ainda sou bastante novo nisso também.",
  ui_story_5045_50450301_80_dialog_content = "Zzz...",
  ui_story_5045_50450301_81_dialog_content = "Quem está aqui?",
  ui_story_5045_50450301_82_dialog_content = "Ei, é o nosso principal suspeito do julgamento simulado de ontem! Prazer em vê-lo novamente, PlayerName!",
  ui_story_5045_50450301_83_dialog_content = "Embora se você está aqui, isso deve significar que você está tendo sérios problemas de relacionamento?",
  ui_story_5045_50450301_84_dialog_content = "Basta enviar uma reclamação formal com todos os detalhes de sua contestação e resolveremos o problema! Bocejar-",
  ui_story_5045_50450301_85_option_content = "Eu não tenho esses tipos de problemas!",
  ui_story_5045_50450301_86_dialog_content = "Oh? Você parece bastante confiante em si mesmo.",
  ui_story_5045_50450301_87_dialog_content = "É porque você é secretamente um PUA? Ou talvez você seja um daqueles nerds de coração de ferro?",
  ui_story_5045_50450301_88_dialog_content = "N-Nenhuma das opções acima! Estou aqui para ajudar vocês!",
  ui_story_5045_50450301_89_dialog_content = "Ah, então você é o cara novo! Bem-vindo bem vindo!",
  ui_story_5045_50450301_90_option_content = "Desculpe por te acordar.",
  ui_story_5045_50450301_91_dialog_content = "Uau. Esta é a primeira vez que alguém realmente se desculpa por me acordar! Estou tão tocada...",
  ui_story_5045_50450301_92_dialog_content = "Brincadeira, não me importo nem um pouco! Além disso, eu deveria estar acordado agora, já que temos um novo membro entrando em nosso departamento hoje.",
  ui_story_5045_50450301_93_dialog_content = "Esse novo membro... Tenho certeza que sou eu.",
  ui_story_5045_50450301_94_dialog_content = "Ah, então você é o cara novo! Bem-vindo bem vindo!",
  ui_story_5045_50450301_95_option_content = "Estou aqui para ajudar.",
  ui_story_5045_50450301_96_dialog_content = "Embora eu ainda não tenha ideia de como vou fazer isso...",
  ui_story_5045_50450301_97_dialog_content = "Uau. Então você é a nova adição promissora à nossa equipe! Você não tem ideia do quanto eu esperei por isso!",
  ui_story_5045_50450301_98_dialog_content = "Na verdade, eu até sonhei ontem à noite que você veio para a Divisão de Romance, PlayerName! Nunca pensei que meu sonho se tornaria realidade!",
  ui_story_5045_50450301_99_dialog_content = "Sempre digo às pessoas que não há nada de errado em dormir e sonhar um pouco mais do que o normal, e é exatamente por isso!",
  ui_story_5045_50450301_100_dialog_content = "E com a sua ajuda, PlayerName... Posso até ser promovido a Juiz Chefe!",
  ui_story_5045_50450301_101_dialog_content = "Do que você tá falando, Tina?",
  ui_story_5045_50450301_102_dialog_content = "Huh? Você quer dizer que ainda não percebeu, Leyn?",
  ui_story_5045_50450301_103_dialog_content = "Ninguém quer servir como Juiz Chefe de um departamento tão estranho e complicado como o nosso agora...",
  ui_story_5045_50450301_104_dialog_content = "É por isso que Matthieu está com tanta pressa para começar esses casos enquanto o cargo ainda está vago.",
  ui_story_5045_50450301_105_dialog_content = "Ele acha que, ao fazer isso, o juiz Irridon pode considerar nomeá-lo como chefe de nosso departamento!",
  ui_story_5045_50450301_106_dialog_content = "Matthieu? Como Juiz Chefe da Divisão Romance?!",
  ui_story_5045_50450301_107_dialog_content = "Isso mesmo. Você pode imaginar como seria nossa vida se eu tivesse sucesso, não é? É por isso que estaríamos melhor comigo no comando!",
  ui_story_5045_50450301_108_dialog_content = "Eu não me importaria se você fosse escolhido como Juiz Chefe, Leyn.",
  ui_story_5045_50450301_109_dialog_content = "Só me preocupo que, com você no comando, os outros departamentos possam desprezar ainda mais a Divisão Romance.",
  ui_story_5045_50450301_110_dialog_content = "Eles podem me menosprezar o quanto quiserem, mas não a Divisão Romance!",
  ui_story_5045_50450301_111_dialog_content = "Se eu for nomeado juiz-chefe do nosso departamento, juro que farei tudo ao meu alcance para obter o respeito que merecemos!",
  ui_story_5045_50450301_112_dialog_content = "Hmm... Parece que você também está de olho na posição, Leyn.",
  ui_story_5045_50450301_113_dialog_content = "Bom! Uma pequena competição amigável nos motivará a trabalhar ainda mais!",
  ui_story_5045_50450301_114_dialog_content = "Estarei contando com você, PlayerName!",
  ui_story_5045_50450301_115_dialog_content = "Ei, o que isso quer dizer? PlayerName está aqui para ajudar todo o nosso departamento! Você não pode simplesmente tê-lo só para você!",
  ui_story_5045_50450301_116_dialog_content = "Oh? Mas eu pensei que você não gostasse de trabalhar com os outros, Leyn?",
  ui_story_5045_50450301_117_dialog_content = "Ou será que você está sentindo um pouco de inveja?",
  ui_story_5045_50450301_118_dialog_content = "Eu me pergunto, você está com ciúmes de mim porque eu tenho PlayerName do meu lado, ou você está com ciúmes de PlayerName porque ele começa a trabalhar comigo?",
  ui_story_5045_50450301_119_dialog_content = "Só estou preocupado que você coloque muito estresse em PlayerName, isso é tudo.",
  ui_story_5045_50450301_120_dialog_content = "Temos muito em nosso prato e, como você só pode trabalhar por um curto período de tempo ... Espere, você não está planejando impingir sua carga de trabalho a PlayerName, você é?!",
  ui_story_5045_50450301_121_dialog_content = "Oh meu Deus, eu não tinha ideia de que você poderia ser tão solidário com outras pessoas.",
  ui_story_5045_50450301_122_dialog_content = "De qualquer forma, você precisará encontrar uma solução mais sustentável para o seu problema.",
  ui_story_5045_50450301_123_dialog_content = "Eu tenho uma ideia!",
  ui_story_5045_50450301_124_dialog_content = "Por que não deixamos PlayerName decidir com quem ele quer trabalhar?",
  ui_story_5045_50450301_125_dialog_content = "Eu vejo. Isso soa justo o suficiente para mim.",
  ui_story_5045_50450301_126_dialog_content = "O que você acha, PlayerName?",
  ui_story_5045_50450301_127_dialog_content = "Acho que não posso fazer esse tipo de escolha agora.",
  ui_story_5045_50450301_128_dialog_content = "Então não pense tanto nisso! Você estaria muito melhor como meu assistente, sabia? Posso até pagar a mais, se necessário!",
  ui_story_5045_50450301_129_dialog_content = "Th-Isso não é...",
  ui_story_5045_50450301_130_dialog_content = "Posso não ter dinheiro para comprar seus serviços como algumas pessoas, mas garanto que seu trabalho não será explorado se você decidir trabalhar para mim.",
  ui_story_5045_50450301_131_dialog_content = "Eu fico com a maior parte do trabalho; tudo o que você precisa fazer é me oferecer uma nova perspectiva de vez em quando e me lembrar de ser justo o tempo todo!",
  ui_story_5045_50450301_132_dialog_content = "(Ambos parecem realmente desesperados por minha ajuda...)",
  ui_story_5045_50450301_133_dialog_content = "(O que devo fazer?!)",
  ui_story_5045_50450301_134_option_content = "Escolha Leyn",
  ui_story_5045_50450301_135_dialog_content = "Para ser sincero, não tenho ideia de como ajudar vocês no Tribunal de Justiça.",
  ui_story_5045_50450301_136_dialog_content = "Mas se o que Leyn diz é verdade, acho que posso lidar com esse tipo de trabalho.",
  ui_story_5045_50450301_137_dialog_content = "Tenho certeza que você vai se sair bem!",
  ui_story_5045_50450301_138_option_content = "Escolha Tina",
  ui_story_5045_50450301_139_dialog_content = "Bem, desde Tina realmente precisa de ajuda agora, acho que posso tentar.",
  ui_story_5045_50450301_140_dialog_content = "Aviso justo, embora! Eu tenho quase zero conhecimento de qualquer uma dessas coisas!",
  ui_story_5045_50450301_141_dialog_content = "Não se preocupe. Com certeza vou ensinar tudo o que sei... Bocejo—",
  ui_story_5045_50450301_142_dialog_content = "Mas primeiro, uma soneca rápida.",
  ui_story_5045_50450301_143_option_content = "Não escolha nenhum",
  ui_story_5045_50450301_144_dialog_content = "Vocês disseram que sou o mais novo membro da Divisão Romance, certo? Então, o que me impede de competir com vocês pelo cargo de Juiz Chefe?",
  ui_story_5045_50450301_145_dialog_content = "Quando você coloca dessa forma, acho que você está livre para fazer isso também! Mas você precisará se tornar um juiz de verdade primeiro.",
  ui_story_5045_50450301_146_dialog_content = "Você sabe, Tina, se PlayerName está confiante o suficiente para dizer algo assim, acho que devemos oferecer todo o nosso apoio.",
  ui_story_5045_50450301_147_dialog_content = "Quem sabe? Ele pode até voar durante o treinamento e se tornar um juiz em pouco tempo, assim como Matthieu!",
  ui_story_5045_50450301_148_dialog_content = "Parece bom para mim... Bocejo...",
  ui_story_5045_50450401_1_dialog_content = "<color=#737378>Hora: 18:00</color>",
  ui_story_5045_50450401_2_dialog_content = "<color=#737378>Localização: Lumo Hall of Justice, Escritório da Divisão Romance</color>",
  ui_story_5045_50450401_3_dialog_content = "Então, há algo mais em que eu possa ajudar, Leyn?",
  ui_story_5045_50450401_4_dialog_content = "Oh, apenas reúna o resto dessas declarações e isso deve ser o suficiente.",
  ui_story_5045_50450401_5_dialog_content = "Eu posso cuidar do resto.",
  ui_story_5045_50450401_6_dialog_content = "Embora agora você deva estar se preparando para ir para casa passar o dia.",
  ui_story_5045_50450401_7_dialog_content = "E você?",
  ui_story_5045_50450401_8_dialog_content = "Recebemos mais uma centena de reclamações hoje que ainda precisam ser analisadas.",
  ui_story_5045_50450401_9_dialog_content = "Feito isso, preciso pegar as reclamações de materiais faltantes e enviá-los de volta para reenvio.",
  ui_story_5045_50450401_10_dialog_content = "Mas já é tão tarde... Você vai mesmo ficar para fazer tudo isso?",
  ui_story_5045_50450401_11_dialog_content = "Para dizer a verdade... Os casos tratados pela Divisão de Romance são todos muito difíceis de entender para mim.",
  ui_story_5045_50450401_12_dialog_content = "Preciso reservar um tempo para estudá-los e aprender a julgá-los da melhor maneira possível.",
  ui_story_5045_50450401_13_dialog_content = "Entendo... Mas pelo que posso dizer, você já marcou todos eles para reenvio. Por que isso?",
  ui_story_5045_50450401_14_dialog_content = "De acordo com as disposições correspondentes recentemente alteradas de Lumopolis, até agora, todos os casos que lidei tiveram alguns problemas.",
  ui_story_5045_50450401_15_dialog_content = "Estou apenas seguindo as regras, só isso.",
  ui_story_5045_50450401_16_dialog_content = "Mas nesse ritmo, você nunca conseguirá fechar um único caso!",
  ui_story_5045_50450401_17_dialog_content = "Heh... Você parece estar com mais pressa do que eu.",
  ui_story_5045_50450401_18_dialog_content = "Bem, obviamente! Somos parceiros, não somos?",
  ui_story_5045_50450401_19_dialog_content = "Parceiros...?",
  ui_story_5045_50450401_20_dialog_content = "Exatamente!",
  ui_story_5045_50450401_21_dialog_content = "Agradeço sua preocupação, de verdade, mas jurei que não tiraria proveito de seu trabalho.",
  ui_story_5045_50450401_22_dialog_content = "Tudo bem... Então vamos sair um pouco, ok? Parece que você precisa de uma pausa rápida.",
  ui_story_5045_50450401_23_dialog_content = "Claro. Além disso, eu estava querendo te perguntar uma coisa, PlayerName.",
  ui_story_5045_50450401_24_dialog_content = "Você sabe o que é amor?",
  ui_story_5045_50450401_25_dialog_content = "Eu amo?",
  ui_story_5045_50450401_26_option_content = "Isso.",
  ui_story_5045_50450401_27_dialog_content = "É quando duas pessoas se gostam tanto que estão dispostas a passar o resto da vida juntas, certo?",
  ui_story_5045_50450401_28_dialog_content = "Devo dizer que sua compreensão do mundo realmente me impressiona às vezes, PlayerName!",
  ui_story_5045_50450401_29_dialog_content = "Eu só estou supondo, realmente...",
  ui_story_5045_50450401_30_option_content = "Na verdade não...",
  ui_story_5045_50450401_31_dialog_content = "Mas já li sobre o amor em muitas histórias!",
  ui_story_5045_50450401_32_dialog_content = "A julgar por suas descrições, o amor é algo realmente misterioso.",
  ui_story_5045_50450401_33_dialog_content = "Então você é um fã de histórias de amor, PlayerName? Parece que estou perguntando para a pessoa certa.",
  ui_story_5045_50450401_34_dialog_content = "Eu não diria que sou fã nem nada...",
  ui_story_5045_50450401_35_option_content = "Eu não vou contar!",
  ui_story_5045_50450401_36_dialog_content = "É segredo, e não vou contar!",
  ui_story_5045_50450401_37_dialog_content = "H-Que misterioso da sua parte...",
  ui_story_5045_50450401_38_dialog_content = "Você também é muito popular, não é? Leyn?",
  ui_story_5045_50450401_39_dialog_content = "Você provavelmente sabe mais sobre o amor do que eu, certo?",
  ui_story_5045_50450401_40_dialog_content = "Bom...",
  ui_story_5045_50450401_41_dialog_content = "Suponho que seja verdade que fui objeto de afeição por mais do que algumas senhoras.",
  ui_story_5045_50450401_42_dialog_content = "Mas, infelizmente, nunca fui capaz de retribuir seus sentimentos.",
  ui_story_5045_50450401_43_dialog_content = "Hã? Por quê?",
  ui_story_5045_50450401_44_dialog_content = "Não sei. Nunca pensei muito nisso, para ser honesto.",
  ui_story_5045_50450401_45_dialog_content = "Mas quando fui designado para a Divisão de Romance do Hall of Justice e encarregado de ajudar os casais a resolver suas disputas.",
  ui_story_5045_50450401_46_dialog_content = "Foi quando percebi que não sei nada sobre o amor.",
  ui_story_5045_50450401_47_dialog_content = "Eu até comecei a duvidar se eu já havia sentido amor antes na minha vida...",
  ui_story_5045_50450401_48_dialog_content = "Estou realmente apto para trabalhar como juiz na Divisão Romance?",
  ui_story_5045_50450401_49_dialog_content = "Claro que você é!",
  ui_story_5045_50450401_50_dialog_content = "O que te dá tanta certeza disso?",
  ui_story_5045_50450401_51_dialog_content = "Um juiz não precisa roubar para julgar um ladrão, certo?",
  ui_story_5045_50450401_52_dialog_content = "Tenho certeza de que o mesmo vale para resolver problemas de relacionamento!",
  ui_story_5045_50450401_53_dialog_content = "Isso parece meio forçado...",
  ui_story_5045_50450401_54_dialog_content = "Mas de certa forma, faz todo o sentido!",
  ui_story_5045_50450401_55_dialog_content = "Ficar olhando para essas reclamações o dia todo não vai te levar muito longe. O que mais importa é aprender com a prática!",
  ui_story_5045_50450401_56_dialog_content = "Você deve tentar sua mão em alguns casos e construir sua experiência primeiro. O resto deve vir rápido o suficiente!",
  ui_story_5045_50450401_57_dialog_content = "Você está certo... Não acredito que ando tão indeciso ultimamente!",
  ui_story_5045_50450401_58_dialog_content = "Eu deveria começar com o primeiro caso na minha frente!",
  ui_story_5045_50450401_59_dialog_content = "\"O reclamante, <color=#1875ad>farrel</color>, exige que o arguido, <color=#1875ad>sophia</color>, case-se com ele de acordo com a lei...\"",
  ui_story_5045_50450401_60_dialog_content = "I-Isto é algum tipo de pedido... Talvez você deva começar com algo um pouco menos complicado?",
  ui_story_5045_50450401_61_dialog_content = "Não precisa.",
  ui_story_5045_50450401_62_dialog_content = "Como juiz, é minha responsabilidade abordar cada um desses casos com o melhor de minhas habilidades.",
  ui_story_5045_50450401_63_dialog_content = "Não apenas isso...",
  ui_story_5045_50450401_64_dialog_content = "Percebo que é um desperdício de seu talento pedir que me ajude a organizar a reclamação.",
  ui_story_5045_50450401_65_dialog_content = "A partir de amanhã, você e eu ouviremos cada um desses casos juntos.",
  ui_story_5045_50450401_66_dialog_content = "H-Huh? Você tem certeza sobre isso?",
  ui_story_5045_50450401_67_dialog_content = "Claro. Você mesmo disse: somos sócios, certo?",
  ui_story_5045_50450501_1_dialog_content = "<color=#737378>Hora: 9:00 AM</color>",
  ui_story_5045_50450501_2_dialog_content = "<color=#737378>Local: Lumo Hall of Justice, Tribunal</color>",
  ui_story_5045_50450501_3_dialog_content = "Olhe para lá! Isso é Leyn!",
  ui_story_5045_50450501_4_dialog_content = "...",
  ui_story_5045_50450501_5_dialog_content = "(Parece que muitas senhoras na platéia vieram só para ver Leyn?)",
  ui_story_5045_50450501_6_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50450501_7_dialog_content = "<size=45>Noite Branca no alto. Tribunal está agora em sessão!</size>",
  ui_story_5045_50450501_8_dialog_content = "Avante, Noite Branca!",
  ui_story_5045_50450501_9_dialog_content = "...",
  ui_story_5045_50450501_10_dialog_content = "Você sabe quem deve ser abordado primeiro pelo tribunal, PlayerName?",
  ui_story_5045_50450501_11_dialog_content = "Hmm... Tenho quase certeza de que é o autor...",
  ui_story_5045_50450501_12_option_content = "farrel",
  ui_story_5045_50450501_13_dialog_content = "Isso mesmo! Fico feliz em ver que você se lembra!",
  ui_story_5045_50450501_14_option_content = "sophia",
  ui_story_5045_50450501_15_dialog_content = "O autor é Farrell.",
  ui_story_5045_50450501_16_dialog_content = "A diferenciação entre o autor e o réu é uma das partes mais básicas do trabalho. Você deve se lembrar disso no futuro.",
  ui_story_5045_50450501_17_dialog_content = "(Cara... Como eu entendi errado?)",
  ui_story_5045_50450501_18_dialog_content = "(Tenho que me certificar de fazer anotações melhores sobre tudo da próxima vez!)",
  ui_story_5045_50450501_19_dialog_content = "O queixoso pode dirigir-se ao tribunal?",
  ui_story_5045_50450501_20_dialog_content = "Bom dia, Excelência. Meu nome é Farrel.",
  ui_story_5045_50450501_21_dialog_content = "O reclamante é um <color=#1875ad>cavaleiro</color> de Lumópolis, né? Isso é inesperado...",
  ui_story_5045_50450501_22_dialog_content = "Cuidadoso, PlayerName. Como juízes, não podemos permitir que noções preconcebidas de qualquer tipo afetem nosso julgamento.",
  ui_story_5045_50450501_23_dialog_content = "T-Tá...",
  ui_story_5045_50450501_24_dialog_content = "Farrell, por favor, diga-nos por que você veio ao Tribunal de Justiça hoje?",
  ui_story_5045_50450501_25_dialog_content = "Porque o réu e eu tínhamos um acordo!",
  ui_story_5045_50450501_26_dialog_content = "Por favor, elabore este acordo entre vocês dois.",
  ui_story_5045_50450501_27_dialog_content = "Nosso acordo era que nos casaríamos assim que nosso <color=#1875ad>recursos financeiros eram iguais</color>!",
  ui_story_5045_50450501_28_dialog_content = "Mas isso é normal, não é? As pessoas sempre assinam acordos de noivado como esse para proteger seus bens.",
  ui_story_5045_50450501_29_dialog_content = "Essa tal de Sophie não parece particularmente bem de vida. Ela provavelmente estava tentando tirar vantagem da posição econômica do cavaleiro.",
  ui_story_5045_50450501_30_dialog_content = "Eles honestamente acham que essas disputas mesquinhas são dignas de desperdiçar o tempo do juiz Leyn?",
  ui_story_5045_50450501_31_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50450501_32_dialog_content = "Silêncio! Ordem no tribunal!",
  ui_story_5045_50450501_33_dialog_content = "Farrell, posso perguntar se houve alguma testemunha deste acordo? Ou talvez prova de algum tipo?",
  ui_story_5045_50450501_34_dialog_content = "S-Sim, Meritíssimo.",
  ui_story_5045_50450501_35_dialog_content = "Aqui está o <color=#1875ad>contrato</color> nós assinamos. Você descobrirá que foi feito de acordo com os regulamentos da Lumopolis.",
  ui_story_5045_50450501_36_dialog_content = "Hmm... O contrato parece estar em perfeita ordem.",
  ui_story_5045_50450501_37_dialog_content = "Você poderia, por favor, apresentar suas demandas ao tribunal?",
  ui_story_5045_50450501_38_dialog_content = "Já que nossas finanças agora são iguais, peço que o tribunal imponha nosso acordo de casamento!",
  ui_story_5045_50450501_39_dialog_content = "Me desculpe, eu ouvi isso corretamente?",
  ui_story_5045_50450501_40_dialog_content = "Como as finanças de um plebeu poderiam ser iguais às de um cavaleiro?",
  ui_story_5045_50450501_41_dialog_content = "O arguido claramente roubou-lhe o dinheiro.",
  ui_story_5045_50450501_42_dialog_content = "Sofia.",
  ui_story_5045_50450501_43_dialog_content = "Sim, Meritíssimo!",
  ui_story_5045_50450501_44_dialog_content = "Você tem algo a dizer sobre este contrato?",
  ui_story_5045_50450501_45_dialog_content = "Sim, Meritíssimo. É verdade que eu assinei aquele acordo.",
  ui_story_5045_50450501_46_dialog_content = "Mas quando conheci Farrell, eu ainda era jovem e inexperiente nos caminhos do mundo... Não fazia ideia do que significava amor na época.",
  ui_story_5045_50450501_47_dialog_content = "Naquela época, Farrell me cortejou com palavras doces e grandes promessas. Ele me fez realmente acreditar que ele era minha alma gêmea.",
  ui_story_5045_50450501_48_dialog_content = "Fiquei impressionado com sua falsa afeição, por isso assinei aquele contrato.",
  ui_story_5045_50450501_49_dialog_content = "Mas com o passar do tempo, percebi que não fomos feitos para ficar juntos. Até sugeri que seguíssemos caminhos separados em mais de uma ocasião.",
  ui_story_5045_50450501_50_dialog_content = "Por esta razão, cumpro nosso acordo de casamento.",
  ui_story_5045_50450501_51_dialog_content = "Em outras palavras, você está se recusando a honrar o conteúdo deste acordo assinado. Isso está correto?",
  ui_story_5045_50450501_52_dialog_content = "Sim, Meritíssimo. Prefiro passar o resto da minha vida na prisão a passá-la com alguém que não amo.",
  ui_story_5045_50450501_53_dialog_content = "D-Não diga coisas assim, Sophie...",
  ui_story_5045_50450501_54_dialog_content = "Você sabe que romper nosso noivado só prejudicaria minha reputação de cavaleiro!",
  ui_story_5045_50450501_55_dialog_content = "Como você ainda pode ser tão cego para o meu amor por você?!",
  ui_story_5045_50450501_56_dialog_content = "Não aguento mais o seu amor, Farrell...",
  ui_story_5045_50450501_57_dialog_content = "Você não fez nada além de observar cada movimento meu e me assediar a cada passo!",
  ui_story_5045_50450501_58_dialog_content = "Só faço isso para proteger você, Sophie!",
  ui_story_5045_50450501_59_dialog_content = "Bem, sinto muito, mas não preciso da proteção de ninguém.",
  ui_story_5045_50450501_60_dialog_content = "Que feio...",
  ui_story_5045_50450501_61_dialog_content = "Não faço a menor ideia do que estão falando...",
  ui_story_5045_50450501_62_dialog_content = "(E agora eles estão discutindo? Parece que os outros estão começando a fofocar entre si também.)",
  ui_story_5045_50450501_63_dialog_content = "(A julgar pelo suspiro de Leyn agora, parece que essa coisa toda está fazendo sua cabeça doer...)",
  ui_story_5045_50450501_64_dialog_content = "Você vê por que ninguém quer se juntar à Divisão Romance agora, PlayerName?",
  ui_story_5045_50450501_65_dialog_content = "Quando se trata de casos como este, raramente existem leis ou precedentes em que se basear.",
  ui_story_5045_50450501_66_dialog_content = "Ambos os lados têm argumentos perfeitamente razoáveis, o que torna difícil para um juiz aprovar um veredicto justo e imparcial.",
  ui_story_5045_50450501_67_dialog_content = "Mas tudo bem, porque serve como uma espécie de treinamento para mim. Juro que defenderei a justiça até o fim!",
  ui_story_5045_50450501_68_dialog_content = "Agora, então, você tem alguma opinião para compartilhar sobre este caso?",
  ui_story_5045_50450501_69_dialog_content = "Agora não, não...",
  ui_story_5045_50450501_70_dialog_content = "E-espere, eu entendi!",
  ui_story_5045_50450501_71_dialog_content = "Acho que devemos dar uma olhada mais de perto nas coisas.",
  ui_story_5045_50450501_72_dialog_content = "Tá bom...",
  ui_story_5045_50450501_73_dialog_content = "Dê uma olhada neste, Leyn...",
  ui_story_5045_50450501_74_dialog_content = "Bem, você olharia para isso? Eu tenho que dizer, vendo que <color=#1875ad>caderno</color> realmente traz de volta memórias.",
  ui_story_5045_50450501_75_dialog_content = "Quando eu era juiz estagiário, levava comigo todos os dias.",
  ui_story_5045_50450501_76_dialog_content = "Mas não acho que seja um bom momento para compartilhar histórias.",
  ui_story_5045_50450501_77_dialog_content = "Por que não nos concentramos no caso em questão?",
  ui_story_5045_50450501_78_dialog_content = "Bom...",
  ui_story_5045_50450501_79_dialog_content = "Talvez devêssemos começar com isso <color=#1875ad>contrato</color>?",
  ui_story_5045_50450501_80_dialog_content = "Uma escolha sábia.",
  ui_story_5045_50450501_81_dialog_content = "Podemos nunca entender os sentimentos entre as duas partes.",
  ui_story_5045_50450501_82_dialog_content = "Mas um acordo por escrito está sujeito à proteção total da lei de Lumopolis!",
  ui_story_5045_50450501_83_dialog_content = "Obrigado por sua sugestão. Acho que agora tenho minha resposta.",
  ui_story_5045_50450501_84_dialog_content = "Que resposta seria essa?",
  ui_story_5045_50450501_85_dialog_content = "Em breve vai ter.",
  ui_story_5045_50450501_86_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50450501_87_dialog_content = "Noite Branca no alto. É hora do veredicto!",
  ui_story_5045_50450501_88_dialog_content = "Ambas as partes eram adultos consentidos na assinatura deste contrato e devem assumir a responsabilidade por suas decisões.",
  ui_story_5045_50450501_89_dialog_content = "De acordo com as leis relevantes de Lumópolis...",
  ui_story_5045_50450501_90_dialog_content = "O tribunal ordena que a ré, Sophie, honre as condições do acordo e se case com o autor, Farrell.",
  ui_story_5045_50450501_91_dialog_content = "Se você não aceitar esta sentença, poderá recorrer de acordo com as disposições do Tribunal de Justiça.",
  ui_story_5045_50450501_92_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50450501_93_dialog_content = "O julgamento acabou!",
  ui_story_5045_50450501_94_dialog_content = "Não deveríamos perguntar a Sophie se Farrell quebrou alguma parte do acordo?",
  ui_story_5045_50450501_95_dialog_content = "Acho que você acabou de tocar em um aspecto crucial deste caso, PlayerName!",
  ui_story_5045_50450501_96_dialog_content = "Sophie, você afirma que o queixoso tem monitorado seus movimentos, além de assediar você. Isso é correto?",
  ui_story_5045_50450501_97_dialog_content = "Com certeza!",
  ui_story_5045_50450501_98_dialog_content = "Farrell muitas vezes tira vantagem de seu status de cavaleiro para perambular fora de minha casa.",
  ui_story_5045_50450501_99_dialog_content = "Apesar de claramente rejeitá-lo várias vezes, ele se recusa a me deixar em paz e até me levou ao tribunal por causa disso!",
  ui_story_5045_50450501_100_dialog_content = "Meritíssimo, embora minha família careça de status e riqueza.",
  ui_story_5045_50450501_101_dialog_content = "Isso não significa que posso ser explorado por outros!",
  ui_story_5045_50450501_102_dialog_content = "Eu tenho o direito de amar ou rejeitar quem eu quiser, assim como qualquer outra pessoa!",
  ui_story_5045_50450501_103_dialog_content = "Não é por isso que a Divisão Romance do Tribunal de Justiça foi criada? Para proteger esses mesmos direitos?",
  ui_story_5045_50450501_104_dialog_content = "(O réu faz um ponto extremamente válido!)",
  ui_story_5045_50450501_105_dialog_content = "(Quando você pensa sobre isso, aquele cavaleiro estava meio que forçando ela.)",
  ui_story_5045_50450501_106_dialog_content = "Devo dizer, Sophie, que sua compreensão do amor é única. Aprendi muito ouvindo você.",
  ui_story_5045_50450501_107_dialog_content = "Você está absolutamente certo! A Divisão de Romance da Sala de Justiça tem o dever de defender o amor em toda a extensão da lei!",
  ui_story_5045_50450501_108_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50450501_109_dialog_content = "Noite Branca no alto. É hora do veredicto!",
  ui_story_5045_50450501_110_dialog_content = "O contrato firmado entre as duas partes é perfeitamente válido.",
  ui_story_5045_50450501_111_dialog_content = "No entanto, o comportamento do queixoso tornou o réu relutante em se casar com ele, violando assim as condições do acordo.",
  ui_story_5045_50450501_112_dialog_content = "O tribunal não tem escolha a não ser impor uma multa de 100 Nightium ao réu, a ser paga integralmente dentro do prazo estipulado.",
  ui_story_5045_50450501_113_dialog_content = "Após receber a multa por quebra de contrato, a autora não deve mais assediar a ré, Sophie.",
  ui_story_5045_50450501_114_dialog_content = "Se você não aceitar esta sentença, poderá recorrer de acordo com as disposições do Tribunal de Justiça.",
  ui_story_5045_50450501_115_dialog_content = "A coragem daquele plebeu! Como ela ousa manchar a honra de um cavaleiro!",
  ui_story_5045_50450501_116_dialog_content = "Independentemente disso, esta é a decisão do juiz Leyn, o que a torna justa e justa.",
  ui_story_5045_50450501_117_dialog_content = "Juiz Leyn! Você tem o dever de proteger o nosso direito de amar também!",
  ui_story_5045_50450501_118_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50450501_119_dialog_content = "O julgamento acabou!",
  ui_story_5045_50450601_1_dialog_content = "<color=#737378>Hora: 12h00</color>",
  ui_story_5045_50450601_2_dialog_content = "<color=#737378>Local: Salão Nobre da Sala Lumo de Justiça</color>",
  ui_story_5045_50450601_3_dialog_content = "Sofia! Espere!",
  ui_story_5045_50450601_4_dialog_content = "Por favor fique longe de mim.",
  ui_story_5045_50450601_5_dialog_content = "Eu sabia que você não estaria disposto a se casar comigo, mesmo que eu tivesse vencido no tribunal hoje.",
  ui_story_5045_50450601_6_dialog_content = "Mas, por favor, apenas nos dê uma chance de conversar sobre as coisas!",
  ui_story_5045_50450601_7_dialog_content = "Salve-o para o tribunal.",
  ui_story_5045_50450601_8_dialog_content = "<color=#737378>Hora: 14:00</color>",
  ui_story_5045_50450601_9_dialog_content = "<color=#737378>Localização: Lumo Hall of Justice, Escritório da Divisão Romance</color>",
  ui_story_5045_50450601_10_dialog_content = "Huh? Por que você ainda está olhando para esse acordo, Leyn?",
  ui_story_5045_50450601_11_dialog_content = "Diga-me... Você acha que tomei a decisão certa no caso de hoje?",
  ui_story_5045_50450601_12_dialog_content = "Bem, eu realmente não sei muito sobre suas leis e regulamentos.",
  ui_story_5045_50450601_13_dialog_content = "Eu sei. Quando lhe pedi para me ajudar, minha única expectativa era que você me lembrasse de fazer um julgamento justo a todo custo.",
  ui_story_5045_50450601_14_dialog_content = "É por isso que peço que você compartilhe seus pensamentos comigo, se possível.",
  ui_story_5045_50450601_15_dialog_content = "Acho que seu veredicto foi...",
  ui_story_5045_50450601_16_option_content = "Um justo.",
  ui_story_5045_50450601_17_dialog_content = "Obrigado pela garantia, mas não posso deixar de sentir que algo está errado.",
  ui_story_5045_50450601_18_dialog_content = "Os casos da Divisão Romance nunca são tão simples.",
  ui_story_5045_50450601_19_option_content = "Um pouco duro.",
  ui_story_5045_50450601_20_dialog_content = "A lei pode ter um efeito obrigatório sobre coisas como contratos, mas definitivamente não pode dizer às pessoas como se sentir.",
  ui_story_5045_50450601_21_dialog_content = "Mesmo que Sophie acabe se casando com Farrell, não consigo imaginar que a vida deles será feliz.",
  ui_story_5045_50450601_22_dialog_content = "Ah! S-Desculpe, Leyn! Eu não estava tentando contestar seu veredicto ou algo assim...",
  ui_story_5045_50450601_23_dialog_content = "Não há razão para se desculpar. No mínimo, devo agradecer por sua disposição em me guiar em casos como este.",
  ui_story_5045_50450601_24_option_content = "Eu realmente não tenho uma opinião.",
  ui_story_5045_50450601_25_dialog_content = "Como assim?",
  ui_story_5045_50450601_26_dialog_content = "Não ter uma opinião sobre algo é a pior opinião que se pode ter.",
  ui_story_5045_50450601_27_dialog_content = "Suspiro, então, novamente, eu não deveria continuar depositando todas as minhas esperanças em você. Desculpe.",
  ui_story_5045_50450601_28_dialog_content = "(Leyn parece bastante decepcionado comigo...)",
  ui_story_5045_50450601_29_dialog_content = "(Talvez eu devesse dizer a ele o que realmente penso sobre o veredicto dele?)",
  ui_story_5045_50450601_30_dialog_content = "Parece que teremos que nos esforçar ainda mais neste caso.",
  ui_story_5045_50450601_31_dialog_content = "Vamos.",
  ui_story_5045_50450601_32_dialog_content = "Huh? Para onde?",
  ui_story_5045_50450601_33_dialog_content = "Sofia apresentou um recurso.",
  ui_story_5045_50450601_34_dialog_content = "Ela disse que tinha mais evidências para fornecer para seu caso.",
  ui_story_5045_50450601_35_dialog_content = "<color=#737378>Horário: 15h</color>",
  ui_story_5045_50450601_36_dialog_content = "<color=#737378>Localização: Baixa Lumópolis</color>",
  ui_story_5045_50450601_37_dialog_content = "Boa tarde. Perdão, mas a casa da Sophie fica perto?",
  ui_story_5045_50450601_38_dialog_content = "Me desculpe, mas quem é você mesmo?",
  ui_story_5045_50450601_39_dialog_content = "(Essa pessoa parece meio familiar...)",
  ui_story_5045_50450601_40_dialog_content = "Nós somos...",
  ui_story_5045_50450601_41_dialog_content = "Oh não, PlayerName! Você tem alguma coisa para mostrar a ele que prove nossa <color=#1875ad>identidade</color>?",
  ui_story_5045_50450601_42_dialog_content = "Isso vai fazer?",
  ui_story_5045_50450601_43_dialog_content = "Acho que isso não serve para provar quem somos.",
  ui_story_5045_50450601_44_dialog_content = "Oh, r-sério? Nesse caso...",
  ui_story_5045_50450601_45_dialog_content = "Somos juízes do Tribunal de Justiça de Lumopolis.",
  ui_story_5045_50450601_46_dialog_content = "Estamos aqui a convite da Sophie. Ela disse que tinha mais informações para fornecer para seu caso.",
  ui_story_5045_50450601_47_dialog_content = "Eu não fazia ideia de que estava na presença de dois juízes! Por favor, você tem que ajudar nossa pobre pequena Sophie!",
  ui_story_5045_50450601_48_dialog_content = "Você conhece ela?",
  ui_story_5045_50450601_49_dialog_content = "Sim senhor! Meu nome é <color=#1875ad>Karl</color>. Eu sou um dos vizinhos dela.",
  ui_story_5045_50450601_50_dialog_content = "Não é nenhum segredo que algum cavaleiro chamado Farrell a está assediando há algum tempo. Ela está positivamente infeliz por causa disso.",
  ui_story_5045_50450601_51_dialog_content = "É por isso que, como vizinhos dela, decidimos afastar qualquer visitante suspeito.",
  ui_story_5045_50450601_52_dialog_content = "Eu vejo. Isso explica por que você queria uma prova de quem somos.",
  ui_story_5045_50450601_53_dialog_content = "Você disse que Farrell está assediando Sophie há muito tempo, certo?",
  ui_story_5045_50450601_54_dialog_content = "Eu sei que é impróprio da minha parte dizer isso sobre um cavaleiro.",
  ui_story_5045_50450601_55_dialog_content = "Mas o homem praticamente vigia a casa dela todos os dias.",
  ui_story_5045_50450601_56_dialog_content = "Mesmo depois que Sophie esclarece que não quer nada com ele, Farrell se recusa a aceitar.",
  ui_story_5045_50450601_57_dialog_content = "Do jeito que as coisas estão indo, não posso deixar de temer pela segurança dela, sabe?",
  ui_story_5045_50450601_58_dialog_content = "Afinal, parece que a acusação de Sophie durante o julgamento era verdade?",
  ui_story_5045_50450601_59_dialog_content = "Isso significa que meu veredicto foi...",
  ui_story_5045_50450601_60_dialog_content = "A casa de Sophie é logo adiante. Deixe-me mostrar-lhe o caminho.",
  ui_story_5045_50450601_61_dialog_content = "<color=#737378>Horário: 15h20</color>",
  ui_story_5045_50450601_62_dialog_content = "<color=#737378>Localização: Lower Lumopolis, casa de Sophie</color>",
  ui_story_5045_50450601_63_dialog_content = "Por favor, perdoe-me, Meritíssimo. Tenho certeza de que minha humilde casa parece ridícula para juízes como vocês.",
  ui_story_5045_50450601_64_dialog_content = "Não sonharíamos com isso, Sophie. Sua casa é muito aconchegante e convidativa, outra coisa que pude aprender com você.",
  ui_story_5045_50450601_65_dialog_content = "Um de seus vizinhos nos disse que Farrell está assediando você todos os dias. Isso é verdade?",
  ui_story_5045_50450601_66_dialog_content = "*Suspira*",
  ui_story_5045_50450601_67_dialog_content = "No começo, ele apenas me seguia e perdia tempo fora de minha casa.",
  ui_story_5045_50450601_68_dialog_content = "Mas apenas <color=#1875ad>esta manhã</color>, notei um estranho conjunto de <color=#1875ad>pegadas</color> em minha casa. Estou começando a ficar com muito medo...",
  ui_story_5045_50450601_69_dialog_content = "Você quer dizer essas pegadas aqui? Eles parecem um pouco estranhos.",
  ui_story_5045_50450601_70_dialog_content = "Parece que quem os deixou realmente queria que você os visse. Eles até pisaram em um pedaço de papel e o deixaram no chão.",
  ui_story_5045_50450601_71_dialog_content = "As marcas de calcanhar dessas pegadas são especialmente claras. O padrão se parece muito com os deixados pelas botas que os cavaleiros costumam usar.",
  ui_story_5045_50450601_72_dialog_content = "As pegadas parecem começar perto da janela...",
  ui_story_5045_50450601_73_dialog_content = "É possível que Farrell tenha entrado enquanto Sophie não estava olhando?",
  ui_story_5045_50450601_74_dialog_content = "Eu não posso dizer com certeza. Falta algum dos seus pertences, Sophie?",
  ui_story_5045_50450601_75_dialog_content = "Nenhum mesmo. O que torna as coisas ainda mais assustadoras!",
  ui_story_5045_50450601_76_dialog_content = "Farrell deve estar tentando me intimidar... E está funcionando. Ah, o que devo fazer?",
  ui_story_5045_50450601_77_dialog_content = "Se ao menos eu tivesse pedido mais informações durante o julgamento.",
  ui_story_5045_50450601_78_dialog_content = "Não o culpo de forma alguma, Meritíssimo.",
  ui_story_5045_50450601_79_dialog_content = "Não há como negar que infringi a lei quebrando meu contrato com Farrell. Então, por favor, apenas me mande para a prisão!",
  ui_story_5045_50450601_80_dialog_content = "No mínimo, eu não teria que me casar com algum perseguidor manipulador lá...",
  ui_story_5045_50450601_81_dialog_content = "Fique tranquila, Sophie.",
  ui_story_5045_50450601_82_dialog_content = "Agora que temos motivos mais do que suficientes para suspeitar de Farrell de jogo sujo, vamos reexaminar o caso de hoje com toda a devida diligência.",
  ui_story_5045_50450601_83_dialog_content = "Tudo bem se dermos uma olhada, Sophie?",
  ui_story_5045_50450601_84_dialog_content = "Por todos os meios, eu só espero que você não se importe com a bagunça...",
  ui_story_5045_50450601_85_dialog_content = "Ahem, acho que investigar a casa de Sophie causaria um desconforto desnecessário a ela, não é?",
  ui_story_5045_50450601_86_dialog_content = "S-Desculpe! Isso nem me ocorreu... Você é muito bom em saber como as outras pessoas se sentem, Leyn!",
  ui_story_5045_50450601_87_dialog_content = "Mesmo assim, viemos até aqui... Farrell pode ter deixado mais pistas por aí.",
  ui_story_5045_50450601_88_dialog_content = "Se alguém perguntar, diga que a ideia foi minha, ok?",
  ui_story_5045_50450601_89_dialog_content = "Como eu poderia deixar você arcar com toda a culpa?",
  ui_story_5045_50450601_90_dialog_content = "Quando terminarmos aqui, vou me desculpar com Sophie em seu nome.",
  ui_story_5045_50450601_91_dialog_content = "Haha...",
  ui_story_5045_50450601_92_dialog_content = "Ah! Desculpe, eu não queria escutar!",
  ui_story_5045_50450601_93_dialog_content = "Mas a maneira como vocês dois continuam tentando levar a culpa um pelo outro. Vocês devem ser muito bons amigos.",
  ui_story_5045_50450601_94_dialog_content = "Por favor, investigue como achar melhor. Eu nunca poderia me ofender, quando vocês dois estão trabalhando tanto para me ajudar.",
  ui_story_5045_50450601_95_dialog_content = "... Obrigado pela sua compreensão.",
  ui_story_5045_50450601_96_dialog_content = "Agora então, por onde devemos começar nossa <color=#1875ad>investigação</color>?",
  ui_story_5045_50450601_97_dialog_content = "Deixa eu pensar...",
  ui_story_5045_50450601_98_option_content = "Verifique as gavetas",
  ui_story_5045_50450601_99_dialog_content = "Há um monte de letras bonitas aqui.",
  ui_story_5045_50450601_100_dialog_content = "Essas não são cartas comuns.",
  ui_story_5045_50450601_101_dialog_content = "O que te faz dizer isso?",
  ui_story_5045_50450601_102_dialog_content = "Porque eu mesmo tenho muitos deles...",
  ui_story_5045_50450601_103_dialog_content = "Você também? Espera... Já entendi! Estas são cartas de amor, não são?",
  ui_story_5045_50450601_104_dialog_content = "A caligrafia e a assinatura em cada um são diferentes, no entanto.",
  ui_story_5045_50450601_105_dialog_content = "Parece que Sophie também é bastante popular. Mas não devemos ler suas cartas particulares.",
  ui_story_5045_50450601_106_dialog_content = "Vamos tentar procurar em outro lugar.",
  ui_story_5045_50450601_106X1_dialog_content = "Onde mais devo investigar?",
  ui_story_5045_50450601_107_option_content = "verifique o chão",
  ui_story_5045_50450601_108_dialog_content = "Não vejo nenhuma outra pegada além daquelas perto da janela.",
  ui_story_5045_50450601_109_dialog_content = "Espera, o que é isso?",
  ui_story_5045_50450601_110_dialog_content = "É um cartão? Parece algum tipo de <color=#1875ad>cartão de presença</color>.",
  ui_story_5045_50450601_111_dialog_content = "Oh sim. Comecei a ter algumas aulas de limpeza recentemente.",
  ui_story_5045_50450601_112_dialog_content = "Esse é o meu cartão de presença do curso.",
  ui_story_5045_50450601_113_dialog_content = "Com a morte de meus pais, não tenho como reconstruir o negócio de nossa família. Mas isso não significa que eu quero ficar de braços cruzados e não fazer nada a respeito!",
  ui_story_5045_50450601_114_dialog_content = "Quero trabalhar duro e confiar em minhas próprias habilidades para ganhar a vida.",
  ui_story_5045_50450601_115_dialog_content = "Eu... Tenho certeza que você terá sucesso!",
  ui_story_5045_50450601_116_option_content = "Embrulhe isso",
  ui_story_5045_50450601_117_dialog_content = "Não parece haver mais nada aqui, além dessas pegadas.",
  ui_story_5045_50450601_118_dialog_content = "Então ele não levou nada com ele, nem deixou nada para trás.",
  ui_story_5045_50450601_119_dialog_content = "O que exatamente Farrell está tramando?",
  ui_story_5045_50450601_120_dialog_content = "<color=#737378>Horário: 17:00</color>",
  ui_story_5045_50450601_121_dialog_content = "<color=#737378>Local: Posto da Guarda de Lumópolis</color>",
  ui_story_5045_50450601_122_dialog_content = "Este lugar é aterrorizante... É realmente aqui que Farrell trabalha?",
  ui_story_5045_50450601_123_dialog_content = "Claro que é assustador. Apenas os nobres mais destemidos são dignos de trabalhar aqui.",
  ui_story_5045_50450601_124_dialog_content = "B-Beverly?!",
  ui_story_5045_50450601_125_dialog_content = "Farrell está de plantão agora. Se quiser vê-lo, terá que voltar outro dia.",
  ui_story_5045_50450601_126_dialog_content = "Perdoe a intromissão, Lady Duquesa, mas estamos aqui em uma investigação.",
  ui_story_5045_50450601_127_dialog_content = "Pelo que entendi, Farrell é um dos seus colegas aqui, sim?",
  ui_story_5045_50450601_128_dialog_content = "De fato, ele é. Mas eu pensei que o caso dele já havia sido resolvido?",
  ui_story_5045_50450601_129_dialog_content = "O réu apresentou um recurso, o que nos obriga a reexaminar o caso.",
  ui_story_5045_50450601_130_dialog_content = "Hmph. É assim mesmo?",
  ui_story_5045_50450601_131_dialog_content = "Então você faria bem em examinar as coisas com mais cuidado desta vez. Desde que conheceu aquela Sophie, Farrell se tornou um homem totalmente diferente.",
  ui_story_5045_50450601_132_dialog_content = "Ele continua falando sobre perder sua honra como cavaleiro se não conseguir resgatar sua princesa.",
  ui_story_5045_50450601_133_dialog_content = "Embora não tenha apresentado nenhuma complicação em seu trabalho, acho tudo insuportavelmente irritante.",
  ui_story_5045_50450601_134_dialog_content = "Um verdadeiro cavaleiro deve servir ao povo de todo o coração. Mas temo que seu coração já esteja comprometido.",
  ui_story_5045_50450601_135_dialog_content = "Ouvi dizer que ele se mudou para este quartel recentemente. Isso é verdade?",
  ui_story_5045_50450601_136_dialog_content = "Isso é. Não muito tempo atrás, ele doou toda a sua riqueza e bens para os pobres de Umbraton.",
  ui_story_5045_50450601_137_dialog_content = "Ele está morando aqui desde então.",
  ui_story_5045_50450601_138_dialog_content = "Sua abnegação é algo a ser elogiado, com certeza. Mas o que isso tem a ver com o caso dele?",
  ui_story_5045_50450601_139_dialog_content = "A-Todos os seus bens?!",
  ui_story_5045_50450601_140_dialog_content = "Você poderia nos mostrar os aposentos de Farrell?",
  ui_story_5045_50450601_141_dialog_content = "Seus aposentos estão logo à esquerda daqui. Você pode se ver em.",
  ui_story_5045_50450601_142_dialog_content = "<color=#737378>Algum tempo depois</color>",
  ui_story_5045_50450601_143_dialog_content = "Bem? Encontrar alguma coisa ainda?",
  ui_story_5045_50450601_144_dialog_content = "O tamanho e a forma das pegadas combinam perfeitamente com a pegada que Farrell deixou em casa.",
  ui_story_5045_50450601_145_dialog_content = "Então a pessoa que invadiu a casa de Sophie realmente foi Farrell...",
  ui_story_5045_50450601_146_dialog_content = "E você, PlayerName? Alguma descoberta?",
  ui_story_5045_50450601_147_dialog_content = "Além disso, não vejo nada particularmente fora do lugar em seu quarto.",
  ui_story_5045_50450601_148_dialog_content = "Isso é um<color=#1875ad> pipa</color>?",
  ui_story_5045_50450601_149_dialog_content = "E olha, tem o nome da Sophie escrito nele!",
  ui_story_5045_50450601_150_dialog_content = "Isso significa que Farrell pegou algo de sua casa? Por que ela não nos contou sobre isso?",
  ui_story_5045_50450601_151_dialog_content = "Talvez não valha muito?",
  ui_story_5045_50450601_152_dialog_content = "Todas as evidências que reunimos até agora parecem apontar para Farrell como a pessoa culpada.",
  ui_story_5045_50450601_153_dialog_content = "Se for esse o caso, não apenas Farrell perderá o caso. Ele enfrentará uma punição ainda mais severa.",
  ui_story_5045_50450601_154_dialog_content = "Que tipo de punição?",
  ui_story_5045_50450601_155_dialog_content = "Ele perderá seu status de cavaleiro e será forçado a viver como um plebeu.",
  ui_story_5045_50450601_156_dialog_content = "Para a nobreza, esta é uma das piores punições que uma pessoa de seu status pode receber.",
  ui_story_5045_50450601_157_dialog_content = "Entendo... Mas algo me diz que há mais neste caso do que imaginamos.",
  ui_story_5045_50450601_158_dialog_content = "Exatamente meus pensamentos.",
  ui_story_5045_50450601_159_dialog_content = "Não podemos pular nenhum detalhe do julgamento de amanhã.",
  ui_story_5045_50450701_1_dialog_content = "<color=#737378>Hora: 9:00 AM</color>",
  ui_story_5045_50450701_2_dialog_content = "<color=#737378>Local: Lumo Hall of Justice, Tribunal</color>",
  ui_story_5045_50450701_3_dialog_content = "Uau! Leyn parece tão bonito como sempre hoje, você não acha?",
  ui_story_5045_50450701_4_dialog_content = "(Parece que o fã-clube de Leyn está de volta...)",
  ui_story_5045_50450701_5_dialog_content = "O que está em sua mente, PlayerName?",
  ui_story_5045_50450701_6_dialog_content = "Nada, apenas...",
  ui_story_5045_50450701_7_option_content = "Você parece tão bonito como sempre hoje, Leyn!",
  ui_story_5045_50450701_8_dialog_content = "(Merda, eu repeti as palavras daquela garota sem pensar...)",
  ui_story_5045_50450701_9_dialog_content = "A-Ahem... O tribunal estará em sessão em breve, então, por favor, tente se concentrar.",
  ui_story_5045_50450701_10_option_content = "Lembre-se de fazer um julgamento justo!",
  ui_story_5045_50450701_11_dialog_content = "Eu vou. Obrigado por me lembrar.",
  ui_story_5045_50450701_12_dialog_content = "Aprendi minha lição com o último julgamento. Não vou mostrar nenhuma indecisão hoje.",
  ui_story_5045_50450701_13_option_content = "Queria ser tão popular quanto você...",
  ui_story_5045_50450701_14_dialog_content = "Realmente? Eu sempre pensei que você tinha ambições maiores do que isso...",
  ui_story_5045_50450701_15_dialog_content = "Mas agora não é hora para esse tipo de conversa! Tribunal estará em sessão em breve!",
  ui_story_5045_50450701_16_dialog_content = "(E aqui eu pensei Leyn me sentiria melhor se eu lhe desse um pequeno elogio...)",
  ui_story_5045_50450701_17_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50450701_18_dialog_content = "<size=45>Noite Branca no alto. Tribunal está agora em sessão!</size>",
  ui_story_5045_50450701_19_dialog_content = "Para começar, a apelante, Sophie, poderia expor seu caso?",
  ui_story_5045_50450701_20_dialog_content = "Bom dia, Excelência. Não posso aceitar o veredicto de primeira instância.",
  ui_story_5045_50450701_21_dialog_content = "Apelo para rescindir o acordo entre Farrell e eu.",
  ui_story_5045_50450701_22_dialog_content = "Como cavaleiro, ele usou sua posição para me perseguir e assediar.",
  ui_story_5045_50450701_23_dialog_content = "Ele até invadiu minha casa <color=#1875ad>após o primeiro teste</color> e deixou suas pegadas lá!",
  ui_story_5045_50450701_24_dialog_content = "Algo está errado com a declaração de Sophie!",
  ui_story_5045_50450701_25_dialog_content = "Qual é o problema?",
  ui_story_5045_50450701_26_dialog_content = "Huh? Sem problemas?",
  ui_story_5045_50450701_26X1_dialog_content = "Tem certeza de que não me ouviu mal? Deixe-me dizer mais uma vez...",
  ui_story_5045_50450701_27_dialog_content = "Dê uma olhada neste, Leyn...",
  ui_story_5045_50450701_28_dialog_content = "Bem, você olharia para isso? Devo dizer que ver aquele caderno realmente me traz lembranças.",
  ui_story_5045_50450701_29_dialog_content = "Quando eu era juiz estagiário, levava comigo todos os dias.",
  ui_story_5045_50450701_30_dialog_content = "Por que essa conversa parece tão familiar?",
  ui_story_5045_50450701_31_dialog_content = "O que você tá tentando dizer?",
  ui_story_5045_50450701_32_dialog_content = "Estou pensando...",
  ui_story_5045_50450701_33_dialog_content = "Sophie, você disse que encontrou essas pegadas em <color=#1875ad>na manhã do primeiro julgamento</color>?",
  ui_story_5045_50450701_34_dialog_content = "Oh... Devo ter me enganado.",
  ui_story_5045_50450701_35_dialog_content = "Meritíssimo, eu estava muito nervoso agora... Deixe-me dizer isso de novo!",
  ui_story_5045_50450701_36_dialog_content = "Na manhã do primeiro julgamento, encontrei essas pegadas em minha casa.",
  ui_story_5045_50450701_37_dialog_content = "Mas nada foi roubado... Eu sabia que devia ser uma tentativa deliberada de invadir minha casa e me assustar!",
  ui_story_5045_50450701_38_dialog_content = "Nada foi roubado? Mas...",
  ui_story_5045_50450701_39_dialog_content = "Acho que me lembro que Farrell tinha <color=#1875ad>algo que era seu</color>!",
  ui_story_5045_50450701_40_dialog_content = "Há algo de errado aqui?",
  ui_story_5045_50450701_41_dialog_content = "Ah, não é isso! O que eu queria dizer era...",
  ui_story_5045_50450701_42_dialog_content = "Esse <color=#1875ad>pipa</color> tem a assinatura de Sophie nele. Deve pertencer a você, certo?",
  ui_story_5045_50450701_43_dialog_content = "Isso é...",
  ui_story_5045_50450701_44_dialog_content = "Meritíssimo, este é um símbolo do nosso amor!",
  ui_story_5045_50450701_45_dialog_content = "Naquela época, eu tinha acabado de patrulhar...",
  ui_story_5045_50450701_46_dialog_content = "(Erm, ele vai se apaixonar de novo aqui mesmo no Tribunal de Justiça?)",
  ui_story_5045_50450701_47_dialog_content = "Senhor...",
  ui_story_5045_50450701_48_dialog_content = "Sim, o que posso fazer para ajudar?",
  ui_story_5045_50450701_49_dialog_content = "M-Minha pipa está presa naquela árvore ali. Eu sei que não deveria incomodá-lo...",
  ui_story_5045_50450701_50_dialog_content = "Mas aquela pipa é muito importante para mim. Foi feito pelo meu pai...",
  ui_story_5045_50450701_51_dialog_content = "Não é nenhum problema. Por favor espere um momento.",
  ui_story_5045_50450701_52_dialog_content = "Muito obrigado! Eu realmente não sei o que fazer se não fosse por você...",
  ui_story_5045_50450701_53_dialog_content = "É tudo em um dia de trabalho. Por favor, não mencione isso.",
  ui_story_5045_50450701_54_dialog_content = "Erm... Você gosta de empinar pipas?",
  ui_story_5045_50450701_55_dialog_content = "E assim, nos encontrávamos de tempos em tempos para empinar pipas juntos e, gradualmente, nos tornamos mais próximos.",
  ui_story_5045_50450701_56_dialog_content = "Foi nessa época que minha família desejou escolher uma esposa adequada para mim.",
  ui_story_5045_50450701_57_dialog_content = "Mas acredito que o amor nasce da liberdade e não queria ser controlada pela minha família.",
  ui_story_5045_50450701_58_dialog_content = "Então virei as costas para minha família e pedi Sophie em casamento.",
  ui_story_5045_50450701_59_dialog_content = "Farrell, nossas pipas estão voando tão alto!",
  ui_story_5045_50450701_60_dialog_content = "Não importa o quão alto uma pipa voe, ela deve retornar ao solo depois que o vento parar.",
  ui_story_5045_50450701_61_dialog_content = "Por exemplo, não importa o quão longe viajemos no vasto mundo, devemos finalmente retornar a uma família calorosa e amorosa.",
  ui_story_5045_50450701_62_dialog_content = "Eu não tenho certeza se entendi.",
  ui_story_5045_50450701_63_dialog_content = "Sophie, você gostaria de construir uma família feliz comigo?",
  ui_story_5045_50450701_64_dialog_content = "Eu... eu aprecio seus sentimentos gentis.",
  ui_story_5045_50450701_65_dialog_content = "Mas sua família aceitará alguém em uma posição tão baixa quanto a minha?",
  ui_story_5045_50450701_66_dialog_content = "Sofia, não se preocupe. Farei com que aceitem você.",
  ui_story_5045_50450701_67_dialog_content = "Se você brigar com sua família por minha causa, não vou conseguir me perdoar...",
  ui_story_5045_50450701_68_dialog_content = "Prometo me casar com você, mas, por favor, espere até que chegue a hora.",
  ui_story_5045_50450701_69_dialog_content = "Quero restaurar a honra da minha família...",
  ui_story_5045_50450701_70_dialog_content = "Sua família pode me aceitar assim que eu recuperar a propriedade de minha família.",
  ui_story_5045_50450701_71_dialog_content = "É por isso que você assinou o acordo de noivado!",
  ui_story_5045_50450701_72_dialog_content = "Objeção! Esses eventos passados não têm nada a ver com o caso de hoje.",
  ui_story_5045_50450701_73_dialog_content = "Embora seja um pouco embaraçoso, ter que assistir a história de amor de outra pessoa...",
  ui_story_5045_50450701_74_dialog_content = "Garanto-lhe que tudo isso está relacionado ao caso!",
  ui_story_5045_50450701_75_dialog_content = "Rejeitado!",
  ui_story_5045_50450701_76_dialog_content = "Meritíssimo, admito que tínhamos um bom relacionamento, mas agora acabou.",
  ui_story_5045_50450701_77_dialog_content = "Eu terminei com ele há muito tempo.",
  ui_story_5045_50450701_78_dialog_content = "Temos a liberdade de amar e a liberdade de não amar.",
  ui_story_5045_50450701_79_dialog_content = "Você não pode forçar alguém a desistir da felicidade de sua vida por causa do que está escrito em um pedaço de papel!",
  ui_story_5045_50450701_80_dialog_content = "Sim, o que o recorrente diz é bastante razoável.",
  ui_story_5045_50450701_81_dialog_content = "Mas depois que terminamos, Farrell ainda me assediava e frequentemente me seguia...",
  ui_story_5045_50450701_82_dialog_content = "Ele até invadiu minha casa!",
  ui_story_5045_50450701_83_dialog_content = "Hmm... Por que Sophie tem tanta certeza de que aquelas pegadas são de Farrell?",
  ui_story_5045_50450701_84_dialog_content = "É porque Farrell assediou Sophie que ela subconscientemente acredita que eles são dele, certo?",
  ui_story_5045_50450701_85_dialog_content = "Mas isso é apenas um palpite. Vamos perguntar ao cliente.",
  ui_story_5045_50450701_86_dialog_content = "Farrell, você admite a acusação de Sophie?",
  ui_story_5045_50450701_87_dialog_content = "Eu...",
  ui_story_5045_50450701_88_dialog_content = "Confesso que às vezes procurava Sophie depois da minha patrulha, mas só queria pedir a ela que me desse outra chance.",
  ui_story_5045_50450701_89_dialog_content = "Noite Branca no alto. Juro pela minha honra de cavaleiro que não fiz nada desagradável a Sophie.",
  ui_story_5045_50450701_90_dialog_content = "Sophie, alguém invadiu seu quarto?",
  ui_story_5045_50450701_91_dialog_content = "É tudo culpa minha. Eu deveria estar lá para te proteger...",
  ui_story_5045_50450701_92_dialog_content = "Parece que ele não vai admitir que as pegadas são dele.",
  ui_story_5045_50450701_93_dialog_content = "Se ao menos houvesse uma maneira de identificar as pegadas...",
  ui_story_5045_50450701_94_dialog_content = "... É isso! Vamos comparar as pegadas no tribunal!",
  ui_story_5045_50450701_95_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50450701_96_dialog_content = "Farrell, por favor, faça uma pegada neste papel.",
  ui_story_5045_50450701_97_dialog_content = "T-Tá...",
  ui_story_5045_50450701_98_dialog_content = "Você pode ver alguma diferença, PlayerName?",
  ui_story_5045_50450701_99_dialog_content = "As marcas deixadas pelas solas duras e saltos são aproximadamente as mesmas em profundidade.",
  ui_story_5045_50450701_100_dialog_content = "E há muitos rasgos nas bordas das solas. Parece que essas botas foram usadas por muitos anos.",
  ui_story_5045_50450701_101_dialog_content = "Mas o <color=#1875ad>pegadas</color> descobrimos que aquele dia era...",
  ui_story_5045_50450701_102_dialog_content = "Existe algum problema com isso?",
  ui_story_5045_50450701_103_dialog_content = "Tosse, tosse, cometi um erro!",
  ui_story_5045_50450701_104_dialog_content = "As pegadas da casa de Sophie tinham um padrão muito claro — um padrão obviamente feito por sapatos novos, mas os sapatos de Farrell são velhos e esfarrapados.",
  ui_story_5045_50450701_105_dialog_content = "As duas pegadas são flagrantemente diferentes.",
  ui_story_5045_50450701_106_dialog_content = "Quê?!",
  ui_story_5045_50450701_107_dialog_content = "Não! Talvez ele estivesse usando um novo par de sapatos naquele dia.",
  ui_story_5045_50450701_108_dialog_content = "Bem, isso não é uma impossibilidade.",
  ui_story_5045_50450701_109_dialog_content = "Meritíssimo, só tenho estas botas agora...",
  ui_story_5045_50450701_110_dialog_content = "Quem sabe? Talvez você tenha escondido as botas daquele dia em algum lugar que ninguém jamais as encontrará?",
  ui_story_5045_50450701_111_dialog_content = "Não... A pessoa que invadiu a casa de Sophie não era Farrell!",
  ui_story_5045_50450701_112_dialog_content = "E o que o leva tão firmemente a essa conclusão, PlayerName?",
  ui_story_5045_50450701_113_dialog_content = "As pegadas encontradas na casa de Sophie... As pegadas deixadas pelo calcanhar são bem distintas.",
  ui_story_5045_50450701_114_dialog_content = "Essas pegadas ocorrem apenas ao usar sapatos muito maiores que seus próprios pés.",
  ui_story_5045_50450701_115_dialog_content = "Portanto, as pegadas na casa de Sophie não poderiam pertencer a Farrell.",
  ui_story_5045_50450701_116_dialog_content = "Seus poderes de observação são assustadoramente astutos!",
  ui_story_5045_50450701_117_dialog_content = "Então, quem usaria deliberadamente botas maiores que seus próprios pés para deixar pegadas na casa de Sophie?",
  ui_story_5045_50450701_118_dialog_content = "Bom...",
  ui_story_5045_50450701_119_dialog_content = "Sophie, você mesmo fez essa prova?",
  ui_story_5045_50450701_120_dialog_content = "Ué, eu...",
  ui_story_5045_50450701_121_dialog_content = "Noite Branca nas alturas! Este é o Tribunal de Justiça, você é obrigado a dizer a verdade!",
  ui_story_5045_50450701_122_dialog_content = "Eu estava com medo de que você ainda mantivesse o julgamento original, então tomei minha própria decisão.",
  ui_story_5045_50450701_123_dialog_content = "Cometi um erro, Meritíssimo, mas realmente não quero me casar com Farrell!",
  ui_story_5045_50450701_124_dialog_content = "É porque Farrell não tem um centavo em seu nome?",
  ui_story_5045_50450701_125_dialog_content = "...",
  ui_story_5045_50450701_126_dialog_content = "Embora não tenha sido explicitamente declarado, seu acordo mencionava que se você tivesse dinheiro suficiente, você se casaria.",
  ui_story_5045_50450701_127_dialog_content = "Mas agora...",
  ui_story_5045_50450701_128_dialog_content = "<color=#1875ad>A condição da propriedade de Farrell</color> sofreu uma mudança significativa.",
  ui_story_5045_50450701_129_dialog_content = "O que foi?",
  ui_story_5045_50450701_130_dialog_content = "Ah, o que eu realmente queria dizer era...",
  ui_story_5045_50450701_131_dialog_content = "Farrell, você pode nos dizer por que quis doar todas as suas propriedades?",
  ui_story_5045_50450701_132_dialog_content = "Esta é minha responsabilidade como cavaleiro.",
  ui_story_5045_50450701_133_dialog_content = "Isso é verdade?",
  ui_story_5045_50450701_134_dialog_content = "Noite Branca nas alturas! Farrell, você deve saber que a honestidade é a qualidade mais básica de qualquer cavaleiro.",
  ui_story_5045_50450701_135_dialog_content = "Bom...",
  ui_story_5045_50450701_136_dialog_content = "Tudo bem, eu vou falar.",
  ui_story_5045_50450701_137_dialog_content = "Desculpe, esse último investimento foi outro pato manco...",
  ui_story_5045_50450701_138_dialog_content = "Mas desta vez será diferente!",
  ui_story_5045_50450701_139_dialog_content = "Farrell, você pode me emprestar mais algum dinheiro? Eu sei que vou escolher um vencedor desta vez!",
  ui_story_5045_50450701_140_dialog_content = "Sofia, tenho boas notícias.",
  ui_story_5045_50450701_141_dialog_content = "Doei todas as minhas propriedades.",
  ui_story_5045_50450701_142_dialog_content = "Mas... por que você faria algo assim?",
  ui_story_5045_50450701_143_dialog_content = "Assim, estaremos financeiramente iguais.",
  ui_story_5045_50450701_144_dialog_content = "Podemos nos casar.",
  ui_story_5045_50450701_145_dialog_content = "Sophie tentou por muito tempo, mas não conseguiu recuperar os bens de sua família.",
  ui_story_5045_50450701_146_dialog_content = "Eu não queria que ela trabalhasse tanto.",
  ui_story_5045_50450701_147_dialog_content = "Dinheiro e propriedades são coisas superficiais. O amor entre nós dois é mais importante do que qualquer coisa no mundo!",
  ui_story_5045_50450701_148_dialog_content = "Obviamente, Sophie não concorda com você nisso.",
  ui_story_5045_50450701_149_dialog_content = "... Certo, acho que não.",
  ui_story_5045_50450701_150_dialog_content = "Acredito que o dinheiro seja o pré-requisito para construir uma família.",
  ui_story_5045_50450701_151_dialog_content = "Eu nunca poderia concordar com a abordagem de Farrell, o que mostra que somos claramente incompatíveis - então terminei com ele.",
  ui_story_5045_50450701_152_dialog_content = "Há algo de errado com isso?",
  ui_story_5045_50450701_153_dialog_content = "Depois de nos casarmos, podemos trabalhar duro juntos e lentamente construir nossa própria riqueza!",
  ui_story_5045_50450701_154_dialog_content = "Mas eu não te amo mais.",
  ui_story_5045_50450701_155_dialog_content = "Ou melhor, eu não te amei desde o começo.",
  ui_story_5045_50450701_156_dialog_content = "Você está satisfeito agora?",
  ui_story_5045_50450701_157_dialog_content = "Sophie... Não... Não é verdade!",
  ui_story_5045_50450701_158_dialog_content = "Pobre Farrel...",
  ui_story_5045_50450701_159_dialog_content = "Leyn, Como nós lidamos com isto?",
  ui_story_5045_50450701_160_dialog_content = "Sempre pensei que os casos poderiam ser julgados apenas com base na lei.",
  ui_story_5045_50450701_161_dialog_content = "Mas as coisas são diferentes em Romance Division...",
  ui_story_5045_50450701_162_dialog_content = "Afinal, as emoções não podem ser explicadas e compreendidas com tanta facilidade.",
  ui_story_5045_50450701_163_dialog_content = "Se continuar assim, ambos terminarão com nada além de miséria e arrependimento.",
  ui_story_5045_50450701_164_dialog_content = "Espero que nosso julgamento possa proteger os dois ao mesmo tempo.",
  ui_story_5045_50450701_165_dialog_content = "Isso significa que você tem uma ideia?",
  ui_story_5045_50450701_166_dialog_content = "De uma vez só.",
  ui_story_5045_50450701_167_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50450701_168_dialog_content = "Noite Branca no alto. É hora do veredicto!",
  ui_story_5045_50450701_169_dialog_content = "Em primeiro lugar, embora o acordo de noivado entre Farrell e Sophie seja legal e eficaz...",
  ui_story_5045_50450701_170_dialog_content = "No entanto, o novo julgamento descobre que as diferenças entre Sophie e Farrell são irreconciliáveis.",
  ui_story_5045_50450701_171_dialog_content = "Em segundo lugar, a acusação de Sophie contra Farrell é falsa. Especificamente, Farrell não seguiu Sophie até sua casa e entrou em sua propriedade ilegalmente.",
  ui_story_5045_50450701_172_dialog_content = "Mas seu amor melancólico e unilateral não faz um casamento.",
  ui_story_5045_50450701_173_dialog_content = "Portanto, chegamos ao seguinte julgamento!",
  ui_story_5045_50450701_174_dialog_content = "Sophie deve apresentar a Farrell um pedido público de desculpas...",
  ui_story_5045_50450701_175_dialog_content = "... esclarecendo os motivos do cancelamento do noivado e as falsas acusações de intrusão ilegal de Farrell.",
  ui_story_5045_50450701_176_dialog_content = "Após o julgamento, Farrell não deve entrar em contato com Sophie em particular - a Guarda aplicará seu próprio monitoramento interno para esse efeito.",
  ui_story_5045_50450701_177_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50450701_178_dialog_content = "O julgamento acabou!",
  ui_story_5045_50450801_1_dialog_content = "<color=#737378>Hora: 12h00</color>",
  ui_story_5045_50450801_2_dialog_content = "<color=#737378>Local: Lumo Hall of Justice, Tribunal</color>",
  ui_story_5045_50450801_3_dialog_content = "Meritíssimo, pode ajudar-me a entregar isto à Sophie?",
  ui_story_5045_50450801_4_dialog_content = "Achei que Sophie e eu empinaríamos pipas juntas de novo...",
  ui_story_5045_50450801_5_dialog_content = "Agora parece que nunca vai acontecer... Não nesta vida.",
  ui_story_5045_50450801_6_dialog_content = "Embora eu esteja tentado a guardá-lo como lembrança...",
  ui_story_5045_50450801_7_dialog_content = "Foi feito pelo falecido pai de Sophie, então acho que ela pode precisar mais do que eu.",
  ui_story_5045_50450801_8_dialog_content = "Por favor, fique tranquilo, vamos entregá-lo para Sophie.",
  ui_story_5045_50450801_9_dialog_content = "Você vai conhecer alguém que te ama de verdade um dia!",
  ui_story_5045_50450801_10_dialog_content = "Por favor, diga a Sophie que esperarei por ela.",
  ui_story_5045_50450801_11_dialog_content = "... Acho que você merece um bom descanso.",
  ui_story_5045_50450801_12_dialog_content = "Suspirar...",
  ui_story_5045_50450801_13_dialog_content = "Sofia, por favor, espere!",
  ui_story_5045_50450801_14_dialog_content = "Tem algum problema?",
  ui_story_5045_50450801_15_dialog_content = "Farrell nos pediu para devolver esta pipa para você.",
  ui_story_5045_50450801_16_dialog_content = "Eu não preciso mais disso. Apenas jogue fora.",
  ui_story_5045_50450801_17_dialog_content = "Não foi feito pelo seu pai?",
  ui_story_5045_50450801_18_dialog_content = "... Aquele velho fazia muita pipa. Não quero mais este.",
  ui_story_5045_50450801_19_dialog_content = "Você realmente deve se preocupar com um assunto tão insignificante, Meritíssimo?",
  ui_story_5045_50450801_20_dialog_content = "Bom...",
  ui_story_5045_50450801_21_dialog_content = "Tenho uma última pergunta para te fazer, Sophie.",
  ui_story_5045_50450801_22_dialog_content = "Não tenho nada a dizer sobre isso.",
  ui_story_5045_50450801_23_dialog_content = "Você já enganou os outros emocionalmente?",
  ui_story_5045_50450801_24_dialog_content = "Como você pode usar a palavra \"enganado\" para descrever os relacionamentos que tive com eles?",
  ui_story_5045_50450801_25_dialog_content = "Se pedirmos ao Tribunal de Justiça para investigar suas relações interpessoais mais profundamente...",
  ui_story_5045_50450801_26_dialog_content = "Podemos descobrir que você não é tão inofensivo quanto parece.",
  ui_story_5045_50450801_27_dialog_content = "... Ninguém está me acusando - você não tem o direito de fazer isso!",
  ui_story_5045_50450801_28_dialog_content = "Na verdade, ninguém está apresentando queixa contra você.",
  ui_story_5045_50450801_29_dialog_content = "Porque seus alvos são os nobres.",
  ui_story_5045_50450801_30_dialog_content = "Mesmo que sejam enganados, eles não gostariam que ninguém mais soubesse disso.",
  ui_story_5045_50450801_31_dialog_content = "Desta vez, você encontrou muitos problemas inesperados, ou seja, ele foi totalmente sincero com você.",
  ui_story_5045_50450801_32_dialog_content = "E de alguma forma você não queria contar a verdade a ele.",
  ui_story_5045_50450801_33_dialog_content = "E então, quando Farrell literalmente desistiu de tudo por você...",
  ui_story_5045_50450801_34_dialog_content = "Chega!",
  ui_story_5045_50450801_35_dialog_content = "Já perdi muito tempo aqui. Desculpa, eu tenho que ir.",
  ui_story_5045_50450801_36_dialog_content = "Ela fugiu... Simples assim.",
  ui_story_5045_50450801_37_dialog_content = "Prometemos a Farrell que entregaríamos a pipa...",
  ui_story_5045_50450801_38_dialog_content = "Os casos aqui certamente não são exatamente claros...",
  ui_story_5045_50450801_39_dialog_content = "Mesmo que o julgamento tenha sido aprovado, minha alma labuta em tormento inquieto.",
  ui_story_5045_50450801_40_dialog_content = "Sim, eu sinto que... há um peso indescritível arrastando meu coração.",
  ui_story_5045_50450801_41_option_content = "Espero que Farrell não se importe muito.",
  ui_story_5045_50450801_42_dialog_content = "Fizemos tudo o que podíamos e a lei não tem respostas para as questões que permanecem.",
  ui_story_5045_50450801_43_dialog_content = "Argh, apenas esqueça isso. Vamos voltar rápido!",
  ui_story_5045_50450801_44_dialog_content = "Você tem razão. É melhor nos apressarmos e começarmos o próximo caso!",
  ui_story_5045_50450801_45_dialog_content = "Talvez possamos resolver qualquer caso sem problemas se tivermos um maior <color=#1875ad>Rapport</color>!",
  ui_story_5045_50450801_46_dialog_content = "Quê?!",
  ui_story_5045_50450801_47_dialog_content = "Eu só...",
  ui_story_5045_50450801_48_dialog_content = "Eu só queria voltar e descansar!",
  ui_story_5045_50450801_49_option_content = "Você fez o melhor que pôde!",
  ui_story_5045_50450801_50_dialog_content = "Acho que esse é o melhor resultado que poderíamos esperar.",
  ui_story_5045_50450801_51_dialog_content = "Esperemos.",
  ui_story_5045_50450801_52_dialog_content = "De qualquer forma, vamos aproveitar esta oportunidade para passear.",
  ui_story_5045_50450801_53_dialog_content = "Um pouco de exercício pode fazer você se sentir melhor.",
  ui_story_5045_50450801_54_dialog_content = "Se você diz.",
  ui_story_5045_50450801_55_dialog_content = "O clima de hoje está realmente...",
  ui_story_5045_50450801_56_dialog_content = "<color=#737378>Zuuup...</color>",
  ui_story_5045_50450801_57_dialog_content = "O vento é tão forte! Isso quase me surpreendeu.",
  ui_story_5045_50450801_58_dialog_content = "A pipa que eu estava segurando agora há pouco... Para onde foi aquela pipa?",
  ui_story_5045_50450801_59_dialog_content = "Bem ali!",
  ui_story_5045_50450801_60_dialog_content = "<color=#737378>Zuuup...</color>",
  ui_story_5045_50450801_61_dialog_content = "(Leyn?)",
  ui_story_5045_50450801_62_dialog_content = "(Como ele voou para o céu e pegou aquela pipa!?)",
  ui_story_5045_50450801_63_dialog_content = "(Espere...)",
  ui_story_5045_50450801_64_dialog_content = "(Por que sinto que já vi todo esse cenário acontecer antes?)",
  ui_story_5045_50450801_65_dialog_content = "(Eu me lembro agora!)",
  ui_story_5045_50450801_66_dialog_content = "(É por causa de Farrell, ele conheceu Sophie porque ele...)",
  ui_story_5045_50450801_67_dialog_content = "Parece que este papagaio gosta mesmo é de fugir dos seus donos.",
  ui_story_5045_50450801_68_dialog_content = "Ou todas as pipas simplesmente desejam buscar a liberdade ao vento?",
  ui_story_5045_50450801_69_dialog_content = "(É verdade que uma pipa pode voar no céu azul por causa do vento que a levanta.)",
  ui_story_5045_50450801_70_dialog_content = "(Mas por que temos que restringir sua liberdade com um fio de seda?)",
  ui_story_5045_50450801_71_dialog_content = "PlayerName, Eu sei o que você está pensando.",
  ui_story_5045_50450801_72_dialog_content = "Mas acredito que liberdade sem restrições não é liberdade real.",
  ui_story_5045_50450801_73_dialog_content = "Se a pipa não tiver o suporte do fio, logo será lançada no deserto árido pelo vento impiedoso.",
  ui_story_5045_50450801_74_dialog_content = "O recente aumento do amor livre em Lumopolis é como o desejo da pipa pelo céu.",
  ui_story_5045_50450801_75_dialog_content = "Se não houver fio - o fio da justiça...",
  ui_story_5045_50450801_76_dialog_content = "Nem a liberdade de amar nem a liberdade de não amar podem ser garantidas.",
  ui_story_5045_50450801_77_dialog_content = "Eu tenho que entregá-lo a você...",
  ui_story_5045_50450801_78_dialog_content = "A partir de uma simples pipa voando pelo céu, você conseguiu desvendar os mistérios da vida, do amor e da liberdade.",
  ui_story_5045_50450801_79_dialog_content = "Ah! Me desculpe.",
  ui_story_5045_50450801_80_dialog_content = "Por favor, não dê atenção ao meu absurdo!",
  ui_story_5045_50450801_81_dialog_content = "É só que, depois desse recente julgamento, acho que entendo como prosseguir com outros casos da Divisão Romance.",
  ui_story_5045_50450801_82_dialog_content = "Claro, devo tudo à sua ajuda.",
  ui_story_5045_50450801_83_option_content = "Sem problemas!",
  ui_story_5045_50450801_84_dialog_content = "Na verdade, você fez a maior parte do trabalho sozinho.",
  ui_story_5045_50450801_85_dialog_content = "Acabei de apresentar algumas sugestões pouco profissionais da periferia.",
  ui_story_5045_50450801_86_dialog_content = "Você é muito modesto.",
  ui_story_5045_50450801_87_dialog_content = "Se não fosse por sua sugestão, quem sabe quando eu teria terminado aquele primeiro caso.",
  ui_story_5045_50450801_88_option_content = "Parece que há algo em sua mente?",
  ui_story_5045_50450801_89_dialog_content = "Escusado será dizer que nada passa por você, PlayerName.",
  ui_story_5045_50450801_90_dialog_content = "Para ser honesto, estive pensando... se ao menos não houvesse amor no mundo.",
  ui_story_5045_50450801_91_dialog_content = "Huh? Você não quer trabalhar na Divisão Romance?",
  ui_story_5045_50450801_92_dialog_content = "Não, não, eu aprecio minha posição atual.",
  ui_story_5045_50450801_93_dialog_content = "Eu apenas sinto cada vez mais como se o amor fosse como veneno.",
  ui_story_5045_50450801_94_dialog_content = "Pode fazer um cavaleiro honesto de repente se tornar tão humilde...",
  ui_story_5045_50450801_95_dialog_content = "O amor é realmente difícil de entender, mas não podemos deixar que esses casos nos atinjam.",
  ui_story_5045_50450801_96_dialog_content = "Deve haver muitos casos de amor verdadeiramente maravilhoso no mundo.",
  ui_story_5045_50450801_97_dialog_content = "A razão pela qual você não os viu é que todos esses amantes felizes nunca acabariam no Tribunal de Justiça.",
  ui_story_5045_50450801_98_dialog_content = "Amor verdadeiramente maravilhoso? Eu me pergunto como seria isso?",
  ui_story_5045_50450801_99_dialog_content = "Duas pessoas se apreciam, confiam uma na outra e se superam uma pela outra.",
  ui_story_5045_50450801_100_dialog_content = "Isso é o que eu considero ser um amor verdadeiramente maravilhoso.",
  ui_story_5045_50450801_101_dialog_content = "Certo...",
  ui_story_5045_50450801_102_dialog_content = "O que te deixou com esse humor filosófico, de repente?",
  ui_story_5045_50450801_103_dialog_content = "Suas palavras me lembraram de alguém.",
  ui_story_5045_50450801_104_dialog_content = "Quem? Eu os conheço?",
  ui_story_5045_50450801_105_dialog_content = "É você, PlayerName.",
  ui_story_5045_50450801_106_dialog_content = "Quê?!",
  ui_story_5045_50450801_107_dialog_content = "Acontece que o amor entre amantes é tão parecido com a amizade entre aliados?",
  ui_story_5045_50450801_108_dialog_content = "Isso é bem verdade... Hahaha...",
  ui_story_5045_50450801_109_dialog_content = "Nesse caso, desejo a todos o melhor em assuntos do coração.",
  ui_story_5045_50450801_110_dialog_content = "Noite Branca no alto, espero que o amor de todos continue feliz por muito, muito tempo.",
  ui_story_5045_50450801_111_dialog_content = "Mas o que vamos fazer com essa pipa, agora?",
  ui_story_5045_50450801_112_dialog_content = "Por enquanto, vamos cuidar disso em nome deles.",
  ui_story_5045_50450801_113_dialog_content = "<color=#737378>Zuuup...</color>",
  ui_story_5045_50450801_114_dialog_content = "Ah, o vento está aumentando novamente. Desta vez, vou cuidar bem dessa pipa.",
  ui_story_5045_50450801_115_dialog_content = "May ser devíamos deixar a pipa voar mais uma vez.",
  ui_story_5045_50450801_116_dialog_content = "Hã?",
  ui_story_5045_50450801_117_dialog_content = "PlayerName, você já empinou uma pipa antes?",
  ui_story_5045_50450901_1_dialog_content = "<color=#737378>Horário: 15h</color>",
  ui_story_5045_50450901_2_dialog_content = "<color=#737378>Localização: Lumo Hall of Justice, Escritório da Divisão Romance</color>",
  ui_story_5045_50450901_3_dialog_content = "(Nunca pensei que terminaria um caso tão cedo.)",
  ui_story_5045_50450901_4_dialog_content = "(Minhas habilidades legais não podem ser melhores do que minhas habilidades psíquicas, podem?)",
  ui_story_5045_50450901_5_dialog_content = "(Se Irridon viu nosso julgamento, ela pode pensar em me pagar mais.)",
  ui_story_5045_50450901_6_dialog_content = "(Quando chegar a hora, heh, eu darei Vice e os outros uma surpresa!)",
  ui_story_5045_50450901_7_dialog_content = "(Mas, novamente...)",
  ui_story_5045_50450901_8_dialog_content = "Por que tantas pessoas estão arquivando hoje!?",
  ui_story_5045_50450901_9_dialog_content = "Huh? Perdeu o interesse no trabalho experimental tão cedo?",
  ui_story_5045_50450901_10_dialog_content = "N-De jeito nenhum!",
  ui_story_5045_50450901_11_dialog_content = "Ah, o que traz nossa sempre ocupada Senhora Irridon aqui?",
  ui_story_5045_50450901_12_dialog_content = "Zzz...",
  ui_story_5045_50450901_13_dialog_content = "Tina, acordar!",
  ui_story_5045_50450901_14_dialog_content = "Certo...",
  ui_story_5045_50450901_15_dialog_content = "Angel, o que você está esperando? Vá fazer um chá para o nosso estimado juiz supremo!",
  ui_story_5045_50450901_16_dialog_content = "... Oh.",
  ui_story_5045_50450901_17_dialog_content = "Não há necessidade.",
  ui_story_5045_50450901_18_dialog_content = "Ouvi dizer que você julgou um caso esta manhã, então vim avaliar as consequências.",
  ui_story_5045_50450901_19_dialog_content = "O caso foi conduzido pelo livro.",
  ui_story_5045_50450901_20_dialog_content = "Pelo contrário, meu julgamento amanhã inspirará o mundo e se tornará um precedente para as gerações futuras aprenderem e imitarem.",
  ui_story_5045_50450901_21_dialog_content = "Quando chegar a hora, sinta-se à vontade para voltar e testemunhar por si mesmo.",
  ui_story_5045_50450901_22_dialog_content = "Veremos. Talvez, se eu tiver tempo.",
  ui_story_5045_50450901_23_dialog_content = "Acabei de ouvir que o caso esta manhã causou um grande rebuliço. Eu quero saber os detalhes.",
  ui_story_5045_50450901_24_dialog_content = "Senhora Irridon, PlayerName e eu tentei o caso desta manhã.",
  ui_story_5045_50450901_25_dialog_content = "Registrei os detalhes e o processo de julgamento neste caderno. Por favor, dê uma olhada.",
  ui_story_5045_50450901_26_dialog_content = "Impressionante. Você formou alguns bons hábitos desde que chegou aqui, PlayerName.",
  ui_story_5045_50450901_27_dialog_content = "Você acabou de dizer que este caso causou um rebuliço?",
  ui_story_5045_50450901_28_dialog_content = "De uma vez só.",
  ui_story_5045_50450901_29_dialog_content = "Então, como a opinião pública está atualmente em relação a este caso?",
  ui_story_5045_50450901_30_dialog_content = "O que você achou?",
  ui_story_5045_50450901_31_dialog_content = "Bem... Acho que deve ser bem positivo, não?",
  ui_story_5045_50450901_32_dialog_content = "PlayerName provou ser digno de ser escolhido pessoalmente por você, Juiz Chefe, para nos auxiliar aqui.",
  ui_story_5045_50450901_33_dialog_content = "Com a ajuda de PlayerName, é natural que Leyn deve fazer algum progresso também.",
  ui_story_5045_50450901_34_dialog_content = "Talvez não demore muito para que ele se torne o segundo melhor juiz da Divisão Romance!",
  ui_story_5045_50450901_35_dialog_content = "Leyn, são PlayerNameregistros completos?",
  ui_story_5045_50450901_36_dialog_content = "Sim, seus registros são muito completos, de fato.",
  ui_story_5045_50450901_37_dialog_content = "A investigação apenas arranhou a superfície, e as partes não foram autorizadas a se explicar totalmente no tribunal...",
  ui_story_5045_50450901_38_dialog_content = "Lembro que suas tentativas anteriores não foram tão desleixadas.",
  ui_story_5045_50450901_39_dialog_content = "Os casos da Divisão Romance são diferentes de tudo que encontramos antes.",
  ui_story_5045_50450901_40_dialog_content = "Também estou tentando descobrir a melhor forma de lidar com esses casos",
  ui_story_5045_50450901_41_dialog_content = "A Divisão Romance acabou de ser estabelecida e não há casos para aprendermos.",
  ui_story_5045_50450901_42_dialog_content = "Eu entendo a pressão.",
  ui_story_5045_50450901_43_dialog_content = "Mas lembre-se de que mesmo um pequeno caso aos nossos olhos pode afetar a vida das partes envolvidas.",
  ui_story_5045_50450901_44_dialog_content = "A maneira como você lida com cada caso afetará a atitude do povo de Lumopolis em relação aos relacionamentos amorosos no futuro.",
  ui_story_5045_50450901_45_dialog_content = "Parece que a opinião pública, como resultado de assumir o caso esta manhã, não é muito boa...",
  ui_story_5045_50450901_46_dialog_content = "O caso desta manhã nos mostra que o custo de violar um acordo de noivado é insignificante.",
  ui_story_5045_50450901_47_dialog_content = "Podemos ver mais casos envolvendo a dissolução de compromissos.",
  ui_story_5045_50450901_48_dialog_content = "Preparem-se.",
  ui_story_5045_50450901_49_dialog_content = "O julgamento de Leyn apenas aumentou nossa carga de trabalho?",
  ui_story_5045_50450901_50_dialog_content = "Como todos os nossos casos são do mesmo tipo, devemos ser capazes de tratá-los muito mais rapidamente.",
  ui_story_5045_50450901_51_dialog_content = "Se isso for verdade, esses casos serão entregues a Leyn e PlayerName no futuro.",
  ui_story_5045_50450901_52_dialog_content = "Huh? Mas com todos esses casos...",
  ui_story_5045_50450901_53_dialog_content = "Quantas sessões serão necessárias para concluir cada tentativa?",
  ui_story_5045_50451001_1_dialog_content = "<color=#737378>Hora: 14:00</color>",
  ui_story_5045_50451001_2_dialog_content = "<color=#737378>Localização: Lumo Hall of Justice, Escritório da Divisão Romance</color>",
  ui_story_5045_50451001_3_dialog_content = "Bocejar-",
  ui_story_5045_50451001_4_dialog_content = "Huh? PlayerName, por que você está me olhando tão sério?",
  ui_story_5045_50451001_5_dialog_content = "Você caiu no sono agora?",
  ui_story_5045_50451001_6_dialog_content = "Claro, eu cochilei...",
  ui_story_5045_50451001_7_dialog_content = "Mas você estava tão feliz agora...",
  ui_story_5045_50451001_8_dialog_content = "Pensando bem, tive um sonho tão lindo agora... Heeheehee!",
  ui_story_5045_50451001_9_dialog_content = "Ahem... De qualquer forma, contanto que você esteja acordado agora.",
  ui_story_5045_50451001_10_dialog_content = "Não sei exatamente como devo ajudá-lo.",
  ui_story_5045_50451001_11_dialog_content = "Então, quando você estava dormindo, eu apenas ajudei a falar com algumas das pessoas que estavam arquivando casos.",
  ui_story_5045_50451001_12_dialog_content = "Novos casos?",
  ui_story_5045_50451001_13_dialog_content = "Vejamos...",
  ui_story_5045_50451001_14_dialog_content = "Bem, obrigado, PlayerName, mas essas reclamações não são de responsabilidade da Divisão Romance.",
  ui_story_5045_50451001_15_dialog_content = "R-Sério? Desculpe. Acho que fiz mais mal do que bem...",
  ui_story_5045_50451001_16_dialog_content = "Não leve isso a sério.",
  ui_story_5045_50451001_17_dialog_content = "Não te contei antes de dormir, então a culpa é minha.",
  ui_story_5045_50451001_18_dialog_content = "Você pode ter certeza, porém, que embora minhas horas de trabalho sejam curtas, minha eficiência é muito alta.",
  ui_story_5045_50451001_19_dialog_content = "Eu vou te ensinar meu único segredo de trabalho em apenas um momento.",
  ui_story_5045_50451001_20_dialog_content = "Uau, isso é incrível! Vamos começar!",
  ui_story_5045_50451001_21_dialog_content = "Não há pressa. Apenas me responda uma pergunta primeiro.",
  ui_story_5045_50451001_22_dialog_content = "Se um dia você se apaixonasse por alguém, você o deixaria saber?",
  ui_story_5045_50451001_23_option_content = "De uma vez só.",
  ui_story_5045_50451001_24_dialog_content = "Se eu soubesse que era realmente amor, eu gostaria que eles soubessem.",
  ui_story_5045_50451001_25_dialog_content = "Mesmo que eles me recusassem, não importaria. Eu faria isso por respeito ao sentimento.",
  ui_story_5045_50451001_26_dialog_content = "Eu nunca esperei que você fosse tão perspicaz a esse respeito, PlayerName.",
  ui_story_5045_50451001_27_dialog_content = "Espero que a pessoa que eu gosto pense igual a você, heehee.",
  ui_story_5045_50451001_28_option_content = "Não.",
  ui_story_5045_50451001_29_dialog_content = "Se eles não gostassem de mim, confessar meu amor só iria causar problemas para eles.",
  ui_story_5045_50451001_30_dialog_content = "Então, eu não acho que eu diria a eles com muita pressa.",
  ui_story_5045_50451001_31_dialog_content = "Heehee, você é tão tímido quanto eu pensava, PlayerName.",
  ui_story_5045_50451001_32_option_content = "Não sei.",
  ui_story_5045_50451001_33_dialog_content = "Não posso prever como me sentirei no futuro.",
  ui_story_5045_50451001_34_dialog_content = "Talvez eu saiba o que fazer então.",
  ui_story_5045_50451001_35_dialog_content = "Hmph, que resposta chata.",
  ui_story_5045_50451001_36_dialog_content = "Eu não entendo o que você quer dizer. Por que você pergunta?",
  ui_story_5045_50451001_37_dialog_content = "Parece que isso não tem nada a ver com o nosso trabalho.",
  ui_story_5045_50451001_38_dialog_content = "Tem tudo a ver com o nosso trabalho.",
  ui_story_5045_50451001_39_dialog_content = "Em que divisão estamos trabalhando?",
  ui_story_5045_50451001_40_dialog_content = "A Divisão Romântica.",
  ui_story_5045_50451001_41_dialog_content = "Então, é claro, devemos discutir tópicos relacionados ao amor.",
  ui_story_5045_50451001_42_dialog_content = "E discutir o tema do amor pode resultar rapidamente em um relacionamento de trabalho mais próximo.",
  ui_story_5045_50451001_43_dialog_content = "Espero que possamos cooperar alegremente.",
  ui_story_5045_50451001_44_dialog_content = "Nesse caso...",
  ui_story_5045_50451001_45_dialog_content = "Como você responderia a essa pergunta agora, Tina?",
  ui_story_5045_50451001_46_dialog_content = "Haha, eu não esperava que você virasse o jogo contra mim assim. Bem, deixe-me dizer-lhe.",
  ui_story_5045_50451001_47_dialog_content = "Eu nunca tomaria a iniciativa. Afinal, sou uma dama.",
  ui_story_5045_50451001_48_dialog_content = "No máximo... secretamente, aumentaria ativamente as chances de nos encontrarmos.",
  ui_story_5045_50451001_49_dialog_content = "Mas se vocês não se veem, como podem saber se realmente gostam deles?",
  ui_story_5045_50451001_50_dialog_content = "O que você fará se a outra pessoa for errada para você?",
  ui_story_5045_50451001_51_dialog_content = "Nunca considerei as coisas por essa perspectiva...",
  ui_story_5045_50451001_52_dialog_content = "Isso é como você, PlayerName. Você entende mais do que Leyn!",
  ui_story_5045_50451001_53_dialog_content = "Você é realmente um ótimo assistente. Com certeza vou incomodá-lo com tais assuntos de agora em diante.",
  ui_story_5045_50451001_54_dialog_content = "Por favor, ajude-me a receber todos os casos, verifique se as declarações são verdadeiras e determine as leis e regulamentos relevantes...",
  ui_story_5045_50451001_55_dialog_content = "Então resuma os detalhes do caso para mim!",
  ui_story_5045_50451001_56_dialog_content = "Quer dizer, você basicamente quer que eu faça tudo por você?",
  ui_story_5045_50451001_57_dialog_content = "Sentarei na cadeira do juiz e, por fim, conduzirei o julgamento. Esta é a parte mais crucial e exaustiva.",
  ui_story_5045_50451001_58_dialog_content = "Mas você parece bastante interessado no julgamento... Por que você não se junta a mim no tribunal?",
  ui_story_5045_50451001_59_dialog_content = "<size=32>Ainda bem que ela prometeu me pagar um extra...</size>",
  ui_story_5045_50451001_60_dialog_content = "Hum? Você disse alguma coisa?",
  ui_story_5045_50451001_61_dialog_content = "Eu disse... com tantos casos para processar, por qual devemos começar?",
  ui_story_5045_50451001_62_dialog_content = "Não perca seu tempo com assuntos tão insignificantes... Bocejo—",
  ui_story_5045_50451001_63_dialog_content = "Basta escolher o que está em suas mãos agora.",
  ui_story_5045_50451001_64_dialog_content = "\"Pedido para que a ré Fanny e o autor Bacon sejam <color=#1875ad>divorciado</color> de acordo com a lei...\"?",
  ui_story_5045_50451001_65_dialog_content = "Certo! Vamos começar!",
  ui_story_5045_50451001_66_dialog_content = "Zzz...",
  ui_story_5045_50451001_67_dialog_content = "Ela queria começar a trabalhar ou começar a dormir...",
  ui_story_5045_50451101_1_dialog_content = "<color=#737378>Hora: 9:00 AM</color>",
  ui_story_5045_50451101_2_dialog_content = "<color=#737378>Local: Lumo Hall of Justice, Tribunal</color>",
  ui_story_5045_50451101_3_dialog_content = "PlayerName, você se lembra qual caso estamos julgando hoje?",
  ui_story_5045_50451101_4_dialog_content = "Eu lembro! O queixoso, <color=#1875ad>Bacon</color> e o réu, <color=#1875ad>fanny</color>de...",
  ui_story_5045_50451101_5_option_content = "Disputa de divórcio",
  ui_story_5045_50451101_6_dialog_content = "Isso mesmo. Parece que a lição antes do julgamento está realmente funcionando em você.",
  ui_story_5045_50451101_7_dialog_content = "Talvez um dia, em breve, você consiga terminar um teste por conta própria.",
  ui_story_5045_50451101_8_option_content = "Anulação de noivado",
  ui_story_5045_50451101_9_dialog_content = "Uau! Parece que a lição antes do julgamento não está funcionando em você.",
  ui_story_5045_50451101_10_dialog_content = "Sua responsabilidade mais básica é lembrar as informações nesses arquivos de caso antes da sessão do tribunal.",
  ui_story_5045_50451101_11_dialog_content = "Na próxima tentativa, você deve tentar assistir, ouvir e aprender mais.",
  ui_story_5045_50451101_12_dialog_content = "Ah, o arquivo do caso diz \"disputa de divórcio\"!",
  ui_story_5045_50451101_13_dialog_content = "Nunca pensei que tropeçaria no primeiro obstáculo assim...",
  ui_story_5045_50451101_14_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451101_15_dialog_content = "<size=45>Noite Branca no alto. Tribunal está agora em sessão!</size>",
  ui_story_5045_50451101_16_dialog_content = "Avante, Noite Branca!",
  ui_story_5045_50451101_17_dialog_content = "(Há tantas pessoas ouvindo hoje! Acho que todos estão realmente prestando muita atenção aos casos da Divisão de Romance atualmente...)",
  ui_story_5045_50451101_18_dialog_content = "Em primeiro lugar, vamos ouvir o que o autor tem a dizer.",
  ui_story_5045_50451101_19_dialog_content = "Meritíssimo, meu nome é Bacon.",
  ui_story_5045_50451101_20_dialog_content = "Por que o queixoso parece tão assustado?",
  ui_story_5045_50451101_21_dialog_content = "Bacon, por favor, não fique nervoso ou com medo.",
  ui_story_5045_50451101_22_dialog_content = "A Sala da Justiça é o lugar mais justo e seguro de Lumópolis.",
  ui_story_5045_50451101_23_dialog_content = "Você pode declarar sua solicitação com confiança aqui.",
  ui_story_5045_50451101_24_dialog_content = "Eu quero me divorciar da minha esposa, Fanny...",
  ui_story_5045_50451101_25_dialog_content = "Bacon, você realmente tem que fazer isso?",
  ui_story_5045_50451101_26_dialog_content = "Pode... Você pode me deixar terminar?",
  ui_story_5045_50451101_27_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451101_28_dialog_content = "O réu se absterá de interromper o autor.",
  ui_story_5045_50451101_29_dialog_content = "...",
  ui_story_5045_50451101_30_dialog_content = "Bacon, por que você quer se divorciar de sua esposa Fanny?",
  ui_story_5045_50451101_31_dialog_content = "Porque nós... nós somos tão diferentes!",
  ui_story_5045_50451101_32_dialog_content = "Quanto tempo você ficou casado?",
  ui_story_5045_50451101_33_dialog_content = "Sete anos.",
  ui_story_5045_50451101_34_dialog_content = "Alguns anos atrás, eu tinha um emprego que dava para nos sustentar, então a vida era tolerável.",
  ui_story_5045_50451101_35_dialog_content = "Mas no ano passado, de repente fui demitido e perdi minha fonte de renda.",
  ui_story_5045_50451101_36_dialog_content = "Desde então, Fanny me importuna todos os dias em casa e se ressente de mim por não ter um emprego.",
  ui_story_5045_50451101_37_dialog_content = "Acabei de perceber que o amor entre nós foi corroído pelo tempo.",
  ui_story_5045_50451101_38_dialog_content = "Tudo o que vemos agora são as deficiências uns dos outros.",
  ui_story_5045_50451101_39_dialog_content = "Não quero perder mais tempo com esse tipo de casamento... Quero o divórcio, para poder me libertar novamente.",
  ui_story_5045_50451101_40_dialog_content = "Em outras palavras, seu relacionamento acabou?",
  ui_story_5045_50451101_41_dialog_content = "Réu, você concorda com o autor?",
  ui_story_5045_50451101_42_dialog_content = "Meritíssimo, eu não concordo.",
  ui_story_5045_50451101_43_dialog_content = "Bacon ficou muito deprimido depois que seu empregador o dispensou.",
  ui_story_5045_50451101_44_dialog_content = "Eu só queria animar Bacon, então constantemente pedia para ele conversar e caminhar comigo.",
  ui_story_5045_50451101_45_dialog_content = "Nunca pensei em deixar Bacon.",
  ui_story_5045_50451101_46_dialog_content = "Desde que ele perdeu o emprego, tenho trabalhado meio período para complementar nossas economias. Eu só reclamei talvez uma ou duas vezes.",
  ui_story_5045_50451101_47_dialog_content = "Mas desde...",
  ui_story_5045_50451101_48_dialog_content = "Mas, no final das contas, se fiz algo errado, eu mudo!",
  ui_story_5045_50451101_49_dialog_content = "(Parece que Fanny queria dizer algo agora, mas de repente <color=#1875ad>mudou de idéia</color>...)",
  ui_story_5045_50451101_50_dialog_content = "É assim que é.",
  ui_story_5045_50451101_51_dialog_content = "Isso está certo?",
  ui_story_5045_50451101_52_dialog_content = "Acho que Bacon deve ter ficado desempregado por muito tempo agora... Ele fica agitado facilmente.",
  ui_story_5045_50451101_53_dialog_content = "É por isso que ele quer se divorciar de mim - ele está tão estressado!",
  ui_story_5045_50451101_54_dialog_content = "Mas quero acreditar que Bacon vai melhorar eventualmente.",
  ui_story_5045_50451101_55_dialog_content = "E, aconteça o que acontecer, não vou me divorciar dele!",
  ui_story_5045_50451101_56_dialog_content = "Entendi.",
  ui_story_5045_50451101_57_dialog_content = "Então... Bocejo—",
  ui_story_5045_50451101_58_dialog_content = "Tina, estamos no meio de um teste! Não durma!",
  ui_story_5045_50451101_59_dialog_content = "Huh...? Ah!",
  ui_story_5045_50451101_60_dialog_content = "Obrigado por me acordar, PlayerName. Quase fiz papel de bobo agora pouco...",
  ui_story_5045_50451101_61_dialog_content = "Bem, confio em você para escolher um caso como este. Não é fácil tentar.",
  ui_story_5045_50451101_62_dialog_content = "Depois que essa onda de amor livre varreu Lumopolis, o número de casos de divórcio realmente aumentou.",
  ui_story_5045_50451101_63_dialog_content = "Mas conceder ou não o divórcio é o problema que a Divisão Romance vem analisando há algum tempo.",
  ui_story_5045_50451101_64_dialog_content = "Quanto ao caso atual, PlayerName...",
  ui_story_5045_50451101_65_dialog_content = "Você tem alguma outra ideia?",
  ui_story_5045_50451101_66_dialog_content = "Parece que você também não encontrou nenhuma pista útil.",
  ui_story_5045_50451101_67_dialog_content = "Th-Esta pista é inútil?",
  ui_story_5045_50451101_67X1_dialog_content = "Além disso...",
  ui_story_5045_50451101_68_dialog_content = "Oh eu sei!",
  ui_story_5045_50451101_69_dialog_content = "Tina, dê uma olhada neste!",
  ui_story_5045_50451101_70_dialog_content = "Agora você é capaz de gravar as declarações de ambos os lados da corte sem mim? Nada mal.",
  ui_story_5045_50451101_71_dialog_content = "Você realmente é uma alegria de assistente.",
  ui_story_5045_50451101_72_dialog_content = "Mas não fique atento apenas aos registros!",
  ui_story_5045_50451101_73_dialog_content = "Quanto ao caso atual...",
  ui_story_5045_50451101_74_dialog_content = "Não acho que os fundamentos de Bacon para o divórcio sejam completamente arbitrários.",
  ui_story_5045_50451101_75_dialog_content = "Bacon não disse que sentia que não havia amor entre eles?",
  ui_story_5045_50451101_76_dialog_content = "Casamento sem amor... É difícil imaginar.",
  ui_story_5045_50451101_77_dialog_content = "Mas Fanny também explicou como ela só queria animar Bacon.",
  ui_story_5045_50451101_78_dialog_content = "E parecia claro para mim que Fanny havia decidido ajudar Bacon nessa fase difícil, não importa o que acontecesse.",
  ui_story_5045_50451101_79_dialog_content = "Isso faz sentido, Bacon está desempregado e deprimido...",
  ui_story_5045_50451101_80_dialog_content = "Mas Fanny não apenas não se importou, como também prometeu ficar com Bacon e ajudá-lo a se reerguer.",
  ui_story_5045_50451101_81_dialog_content = "Esse tipo de relacionamento entre marido e mulher é simplesmente uma história de Lumopolis!",
  ui_story_5045_50451101_82_dialog_content = "Se Bacon está apenas zangado neste momento, e o juiz decide conceder-lhe o divórcio...",
  ui_story_5045_50451101_83_dialog_content = "O Deus da Luz não vai me roubar a chance de encontrar meu verdadeiro amor?",
  ui_story_5045_50451101_84_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451101_85_dialog_content = "Noite Branca no alto. É hora do veredicto!",
  ui_story_5045_50451101_86_dialog_content = "O Tribunal de Justiça finalmente decidiu que a relação entre o autor Bacon e a ré Fanny não deve ser dissolvida.",
  ui_story_5045_50451101_87_dialog_content = "Uma união formada diante dos olhos do Deus da Luz não deve ser descartada tão apressadamente.",
  ui_story_5045_50451101_88_dialog_content = "Por favor, continuem a se amar e trabalhar em seu casamento.",
  ui_story_5045_50451101_89_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451101_90_dialog_content = "O julgamento acabou!",
  ui_story_5045_50451101_91_dialog_content = "O lado de Fanny da história é muito comovente.",
  ui_story_5045_50451101_92_dialog_content = "Mas você não sente que ela está escondendo alguma coisa deliberadamente?",
  ui_story_5045_50451101_93_dialog_content = "PlayerName, seus poderes de observação são bastante impressionantes.",
  ui_story_5045_50451101_94_dialog_content = "Vamos perguntar a Fanny o que ela está escondendo.",
  ui_story_5045_50451101_95_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451101_96_dialog_content = "Noite Branca lá no alto, Fanny, tem certeza de que nos contou toda a história?",
  ui_story_5045_50451101_97_dialog_content = "Eu acho que sim...",
  ui_story_5045_50451101_98_dialog_content = "Se você não vai dizer... então me permita!",
  ui_story_5045_50451101_99_dialog_content = "Meritíssimo, Fanny sabe que não temos muito dinheiro, mas mesmo assim ela pegou um grande empréstimo e agora estamos endividados.",
  ui_story_5045_50451101_100_dialog_content = "Bacon, como te disse, era tudo para ti.",
  ui_story_5045_50451101_101_dialog_content = "Por mim?",
  ui_story_5045_50451101_102_dialog_content = "Você... Você pegou emprestado sem nem me pedir!",
  ui_story_5045_50451101_103_dialog_content = "Eu só... eu só...",
  ui_story_5045_50451101_104_dialog_content = "Fanny, é verdade que você pediu dinheiro emprestado sem o conhecimento de Bacon?",
  ui_story_5045_50451101_105_dialog_content = "... É verdade.",
  ui_story_5045_50451101_106_dialog_content = "Meritíssimo, não posso viver com alguém que mentiu para mim desse jeito.",
  ui_story_5045_50451101_107_dialog_content = "Por favor, permita-me me divorciar de Fanny.",
  ui_story_5045_50451101_108_dialog_content = "Eu tenho apenas um pedido - por favor, vamos discutir a divisão de nossos bens.",
  ui_story_5045_50451101_109_dialog_content = "Fanny, você concorda com o pedido de Bacon?",
  ui_story_5045_50451101_110_dialog_content = "Suspiro, não tenho mais nada a dizer...",
  ui_story_5045_50451101_111_dialog_content = "Eu concordo com o que Bacon quiser.",
  ui_story_5045_50451101_112_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451101_113_dialog_content = "Noite Branca no alto. É hora do veredicto!",
  ui_story_5045_50451101_114_dialog_content = "Devido a diferenças irreconciliáveis entre o autor Bacon e a ré Fanny, o Tribunal de Justiça decide que o casamento deles deve ser dissolvido imediatamente.",
  ui_story_5045_50451101_115_dialog_content = "De acordo com o pedido das partes, elas já podem negociar a divisão de seus bens entre si.",
  ui_story_5045_50451101_116_dialog_content = "Depois disso, eles assinarão o acordo correspondente na presença do juiz.",
  ui_story_5045_50451101_117_dialog_content = "Se você não aceitar esta sentença, poderá recorrer de acordo com as disposições do Tribunal de Justiça.",
  ui_story_5045_50451101_118_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451101_119_dialog_content = "O julgamento acabou!",
  ui_story_5045_50451201_1_dialog_content = "<color=#737378>Hora: 11h00</color>",
  ui_story_5045_50451201_2_dialog_content = "<color=#737378>Local: Lumo Hall of Justice, Tribunal</color>",
  ui_story_5045_50451201_3_dialog_content = "Suspiro, Tina realmente vai me deixar fazer isso sozinha...?",
  ui_story_5045_50451201_4_dialog_content = "Aconteça o que acontecer, não me acorde antes das duas da tarde.",
  ui_story_5045_50451201_5_dialog_content = "Mas o acordo de propriedade entre Bacon e Fanny...",
  ui_story_5045_50451201_6_dialog_content = "Contanto que ninguém se oponha ao acordo, você pode simplesmente deixá-los ir em frente e assiná-lo.",
  ui_story_5045_50451201_7_dialog_content = "Eu sei que você pode lidar com isso... Bocejo—",
  ui_story_5045_50451201_8_dialog_content = "Zzz...",
  ui_story_5045_50451201_9_dialog_content = "Ei, não tem como você adormecer tão rápido!",
  ui_story_5045_50451201_10_dialog_content = "Bacon e Fanny assinaram o acordo no final. Felizmente, nada fora do comum apareceu.",
  ui_story_5045_50451201_11_dialog_content = "Uhh!",
  ui_story_5045_50451201_12_dialog_content = "Meritíssimo...",
  ui_story_5045_50451201_13_dialog_content = "Fanny, o que você está fazendo aqui?",
  ui_story_5045_50451201_14_dialog_content = "<color=#737378>Hora: 14:00</color>",
  ui_story_5045_50451201_15_dialog_content = "<color=#737378>Localização: Lumo Hall of Justice, Escritório da Divisão Romance</color>",
  ui_story_5045_50451201_16_dialog_content = "Bocejar.",
  ui_story_5045_50451201_17_dialog_content = "O que está comendo você, PlayerName?",
  ui_story_5045_50451201_18_dialog_content = "Você finalmente acordou.",
  ui_story_5045_50451201_19_dialog_content = "Bacon e Fanny assinaram o acordo esta manhã.",
  ui_story_5045_50451201_20_dialog_content = "Mas Fanny entrou com um recurso logo depois.",
  ui_story_5045_50451201_21_dialog_content = "Huh? Ela não está feliz com a forma como sua propriedade foi dividida?",
  ui_story_5045_50451201_22_dialog_content = "Você poderia dizer isso, mas não é o que você pode pensar.",
  ui_story_5045_50451201_23_dialog_content = "Veja o acordo deles.",
  ui_story_5045_50451201_24_dialog_content = "\"Todas as propriedades do casal agora pertencem a Fanny, e todas as suas dívidas pertencem a Bacon\"?",
  ui_story_5045_50451201_25_dialog_content = "Fanny forçou Bacon a escrever isso?",
  ui_story_5045_50451201_26_dialog_content = "Pelo contrário, o acordo foi escrito por Bacon. Fanny não queria brigar por sua propriedade porque estava muito angustiada com toda a provação.",
  ui_story_5045_50451201_27_dialog_content = "Ela assinou o acordo sem lê-lo, então descobriu que esses eram os termos após o fato.",
  ui_story_5045_50451201_28_dialog_content = "Bacon nos mostrou claramente que se ressentia de Fanny no julgamento. Por que ele faria isso?",
  ui_story_5045_50451201_29_dialog_content = "Fanny sente que isso mostra que Bacon ainda a ama, então ela apela para a decisão.",
  ui_story_5045_50451201_30_dialog_content = "Ela nos pediu para retirar a sentença de divórcio.",
  ui_story_5045_50451201_31_dialog_content = "Meu julgamento foi... errado?",
  ui_story_5045_50451201_32_option_content = "Não seja tão rápido em se culpar.",
  ui_story_5045_50451201_33_dialog_content = "As partes envolvidas podem não ter declarado todos os fatos no tribunal.",
  ui_story_5045_50451201_34_dialog_content = "Você fez o julgamento que melhor se adequou à situação no momento.",
  ui_story_5045_50451201_35_dialog_content = "Agora, só precisamos encontrar uma maneira de extrair os fatos de tudo isso e nos preparar para o recurso!",
  ui_story_5045_50451201_36_dialog_content = "... Eu nunca pensei que você seria o único a me confortar.",
  ui_story_5045_50451201_37_dialog_content = "Mas ainda assim, obrigado, PlayerName.",
  ui_story_5045_50451201_38_dialog_content = "Afinal, sou um juiz de verdade - nunca deixaria uma coisa tão pequena como essa me abalar.",
  ui_story_5045_50451201_39_option_content = "Ainda não podemos ter certeza.",
  ui_story_5045_50451201_40_dialog_content = "O acordo de liquidação de propriedade de Bacon contradiz claramente sua declaração anterior sobre suas diferenças irreconciliáveis.",
  ui_story_5045_50451201_41_dialog_content = "Como podemos suportar o julgamento quando não sabemos o que realmente aconteceu entre eles?",
  ui_story_5045_50451201_42_dialog_content = "Você tem razão. Para julgar este caso adequadamente, é crucial descobrirmos o que realmente aconteceu.",
  ui_story_5045_50451201_43_option_content = "Então está errado",
  ui_story_5045_50451201_44_dialog_content = "Não há outra explicação para o que está acontecendo agora.",
  ui_story_5045_50451201_45_dialog_content = "Sério...?",
  ui_story_5045_50451201_46_dialog_content = "No entanto, como juízes, ainda temos que fazer nossos julgamentos com base em fatos.",
  ui_story_5045_50451201_47_dialog_content = "Mas o que aconteceu entre eles?",
  ui_story_5045_50451201_48_dialog_content = "Vamos!",
  ui_story_5045_50451201_49_dialog_content = "Huh? Para onde?",
  ui_story_5045_50451201_50_dialog_content = "Para a casa deles para investigar o que realmente aconteceu, é claro.",
  ui_story_5045_50451201_51_dialog_content = "E é melhor nos apressarmos - se não terminarmos de investigar nas próximas duas horas...",
  ui_story_5045_50451201_52_dialog_content = "Você vai ter que me carregar nas costas quando eu dormir.",
  ui_story_5045_50451201_53_dialog_content = "A-Tudo bem, vamos então!",
  ui_story_5045_50451201_54_dialog_content = "<color=#737378>Horário: 14h30</color>",
  ui_story_5045_50451201_55_dialog_content = "<color=#737378>Localização: Baixa Lumópolis</color>",
  ui_story_5045_50451201_56_dialog_content = "A casa de Bacon e Fanny fica logo adiante.",
  ui_story_5045_50451201_57_dialog_content = "Ei, quem é aquele cara parado na porta?",
  ui_story_5045_50451201_58_dialog_content = "(Por que ele parece tão familiar...?)",
  ui_story_5045_50451201_59_dialog_content = "...",
  ui_story_5045_50451201_60_dialog_content = "Olá. Você conhece Bacon e Fanny?",
  ui_story_5045_50451201_61_dialog_content = "Me desculpe, mas... quem é você?",
  ui_story_5045_50451201_62_dialog_content = "Somos do Tribunal de Justiça.",
  ui_story_5045_50451201_63_dialog_content = "PlayerName, mostre a ele essa coisa e você pode provar nosso <color=#1875ad>identidade</color>.",
  ui_story_5045_50451201_64_dialog_content = "Este?",
  ui_story_5045_50451201_65_dialog_content = "Isso não foi o que eu quis dizer.",
  ui_story_5045_50451201_66_dialog_content = "Oh, é-é? Nesse caso...",
  ui_story_5045_50451201_67_dialog_content = "Vocês são juízes? Por favor, perdoe minha grosseria agora.",
  ui_story_5045_50451201_68_dialog_content = "Sou amigo de Bacon. Os nomes <color=#1875ad>Karl</color>.",
  ui_story_5045_50451201_69_dialog_content = "Só vim aqui procurando Bacon, mas parece que só Fanny está em casa agora.",
  ui_story_5045_50451201_70_dialog_content = "(Ele não sabe que Bacon e Fanny estão se divorciando?)",
  ui_story_5045_50451201_71_dialog_content = "Então, qual é a sua opinião sobre o relacionamento de Bacon com sua esposa?",
  ui_story_5045_50451201_72_dialog_content = "... Eles fizeram algo ilegal?",
  ui_story_5045_50451201_73_dialog_content = "Eles estão indo para-",
  ui_story_5045_50451201_74_dialog_content = "...",
  ui_story_5045_50451201_75_dialog_content = "<size=32>Ahem... Não deixe que os detalhes do caso afetem a opinião da testemunha!</size>",
  ui_story_5045_50451201_76_dialog_content = "Na verdade, estamos apenas realizando algumas pesquisas sobre a felicidade da vida matrimonial em Lumopolis.",
  ui_story_5045_50451201_77_dialog_content = "Agradeceríamos se você pudesse responder algumas perguntas para nós.",
  ui_story_5045_50451201_78_dialog_content = "Bem, eles sempre foram um casal muito amoroso - um exemplo brilhante para todos que os conhecem.",
  ui_story_5045_50451201_79_dialog_content = "Você está ciente de quaisquer questões sobre as quais os dois possam ter discutido?",
  ui_story_5045_50451201_80_dialog_content = "Haha! Discutir? Mesmo que Lumopolis caísse do céu, eles não lutariam.",
  ui_story_5045_50451201_81_dialog_content = "Entendo...",
  ui_story_5045_50451201_82_dialog_content = "<color=#737378>Horário: 15h</color>",
  ui_story_5045_50451201_83_dialog_content = "<color=#737378>Localização: Lower Lumopolis, Bacon e Fanny's House</color>",
  ui_story_5045_50451201_84_dialog_content = "Olá? Tem alguém em casa?",
  ui_story_5045_50451201_85_dialog_content = "Meritíssimos, o que os traz aqui?",
  ui_story_5045_50451201_86_dialog_content = "Recebemos sua solicitação de apelação e percebemos que erros podem ter sido cometidos durante o primeiro julgamento.",
  ui_story_5045_50451201_87_dialog_content = "Então, estamos aqui para encontrar vocês dois para averiguar todos os detalhes da situação.",
  ui_story_5045_50451201_88_dialog_content = "Bacon... disse que voltaria mais tarde para fazer as malas.",
  ui_story_5045_50451201_89_dialog_content = "Mas, por favor, entre!",
  ui_story_5045_50451201_90_dialog_content = "O que é isso no chão...?",
  ui_story_5045_50451201_91_dialog_content = "Eu sinto muito. Não tive tempo de limpar as coisas...",
  ui_story_5045_50451201_92_dialog_content = "Esse <color=#1875ad>placa</color> é...",
  ui_story_5045_50451201_93_dialog_content = "Sou eu! sem querer quebrei...",
  ui_story_5045_50451201_94_dialog_content = "Mas esta placa não parece ter sido quebrada acidentalmente.",
  ui_story_5045_50451201_95_dialog_content = "Fanny, viemos aqui por um motivo - queremos descobrir a verdade.",
  ui_story_5045_50451201_96_dialog_content = "Se você ainda está escondendo algo, temo que a verdade deste caso nunca venha à tona.",
  ui_story_5045_50451201_97_dialog_content = "... Tudo bem.",
  ui_story_5045_50451201_98_dialog_content = "Bacon quebrou este prato ontem à noite.",
  ui_story_5045_50451201_99_dialog_content = "Mas eu podia sentir que ele estava deliberadamente tentando me deixar com raiva para que eu aceitasse o fato de que logo nos divorciaríamos.",
  ui_story_5045_50451201_100_dialog_content = "Eu não entendo. Se é assim que Bacon te trata... por que você ainda quer ficar com ele?",
  ui_story_5045_50451201_101_dialog_content = "Obviamente, você nunca conheceu o amor verdadeiro.",
  ui_story_5045_50451201_102_dialog_content = "Um dia, você começará sua própria família com a pessoa que ama...",
  ui_story_5045_50451201_103_dialog_content = "Quando esse dia chegar, você fará tudo ao seu alcance para manter aquela família.",
  ui_story_5045_50451201_104_dialog_content = "Mesmo que Bacon queira acabar com sua família?",
  ui_story_5045_50451201_105_dialog_content = "Meritíssimos, há algumas coisas que eu não poderia dizer no tribunal. Eu estava com medo de que Bacon fosse ridicularizado.",
  ui_story_5045_50451201_106_dialog_content = "Tenha certeza de que manteremos seu segredo seguro.",
  ui_story_5045_50451201_107_dialog_content = "Seria do interesse de todos se você apenas nos contasse o que tem a dizer.",
  ui_story_5045_50451201_108_dialog_content = "Um dia, arrastei Bacon para um passeio e nos deparamos com um evento de consulta gratuita que uma certa clínica estava realizando.",
  ui_story_5045_50451201_109_dialog_content = "Foi então que Bacon foi diagnosticado com <color=#1875ad>depressão</color>.",
  ui_story_5045_50451201_110_dialog_content = "O médico disse que era algo no coração dele que estava deixando Bacon letárgico, deprimido, insone...",
  ui_story_5045_50451201_111_dialog_content = "Foi quando descobri pela primeira vez que Bacon estava doente e não estava apenas vagando por aí.",
  ui_story_5045_50451201_112_dialog_content = "Então, depois disso, nunca mais o importunei.",
  ui_story_5045_50451201_113_dialog_content = "Eu só esperava que Bacon pudesse receber o tratamento de que precisava e melhorar gradualmente.",
  ui_story_5045_50451201_114_dialog_content = "Mas eu realmente não esperava que Bacon fosse de repente ao Tribunal de Justiça e pedisse o divórcio.",
  ui_story_5045_50451201_115_dialog_content = "Algo deve ter acontecido com ele... mas ele se recusou a me contar qualquer coisa.",
  ui_story_5045_50451201_116_dialog_content = "O que poderia ter acontecido com Bacon?",
  ui_story_5045_50451201_117_dialog_content = "Ele provavelmente não nos dirá se perguntarmos diretamente a ele. Por que não procuramos pistas em sua casa primeiro?",
  ui_story_5045_50451201_118_dialog_content = "Existe algum lugar em particular que você gostaria de investigar?",
  ui_story_5045_50451201_119_dialog_content = "Deixa eu pensar...",
  ui_story_5045_50451201_120_option_content = "Verifique as paredes",
  ui_story_5045_50451201_121_dialog_content = "Posso dar uma olhada nisso <color=#1875ad>foto</color> pendurado na parede?",
  ui_story_5045_50451201_122_dialog_content = "Claro, vou retirá-lo para você.",
  ui_story_5045_50451201_123_dialog_content = "É uma foto de Fanny e Bacon.",
  ui_story_5045_50451201_124_dialog_content = "Sim, mas isso foi há sete anos.",
  ui_story_5045_50451201_125_dialog_content = "Naquela época, tínhamos acabado de nos casar e não tínhamos nada.",
  ui_story_5045_50451201_126_dialog_content = "Não sei como, mas Bacon de alguma forma convenceu um fotógrafo a tirar essa foto para nós de graça...",
  ui_story_5045_50451201_127_dialog_content = "Pensando bem, essa foi a primeira e única foto que tiramos juntos.",
  ui_story_5045_50451201_128_dialog_content = "É o <color=#1875ad>endereço</color> escrito atrás de onde você tirou?",
  ui_story_5045_50451201_129_dialog_content = "Hum, isso é estranho. Não me lembro de ter escrito nada no verso...",
  ui_story_5045_50451201_130_dialog_content = "Mas esta é a caligrafia de Bacon.",
  ui_story_5045_50451201_131_dialog_content = "Parece um tanto suspeito, não é? Vamos anotar.",
  ui_story_5045_50451201_132_dialog_content = "Além disso...",
  ui_story_5045_50451201_133_option_content = "verifique a tabela",
  ui_story_5045_50451201_134_dialog_content = "Huh? O que é isso <color=#1875ad>cartão</color>?",
  ui_story_5045_50451201_135_dialog_content = "... Isso é do <color=#1875ad>curso de autoajuda</color>. É um <color=#1875ad>cartão de presença</color>.",
  ui_story_5045_50451201_136_dialog_content = "Nosso amigo Karl me disse que este curso era particularmente bom.",
  ui_story_5045_50451201_137_dialog_content = "Eles ajudam as pessoas a desenvolver sua força de vontade para que não tenham mais medo de enfrentar as dificuldades da vida.",
  ui_story_5045_50451201_138_dialog_content = "Ele disse que muitas das pessoas que fizeram esse curso tiveram uma vida melhor.",
  ui_story_5045_50451201_139_dialog_content = "Eles realmente oferecem cursos como este em Lumopolis?",
  ui_story_5045_50451201_140_dialog_content = "Eu mesmo não fiz nenhum curso como este, mas sei que são muito caros.",
  ui_story_5045_50451201_141_dialog_content = "... Eu queria que Bacon conseguisse ajuda, então peguei dinheiro emprestado para contratá-lo.",
  ui_story_5045_50451201_142_dialog_content = "Mas Bacon disse que não iria... No entanto, não há reembolso para o curso de autoajuda.",
  ui_story_5045_50451201_143_dialog_content = "Então, espero que Bacon possa voltar, mesmo que só para tentar uma vez...",
  ui_story_5045_50451201_144_dialog_content = "Então Fanny pediu dinheiro emprestado para Bacon...",
  ui_story_5045_50451201_145_dialog_content = "Além disso...",
  ui_story_5045_50451201_146_option_content = "Embrulhe isso",
  ui_story_5045_50451201_147_dialog_content = "De fato. Não parece haver mais pistas valiosas aqui.",
  ui_story_5045_50451201_148_dialog_content = "Mas isso <color=#1875ad>garrafa</color> parece bastante intrigante.",
  ui_story_5045_50451201_149_dialog_content = "<color=#737378>Farfalhar—</color>",
  ui_story_5045_50451201_150_dialog_content = "Que tipo de tempero você guarda nesta garrafa?",
  ui_story_5045_50451201_151_dialog_content = "Ah, isso é de Bacon <color=#1875ad>Frasco de remédios</color>!",
  ui_story_5045_50451201_152_dialog_content = "Desde então, Bacon recebe tratamento de um médico de clínica gratuita e precisa tomar remédios todos os dias.",
  ui_story_5045_50451201_153_dialog_content = "Não sei se ele tomou o remédio hoje.",
  ui_story_5045_50451201_154_dialog_content = "Erm, Bacon realmente não se importa em fazer as pessoas se preocuparem com ele.",
  ui_story_5045_50451201_155_dialog_content = "<color=#737378>Hora: 16:00</color>",
  ui_story_5045_50451201_156_dialog_content = "<color=#737378>Localização: Lower Lumopolis, Fora da Clínica Gratuita</color>",
  ui_story_5045_50451201_157_dialog_content = "Então, fomos à casa de Bacon para investigar, mas agora me sinto ainda mais confuso do que nunca.",
  ui_story_5045_50451201_158_dialog_content = "Espero que possamos encontrar algumas informações úteis aqui.",
  ui_story_5045_50451201_159_dialog_content = "Ei, PlayerName e juiz Tina!",
  ui_story_5045_50451201_160_dialog_content = "Raphael, o que você está fazendo aqui?",
  ui_story_5045_50451201_161_dialog_content = "Eu poderia te perguntar a mesma coisa... É aqui que eu trabalho!",
  ui_story_5045_50451201_162_dialog_content = "Acreditamos que uma parte do nosso caso pode ser um paciente aqui, então viemos aqui para investigar a situação.",
  ui_story_5045_50451201_163_dialog_content = "Alimentos de café da manhã à parte, o nome Bacon significa alguma coisa para você?",
  ui_story_5045_50451201_164_dialog_content = "Bacon? Ele é meu <color=#1875ad>paciente</color>!",
  ui_story_5045_50451201_165_dialog_content = "Realmente? Que coincidência...",
  ui_story_5045_50451201_166_dialog_content = "Com certeza é. Bacon é um paciente que atendi durante um evento gratuito de divulgação clínica.",
  ui_story_5045_50451201_167_dialog_content = "Sua condição não mostrou sinais de melhora. É realmente muito desconcertante.",
  ui_story_5045_50451201_168_dialog_content = "Mas ele não vem para uma visita há tanto tempo, agora. Estou preocupado...",
  ui_story_5045_50451201_169_dialog_content = "Espere! Você disse que Bacon é seu cliente? O que aconteceu com ele? Ele não está na cadeia, está!?",
  ui_story_5045_50451201_170_dialog_content = "Não se preocupe, não é nada tão grave.",
  ui_story_5045_50451201_171_dialog_content = "Realmente? Então você deve lembrá-lo de vir a mim o mais rápido possível para uma consulta mais aprofundada e para pegar seu remédio.",
  ui_story_5045_50451201_172_dialog_content = "Ele já deve ter terminado o remédio que dei a ele da última vez.",
  ui_story_5045_50451201_173_dialog_content = "Huh? Mas encontramos um frasco de remédio na casa dele, e estava cheio de comprimidos...",
  ui_story_5045_50451201_174_dialog_content = "Parou!",
  ui_story_5045_50451201_175_dialog_content = "O remédio que dei a Bacon só é administrado em pequenas doses. Ele deveria voltar para mim depois de terminar tudo.",
  ui_story_5045_50451201_176_dialog_content = "Fanny poderia ter cometido um erro?",
  ui_story_5045_50451201_177_dialog_content = "<color=#737378>Horário: 17:00</color>",
  ui_story_5045_50451201_178_dialog_content = "<color=#737378>Localização: Lower Lumopolis, Bacon e Fanny's House</color>",
  ui_story_5045_50451201_179_dialog_content = "<size=45>Céus!</size>",
  ui_story_5045_50451201_180_dialog_content = "Shh! Se Fanny vir o médico de Bacon aqui, ela ficará preocupada.",
  ui_story_5045_50451201_181_dialog_content = "O que você achou, Raphael?",
  ui_story_5045_50451201_182_dialog_content = "Estas são as pílulas para dormir que dei a Bacon há algum tempo.",
  ui_story_5045_50451201_183_dialog_content = "Por que ele não pegou nenhum deles?",
  ui_story_5045_50451201_184_dialog_content = "Você quer dizer que Bacon tem acumulado essas pílulas deliberadamente?",
  ui_story_5045_50451201_185_dialog_content = "Eu realmente não entendo o que Bacon poderia estar pensando...",
  ui_story_5045_50451201_186_dialog_content = "Raphael, supostamente, apenas suponha por um segundo...",
  ui_story_5045_50451201_187_dialog_content = "Suponha que alguém engolisse todas essas pílulas de uma vez... O que aconteceria com elas?",
  ui_story_5045_50451201_188_dialog_content = "<size=45>Uau!</size>",
  ui_story_5045_50451201_189_dialog_content = "Você ainda tem muito o que viver!",
  ui_story_5045_50451201_190_dialog_content = "PlayerName, Estou tendo um mau pressentimento sobre tudo isso...",
  ui_story_5045_50451201_191_dialog_content = "Eu também sou.",
  ui_story_5045_50451201_192_dialog_content = "Parece que devemos começar o julgamento mais cedo ou mais tarde.",
  ui_story_5045_50451201_193_dialog_content = "Mas antes disso, devo pedir uma coisa de você, PlayerName.",
  ui_story_5045_50451201_194_dialog_content = "Vá em frente, diga!",
  ui_story_5045_50451201_195_dialog_content = "Eu... vou... dormir... me carregue de volta...",
  ui_story_5045_50451201_196_dialog_content = "Zzz...",
  ui_story_5045_50451201_197_dialog_content = "...",
  ui_story_5045_50451301_1_dialog_content = "<color=#737378>Hora: 9:00 AM</color>",
  ui_story_5045_50451301_2_dialog_content = "<color=#737378>Local: Lumo Hall of Justice, Tribunal</color>",
  ui_story_5045_50451301_3_dialog_content = "Hum? Parece que não temos público hoje...",
  ui_story_5045_50451301_4_dialog_content = "Depois de pensar muito sobre isso, acredito que a audiência presente pode ter um efeito sobre as partes envolvidas neste caso.",
  ui_story_5045_50451301_5_dialog_content = "Portanto, o caso de hoje não será aberto ao público.",
  ui_story_5045_50451301_6_dialog_content = "Huh? Quando você começou a pensar nisso?",
  ui_story_5045_50451301_7_dialog_content = "Talvez tenha sido ontem à noite quando você voltou comigo dormindo de costas.",
  ui_story_5045_50451301_8_dialog_content = "Quer dizer, você...",
  ui_story_5045_50451301_9_option_content = "Você ainda estava trabalhando enquanto dormia!?",
  ui_story_5045_50451301_10_dialog_content = "Sim, eu sonho muito.",
  ui_story_5045_50451301_11_dialog_content = "Às vezes, posso até pensar em soluções em meus sonhos para problemas com os quais nunca poderia lidar em minha vida desperta.",
  ui_story_5045_50451301_12_dialog_content = "Comparado com a sua vida de vigília, seus sonhos parecem exaustivos...",
  ui_story_5045_50451301_13_dialog_content = "Heehee, eu sabia que você entenderia, PlayerName.",
  ui_story_5045_50451301_14_dialog_content = "Leyn nunca foi tão legal comigo quanto você.",
  ui_story_5045_50451301_15_dialog_content = "M-Mesmo...?",
  ui_story_5045_50451301_16_option_content = "Você é bastante confiável.",
  ui_story_5045_50451301_17_dialog_content = "Uh-huh, naturalmente.",
  ui_story_5045_50451301_18_dialog_content = "Confiabilidade é o requisito mínimo nesta profissão.",
  ui_story_5045_50451301_19_dialog_content = "Espere! Então, em sua mente, você sempre me viu como não confiável?",
  ui_story_5045_50451301_20_dialog_content = "Eu...",
  ui_story_5045_50451301_21_option_content = "Você estava fingindo estar dormindo?",
  ui_story_5045_50451301_22_dialog_content = "Hmm .. Parece que você ainda está muito atrás Leyn quando se trata de ser atencioso com seu parceiro, PlayerName.",
  ui_story_5045_50451301_23_dialog_content = "(Estou imaginando coisas, ou é Tina de repente olhando para mim com um ar de nojo?)",
  ui_story_5045_50451301_24_dialog_content = "(Parece que minha resposta abalou a confiança entre nós...)",
  ui_story_5045_50451301_25_dialog_content = "Mas não importa, precisamos começar o julgamento logo.",
  ui_story_5045_50451301_26_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451301_27_dialog_content = "<size=45>Noite Branca no alto. Tribunal está agora em sessão!</size>",
  ui_story_5045_50451301_28_dialog_content = "Em primeiro lugar, invoco a apelante Fanny para fazer seu depoimento.",
  ui_story_5045_50451301_29_dialog_content = "Obrigado, Excelência. Não posso aceitar a sentença de divórcio do primeiro julgamento.",
  ui_story_5045_50451301_30_dialog_content = "Não concordo que meu relacionamento com Bacon tenha acabado, por isso não quero o divórcio.",
  ui_story_5045_50451301_31_dialog_content = "Fanny, pare com isso...",
  ui_story_5045_50451301_32_dialog_content = "Apenas deixe-me ir, por favor.",
  ui_story_5045_50451301_33_dialog_content = "Bacon, você ainda insiste que seu relacionamento acabou, certo?",
  ui_story_5045_50451301_34_dialog_content = "Correto, Excelência.",
  ui_story_5045_50451301_35_dialog_content = "Mas...",
  ui_story_5045_50451301_36_dialog_content = "Suas ações provam que você foi <color=#1875ad>protegendo os melhores interesses de Fanny</color> durante todo esse tempo!",
  ui_story_5045_50451301_37_dialog_content = "PlayerName, o que te faz dizer isso de repente?",
  ui_story_5045_50451301_38_dialog_content = "M-Meu erro!",
  ui_story_5045_50451301_39_dialog_content = "O que eu realmente queria dizer era...",
  ui_story_5045_50451301_40_dialog_content = "Tina, dê uma olhada neste!",
  ui_story_5045_50451301_41_dialog_content = "Hmm, seus registros são realmente muito detalhados.",
  ui_story_5045_50451301_42_dialog_content = "Mas por que essa cena parece tão familiar? Eu não vi tudo isso em um sonho?",
  ui_story_5045_50451301_43_dialog_content = "Não tive pesadelos recentemente... então, o teste de hoje deve ser um sucesso!",
  ui_story_5045_50451301_44_dialog_content = "Então, novamente, você tirou isso de repente só para que eu satisfizesse seu ego?",
  ui_story_5045_50451301_45_dialog_content = "Não é isso. O que eu realmente queria dizer era...",
  ui_story_5045_50451301_46_dialog_content = "Você está deixando todas as suas propriedades para Fanny e assumindo todas as suas dívidas você mesmo! O que mais eu preciso dizer?",
  ui_story_5045_50451301_47_dialog_content = "I-Isto não tem nada a ver com o fim do nosso casamento.",
  ui_story_5045_50451301_48_dialog_content = "Estou entregando todas as nossas propriedades para Fanny como compensação por seu trabalho árduo em casa nos últimos sete anos.",
  ui_story_5045_50451301_49_dialog_content = "Eu simplesmente desejo trocar tudo isso pela minha liberdade... isso é tudo.",
  ui_story_5045_50451301_50_dialog_content = "Só isso?",
  ui_story_5045_50451301_51_dialog_content = "Você realmente não me ama mais, não é...?",
  ui_story_5045_50451301_52_dialog_content = "Isso mesmo, agora, por favor, pare de me importunar.",
  ui_story_5045_50451301_53_dialog_content = "Boo-hoo... Por quê? Por que você está fazendo isto comigo!?",
  ui_story_5045_50451301_54_dialog_content = "Fanny, ainda temos que trazer este caso a um grau satisfatório de clareza. Não se preocupe com isso ainda.",
  ui_story_5045_50451301_55_dialog_content = "Meritíssimo, se é assim que Bacon se sente, não quero mais incomodá-lo.",
  ui_story_5045_50451301_56_dialog_content = "Vale a pena prolongar ainda mais este julgamento?",
  ui_story_5045_50451301_57_dialog_content = "Sim! Claro que há!",
  ui_story_5045_50451301_58_dialog_content = "Hum? Por que de repente você parece tão animado, PlayerName?",
  ui_story_5045_50451301_59_dialog_content = "Eu acredito que as duas partes ainda se amam...",
  ui_story_5045_50451301_60_dialog_content = "Bem, o que você planeja fazer a seguir?",
  ui_story_5045_50451301_61_dialog_content = "eu... eu não sei...",
  ui_story_5045_50451301_62_dialog_content = "Haha, apenas assista e aprenda então.",
  ui_story_5045_50451301_63_dialog_content = "Ahem, encontramos algumas coisas peculiares durante nossa investigação.",
  ui_story_5045_50451301_64_dialog_content = "Se você não consegue explicá-los claramente, pode estar enfrentando mais do que apenas um julgamento na Divisão de Romance.",
  ui_story_5045_50451301_65_dialog_content = "Uma das coisas estranhas mencionadas é <color=#1875ad>a coisa Raphael verifiquei ontem</color>. Ela deve significar...",
  ui_story_5045_50451301_66_dialog_content = "Não é isso. Pense de novo, PlayerName.",
  ui_story_5045_50451301_67_dialog_content = "Sim!",
  ui_story_5045_50451301_68_dialog_content = "Bacon, você reconhece isso?",
  ui_story_5045_50451301_69_dialog_content = "Bom...",
  ui_story_5045_50451301_70_dialog_content = "Você pode nos dizer que tipo de remédio está neste frasco?",
  ui_story_5045_50451301_71_dialog_content = "Este é o remédio para dormir que meu médico me receitou.",
  ui_story_5045_50451301_72_dialog_content = "Conhecemos o seu médico de clínica gratuita Raphael ontem.",
  ui_story_5045_50451301_73_dialog_content = "Segundo ela, ela só lhe dá uma pequena dose de pílulas para dormir cada vez que você a vê.",
  ui_story_5045_50451301_74_dialog_content = "Parece que você tem estocado secretamente as pílulas sem avisar o seu médico.",
  ui_story_5045_50451301_75_dialog_content = "Com uma dosagem tão grande de pílulas para dormir à sua disposição... será que você planeja envenenar sua esposa?",
  ui_story_5045_50451301_76_dialog_content = "<size=45>O que!?</size>",
  ui_story_5045_50451301_77_dialog_content = "Fanny, não, não é isso! Eu não queria envenenar ninguém...",
  ui_story_5045_50451301_78_dialog_content = "Então por que você guardou deliberadamente essas pílulas para dormir?",
  ui_story_5045_50451301_79_dialog_content = "...",
  ui_story_5045_50451301_80_dialog_content = "Não tem nada a ver com o divórcio.",
  ui_story_5045_50451301_81_dialog_content = "Bacon, você realmente mudou. Eu não sei mais quem você é...",
  ui_story_5045_50451301_82_dialog_content = "Fanny...",
  ui_story_5045_50451301_83_dialog_content = "Tina, o que devemos fazer agora?",
  ui_story_5045_50451301_84_dialog_content = "Se Bacon não derramar o feijão, não há nada que possamos fazer.",
  ui_story_5045_50451301_85_dialog_content = "Você consegue pensar em algum ponto questionável que ainda não esclarecemos?",
  ui_story_5045_50451301_86_dialog_content = "Todo o caso é um grande ponto questionável!",
  ui_story_5045_50451301_87_dialog_content = "Hum, pensando bem...",
  ui_story_5045_50451301_88_dialog_content = "O <color=#1875ad>endereço</color>!",
  ui_story_5045_50451301_89_dialog_content = "Qual endereço?",
  ui_story_5045_50451301_90_dialog_content = "Não... Certo, é isso!",
  ui_story_5045_50451301_91_dialog_content = "Há um endereço no verso desta foto que ainda não investigamos completamente.",
  ui_story_5045_50451301_92_dialog_content = "Oh! Isso mesmo, você acabou de me lembrar. Convidei uma testemunha!",
  ui_story_5045_50451301_93_dialog_content = "Quando você convidou uma testemunha? Foi também durante o seu sonho?",
  ui_story_5045_50451301_94_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451301_95_dialog_content = "Agora, eu gostaria de pedir testemunha <color=#1875ad>Michenny</color> para tomar posição.",
  ui_story_5045_50451301_96_dialog_content = "Bom Dia a todos. Eu sou o cobrador de impostos, Michenny.",
  ui_story_5045_50451301_97_dialog_content = "Você reconhece o endereço escrito à mão no verso desta foto?",
  ui_story_5045_50451301_98_dialog_content = "Este é um novo tipo de organização que fornece <color=#1875ad>serviços de seguros</color>.",
  ui_story_5045_50451301_99_dialog_content = "Bacon, o autor neste caso, comprou <color=#1875ad>seguro de vida</color> para si mesmo desta agência de seguros.",
  ui_story_5045_50451301_100_dialog_content = "Se Bacon for vítima de morte ou lesão acidental, um <color=#1875ad>reivindicação enorme</color> pode ser feito à agência de seguros.",
  ui_story_5045_50451301_101_dialog_content = "Se isso acontecer, quem receberá o pagamento?",
  ui_story_5045_50451301_102_dialog_content = "Segundo a agência, essas informações são sigilosas.",
  ui_story_5045_50451301_103_dialog_content = "Mas se essa informação for vital para o caso, a lei determina que temos direito a ela.",
  ui_story_5045_50451301_104_dialog_content = "Muito bem... Muito obrigado!",
  ui_story_5045_50451301_105_dialog_content = "Bem, vou me despedir então.",
  ui_story_5045_50451301_106_dialog_content = "Meritíssimo, o que quer dizer com isso?",
  ui_story_5045_50451301_107_dialog_content = "Será mesmo que... Bacon preparou todas essas pílulas para si mesmo?",
  ui_story_5045_50451301_108_dialog_content = "Ele planejava deixar um enorme pagamento de seguro para alguém?",
  ui_story_5045_50451301_109_dialog_content = "Bacon, você percebe que esse tipo de comportamento pode levá-lo à prisão?",
  ui_story_5045_50451301_110_dialog_content = "Eles dizem que ser enviado para a prisão de Lumopolis é um destino pior que a morte.",
  ui_story_5045_50451301_111_dialog_content = "...",
  ui_story_5045_50451301_112_dialog_content = "Eu...",
  ui_story_5045_50451301_113_dialog_content = "Não se preocupe. Se você confessar agora, vamos lidar com você com indulgência.",
  ui_story_5045_50451301_114_dialog_content = "Bacon, o que você estava planejando?",
  ui_story_5045_50451301_115_dialog_content = "Diga ao juiz rapidamente. Esta é a última coisa que pedirei a você como sua esposa.",
  ui_story_5045_50451301_116_dialog_content = "Fanny, me desculpe.",
  ui_story_5045_50451301_117_dialog_content = "Eu planejei por tanto tempo, me enganei e até enganei você, mas no final... ainda falhei.",
  ui_story_5045_50451301_118_dialog_content = "O que é que você fez...?",
  ui_story_5045_50451301_119_dialog_content = "Meritíssimo, eu era um jardineiro, trabalhando para uma família nobre.",
  ui_story_5045_50451301_120_dialog_content = "Foi porque quebrei acidentalmente o amado prato de porcelana do mestre que fui demitido.",
  ui_story_5045_50451301_121_dialog_content = "Por causa disso, tornei-me motivo de chacota entre os empregados, e ninguém pensava em me contratar...",
  ui_story_5045_50451301_122_dialog_content = "Me escondi em casa, cada vez com mais medo de sair de casa e sem esperança no futuro.",
  ui_story_5045_50451301_123_dialog_content = "Depois disso, à medida que nossas dívidas aumentavam, Fanny começou a trabalhar cada vez mais.",
  ui_story_5045_50451301_124_dialog_content = "Deveria ser eu a proteger Fanny, proteger nossa casa, mas não pude fazer nada...",
  ui_story_5045_50451301_125_dialog_content = "Foi quando me deparei com aquela nova agência de seguros.",
  ui_story_5045_50451301_126_dialog_content = "Eu estava pensando que em vez de ser um fardo para Fanny, seria melhor se...",
  ui_story_5045_50451301_127_dialog_content = "Seu idiota! Nunca pensei em você como um fardo! Nunca!",
  ui_story_5045_50451301_128_dialog_content = "É tudo porque eu era muito ganancioso.",
  ui_story_5045_50451301_129_dialog_content = "Achei que se me divorciasse de Fanny, poderia assumir todas as nossas dívidas.",
  ui_story_5045_50451301_130_dialog_content = "Então, depois da minha morte, a dívida também seria cancelada.",
  ui_story_5045_50451301_131_dialog_content = "No final, descobri que sou inútil demais para fazer isso.",
  ui_story_5045_50451301_132_dialog_content = "Bacon, deixe-me dizer-lhe uma coisa.",
  ui_story_5045_50451301_133_dialog_content = "Se você acabasse com sua própria vida, a companhia de seguros negaria o pedido.",
  ui_story_5045_50451301_134_dialog_content = "R-Sério!?",
  ui_story_5045_50451301_135_dialog_content = "Se você fizesse uma coisa dessas, só deixaria Fanny com uma tonelada de dívidas e uma tristeza sem fim.",
  ui_story_5045_50451301_136_dialog_content = "Céus, o que eu fiz?",
  ui_story_5045_50451301_137_dialog_content = "Fanny, me desculpe! Desculpe...",
  ui_story_5045_50451301_138_dialog_content = "No final, ainda falhei em lhe dar uma vida feliz.",
  ui_story_5045_50451301_139_dialog_content = "Bacon, do que você está falando?",
  ui_story_5045_50451301_140_dialog_content = "Sempre fui feliz com você.",
  ui_story_5045_50451301_141_dialog_content = "...",
  ui_story_5045_50451301_142_dialog_content = "Lembra do prato de barro que nós mesmos fizemos?",
  ui_story_5045_50451301_143_dialog_content = "eu lembro disso <color=#1875ad>prato de barro</color>!",
  ui_story_5045_50451301_144_dialog_content = "PlayerName, não torne isso mais bagunçado do que já é.",
  ui_story_5045_50451301_145_dialog_content = "Desculpa, mas eu acho...",
  ui_story_5045_50451301_146_dialog_content = "Essa é a placa quebrada?",
  ui_story_5045_50451301_147_dialog_content = "Eu me lembro, era de quando nos casamos...",
  ui_story_5045_50451301_148_dialog_content = "Uh, Bacon está prestes a relembrar a alegria de todo o período de lua de mel deles aqui no tribunal?",
  ui_story_5045_50451301_149_dialog_content = "Rápido!",
  ui_story_5045_50451301_150_dialog_content = "Sinto muito...",
  ui_story_5045_50451301_151_dialog_content = "Fanny, pelo que você está se desculpando?",
  ui_story_5045_50451301_152_dialog_content = "Eu queria te surpreender com o jantar, mas sem querer quebrei nossos pratos...",
  ui_story_5045_50451301_153_dialog_content = "Hahaha! Por que você se desculpou por isso?",
  ui_story_5045_50451301_154_dialog_content = "Nem me lembro há quanto tempo essas placas foram usadas. Já é hora de substituí-los.",
  ui_story_5045_50451301_155_dialog_content = "Mas... não temos dinheiro agora.",
  ui_story_5045_50451301_156_dialog_content = "Podemos fazer alguns nós mesmos.",
  ui_story_5045_50451301_157_dialog_content = "Nós mesmos? Como?",
  ui_story_5045_50451301_158_dialog_content = "Me siga!",
  ui_story_5045_50451301_159_dialog_content = "Hahaha, pensei que Bacon tinha encontrado um lojista que poderia nos ajudar com alguns pratos.",
  ui_story_5045_50451301_160_dialog_content = "Inesperadamente, ele me levou para o deserto.",
  ui_story_5045_50451301_161_dialog_content = "Apontando para o barro do rio, ele disse que faria alguma mágica para mim.",
  ui_story_5045_50451301_162_dialog_content = "Podemos moldar esta argila em qualquer forma que quisermos, depois assá-la no fogo...",
  ui_story_5045_50451301_163_dialog_content = "... e teremos nossos próprios pratos.",
  ui_story_5045_50451301_164_dialog_content = "Uau, meu marido é incrível!",
  ui_story_5045_50451301_165_dialog_content = "Heh, embora este prato seja um pouco feio.",
  ui_story_5045_50451301_166_dialog_content = "O meu parece pior.",
  ui_story_5045_50451301_167_dialog_content = "Mas estes são nossos pratos de argila exclusivos! Não importa o quanto esses nobres os desejem, eles não podem tê-los!",
  ui_story_5045_50451301_168_dialog_content = "Naquela época, não tínhamos nada, mas éramos muito felizes.",
  ui_story_5045_50451301_169_dialog_content = "Agora temos casa própria, embora estejamos endividados...",
  ui_story_5045_50451301_170_dialog_content = "Mas ainda podemos ser saudáveis e felizes juntos, algo que nenhuma quantidade de Nightium pode comprar!",
  ui_story_5045_50451301_171_dialog_content = "Fanny...",
  ui_story_5045_50451301_172_dialog_content = "Tudo vai ficar bem.",
  ui_story_5045_50451301_173_dialog_content = "Esta é a verdade que você me ensinou e me fez acreditar por meio de suas ações.",
  ui_story_5045_50451301_174_dialog_content = "Você vai acreditar em mim desta vez, Bacon?",
  ui_story_5045_50451301_175_dialog_content = "... Sim.",
  ui_story_5045_50451301_176_dialog_content = "Parece que este caso já chegou à sua conclusão.",
  ui_story_5045_50451301_177_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451301_178_dialog_content = "Noite Branca no alto. É hora do veredicto!",
  ui_story_5045_50451301_179_dialog_content = "Em primeiro lugar, Bacon e Fanny, ao longo deste julgamento, provaram o amor que existe entre eles.",
  ui_story_5045_50451301_180_dialog_content = "Em segundo lugar, embora Bacon pretendesse cometer fraude de seguros, ele receberá uma punição mais leve, pois não executou seu plano e mostrou a sinceridade de seu arrependimento.",
  ui_story_5045_50451301_181_dialog_content = "Portanto, chegamos ao seguinte julgamento!",
  ui_story_5045_50451301_182_dialog_content = "O estado civil de Bacon e Fanny continuará inalterado.",
  ui_story_5045_50451301_183_dialog_content = "O remédio acumulado de Bacon será confiscado. Ele será levado a um médico regularmente e tomará seus remédios nos dias seguintes a essas visitas.",
  ui_story_5045_50451301_184_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451301_185_dialog_content = "O julgamento acabou!",
  ui_story_5045_50451401_1_dialog_content = "<color=#737378>Hora: 14:00</color>",
  ui_story_5045_50451401_2_dialog_content = "<color=#737378>Localização: Lumo Hall of Justice, Escritório da Divisão Romance</color>",
  ui_story_5045_50451401_3_dialog_content = "Bocejar-",
  ui_story_5045_50451401_4_dialog_content = "Você está acordado?",
  ui_story_5045_50451401_5_dialog_content = "Selecionei alguns resumos de casos. Tina, vamos ver qual caso devemos examinar primeiro.",
  ui_story_5045_50451401_6_dialog_content = "Nada mal, PlayerName.",
  ui_story_5045_50451401_7_dialog_content = "Você é muito proativo em seu trabalho. Talvez você devesse ficar e ser meu assistente no futuro.",
  ui_story_5045_50451401_8_dialog_content = "Hã...",
  ui_story_5045_50451401_9_dialog_content = "Meritíssimo.",
  ui_story_5045_50451401_10_dialog_content = "Eh!?",
  ui_story_5045_50451401_11_dialog_content = "Bacon? E Fanny também? O que você está fazendo aqui?",
  ui_story_5045_50451401_12_dialog_content = "Surgiu outro problema?",
  ui_story_5045_50451401_13_dialog_content = "Nada disso, Meritíssimo. Estamos aqui para agradecer a vocês dois.",
  ui_story_5045_50451401_14_dialog_content = "Após o julgamento, foi como se eu tivesse acabado de acordar de um sonho...",
  ui_story_5045_50451401_15_dialog_content = "Percebi que quase cometi um grande erro e também causei muitos problemas a vocês dois.",
  ui_story_5045_50451401_16_dialog_content = "De nada. Foi uma honra ajudá-lo.",
  ui_story_5045_50451401_17_dialog_content = "E eu não sinto que você nos trouxe nenhum problema!",
  ui_story_5045_50451401_18_dialog_content = "(Porque eu fiz todo o trabalho duro...)",
  ui_story_5045_50451401_19_dialog_content = "PlayerName, você tem algo que deseja dizer a Bacon?",
  ui_story_5045_50451401_20_dialog_content = "Ah, certo, eu queria <color=#1875ad>dizer</color> você alguma coisa...",
  ui_story_5045_50451401_21_dialog_content = "O caso acabou. Por que você ainda está perguntando sobre isso?",
  ui_story_5045_50451401_22_dialog_content = "Raphael tem se preocupado com você.",
  ui_story_5045_50451401_23_dialog_content = "Embora Raphael parece uma criança, e suas técnicas de tratamento podem parecer um pouco grosseiras...",
  ui_story_5045_50451401_24_dialog_content = "Mas suas habilidades médicas são excelentes!",
  ui_story_5045_50451401_25_dialog_content = "Eu entendo... Vou pedir desculpas ao Dr. Raphael também.",
  ui_story_5045_50451401_26_dialog_content = "Se ela estiver disposta a me dar outra chance, aceitarei o tratamento dela.",
  ui_story_5045_50451401_27_dialog_content = "Bacon, Fanny, quais são seus planos para o futuro?",
  ui_story_5045_50451401_28_dialog_content = "Não tenho certeza, mas vamos tentar fazer um trabalho de meio período juntos primeiro e pagar nossas dívidas aos poucos.",
  ui_story_5045_50451401_29_dialog_content = "Além disso, indo para o <color=#1875ad>curso de autoajuda</color> pode me ajudar a encontrar uma nova direção na vida.",
  ui_story_5045_50451401_30_dialog_content = "Isso soa muito encorajador!",
  ui_story_5045_50451401_31_dialog_content = "Mas o que há com toda essa bagagem? Você está mudando de casa?",
  ui_story_5045_50451401_32_dialog_content = "Estas são as nossas ferramentas de cerâmica.",
  ui_story_5045_50451401_33_dialog_content = "Estamos indo para o campo mais tarde para fazer alguns pratos novos.",
  ui_story_5045_50451401_34_dialog_content = "Uau! Revivendo os bons velhos tempos?",
  ui_story_5045_50451401_35_dialog_content = "Ahem... Você poderia dizer isso.",
  ui_story_5045_50451401_36_dialog_content = "Eu sou o culpado por quebrar nossa lembrança mais preciosa.",
  ui_story_5045_50451401_37_dialog_content = "É justo que eu compense isso.",
  ui_story_5045_50451401_38_dialog_content = "Isso é tão querido!",
  ui_story_5045_50451401_39_option_content = "Isso é uma pitada de inveja que eu detecto, Tina?",
  ui_story_5045_50451401_40_dialog_content = "Hmm... Há algo de estranho em admirar a beleza do amor?",
  ui_story_5045_50451401_41_dialog_content = "Se Vossas Excelências não se importarem, faremos mais pratos pequenos para vocês dois!",
  ui_story_5045_50451401_42_dialog_content = "Adoraríamos, mas como jurados, não podemos aceitar presentes de nossos clientes.",
  ui_story_5045_50451401_43_dialog_content = "As placas de barro que fazemos são de muito pouco valor...",
  ui_story_5045_50451401_44_dialog_content = "Agradecemos sua gentileza, mas, na minha opinião, seus pratos não têm preço.",
  ui_story_5045_50451401_45_dialog_content = "Obrigado, meritíssimo... Bem, já tomamos bastante do seu tempo.",
  ui_story_5045_50451401_46_dialog_content = "Suspiro, eu realmente espero que um dia, minha namorada me leve para fazer algo tão romântico quanto.",
  ui_story_5045_50451401_47_dialog_content = "Mas ainda é tempo de trabalho, PlayerName, volte ao seu trabalho...",
  ui_story_5045_50451401_47X1_dialog_content = "Como parceiros, há espaço para nossos <color=#1875ad>Rapport</color> melhorar!",
  ui_story_5045_50451401_48_dialog_content = "E você?",
  ui_story_5045_50451401_49_dialog_content = "Preciso dormir um pouco, é claro. Pode haver alguns bons sonhos esperando por mim se eu adormecer com o coração feliz!",
  ui_story_5045_50451401_50_dialog_content = "O que-?!",
  ui_story_5045_50451401_51_option_content = "Vamos juntos!",
  ui_story_5045_50451401_52_dialog_content = "Hã?",
  ui_story_5045_50451401_53_dialog_content = "Ah, desculpe... esqueci que ainda é hora do trabalho.",
  ui_story_5045_50451401_54_dialog_content = "Então vamos em frente!",
  ui_story_5045_50451401_55_dialog_content = "Tudo bem, eu só—",
  ui_story_5045_50451401_56_dialog_content = "Huh? Ela se foi?",
  ui_story_5045_50451401_57_dialog_content = "<color=#737378>Horário: 21:00</color>",
  ui_story_5045_50451401_58_dialog_content = "<color=#737378>Localização: Arredores de Lumópolis</color>",
  ui_story_5045_50451401_59_dialog_content = "Assim que estiver tudo pronto, você pode colocá-lo no fogo para assá-lo.",
  ui_story_5045_50451401_60_dialog_content = "Tina, o que você está fazendo?",
  ui_story_5045_50451401_61_dialog_content = "Espere um segundo, eu vou te mostrar em breve.",
  ui_story_5045_50451401_62_dialog_content = "Não se preocupe, o meu está horrível. Eu prometo que não vou rir da sua.",
  ui_story_5045_50451401_63_dialog_content = "Estou muito satisfeito com minha obra-prima, só não a terminei ainda—",
  ui_story_5045_50451401_64_dialog_content = "Hehe... Hahaha!",
  ui_story_5045_50451401_65_dialog_content = "O que é isso?",
  ui_story_5045_50451401_66_dialog_content = "PlayerName, seu prato está realmente horrível e seu rosto está coberto de barro.",
  ui_story_5045_50451401_67_dialog_content = "Você estava tentando se transformar em uma escultura de barro?",
  ui_story_5045_50451401_68_dialog_content = "R-Sério? eu nem percebi...",
  ui_story_5045_50451401_69_dialog_content = "Mas eu poderia dizer o mesmo sobre você...",
  ui_story_5045_50451401_70_dialog_content = "Quê?!",
  ui_story_5045_50451401_71_dialog_content = "Não importa. A aparência não é importante, desde que seja para minha obra-prima!",
  ui_story_5045_50451401_72_dialog_content = "Essa coisa que você está segurando é sua... obra-prima?",
  ui_story_5045_50451401_73_dialog_content = "Isso mesmo, hehe!",
  ui_story_5045_50451401_74_dialog_content = "Não entendi... O que deveria ser?",
  ui_story_5045_50451401_75_dialog_content = "O que há para não conseguir? Olhe atentamente...",
  ui_story_5045_50451401_76_dialog_content = "Este é um menino e esta é uma menina.",
  ui_story_5045_50451401_77_dialog_content = "Eles se amam profundamente. Olhando-se nos olhos com carinho, eles desejam oferecer o beijo mais doce um ao outro...",
  ui_story_5045_50451401_78_dialog_content = "Aham... Fiz este pequeno enfeite, especialmente para a Divisão Romance.",
  ui_story_5045_50451401_79_dialog_content = "Então, deveriam ser duas estatuetas de barro...",
  ui_story_5045_50451401_80_dialog_content = "Essas duas figurinhas de barro são tão fofas. Por que não pensei em fazer alguns enfeites pequenos?",
  ui_story_5045_50451401_81_dialog_content = "Sabe, esta pequena estatueta de argila parece um pouco familiar...",
  ui_story_5045_50451401_82_dialog_content = "Haha, você não acha que eles se parecem com os dois juízes?",
  ui_story_5045_50451401_83_dialog_content = "O quê?",
  ui_story_5045_50451401_84_option_content = "Acho que não.",
  ui_story_5045_50451401_85_dialog_content = "Isso mesmo, eles não são nós!",
  ui_story_5045_50451401_86_dialog_content = "Eles são apenas um menino e uma menina aleatórios que casualmente juntei.",
  ui_story_5045_50451401_87_dialog_content = "Espero que todos os amantes de Lumopolis sejam abençoados pelo Deus da Luz.",
  ui_story_5045_50451401_88_dialog_content = "Pelo menos então a Divisão Romance não estaria tão ocupada como está agora...",
  ui_story_5045_50451401_89_dialog_content = "Se estamos tão ocupados, por que você me levou para passear no campo?",
  ui_story_5045_50451401_90_dialog_content = "Porque...",
  ui_story_5045_50451401_91_dialog_content = "Huh? Porque o que?",
  ui_story_5045_50451401_92_option_content = "Posso ver a semelhança.",
  ui_story_5045_50451401_93_dialog_content = "Sério?",
  ui_story_5045_50451401_94_dialog_content = "Onde!? Eu não vejo isso!",
  ui_story_5045_50451401_95_dialog_content = "Quem eles deveriam ser então?",
  ui_story_5045_50451401_96_dialog_content = "Ninguém em particular.",
  ui_story_5045_50451401_97_dialog_content = "Estas duas estatuetas de argila são encarnações abstratas de todos os amantes do mundo!",
  ui_story_5045_50451401_98_dialog_content = "Eu só quero que todos experimentem um amor verdadeiramente lindo.",
  ui_story_5045_50451401_99_dialog_content = "Espero que durem muito, muito tempo.",
  ui_story_5045_50451401_100_dialog_content = "Tina, você realmente adora trabalhar na Divisão Romance, não é...",
  ui_story_5045_50451401_101_dialog_content = "Para dizer a verdade, não importa onde eu trabalho.",
  ui_story_5045_50451401_102_dialog_content = "No entanto, não posso negar que meus casos recentes na Divisão de Romance são realmente mais interessantes do que qualquer coisa que já encontrei antes.",
  ui_story_5045_50451401_103_dialog_content = "Se não fosse pela sua ajuda...",
  ui_story_5045_50451401_104_dialog_content = "Talvez eu não soubesse como lidar com os casos da Divisão Romance.",
  ui_story_5045_50451401_105_dialog_content = "Por que você diz isso? Você é um juiz fenomenal.",
  ui_story_5045_50451401_106_dialog_content = "Mas minha compreensão do amor era severamente deficiente.",
  ui_story_5045_50451401_107_dialog_content = "Sempre gostei das pessoas sem motivo aparente, mas no final percebi que gostava apenas da impressão que formava sobre elas em minha imaginação.",
  ui_story_5045_50451401_108_dialog_content = "Parece um sentimento tão bobo agora.",
  ui_story_5045_50451401_109_dialog_content = "Amor verdadeiro...",
  ui_story_5045_50451401_110_dialog_content = "É ajudar uns aos outros nos bons e maus momentos, lutando contra a mundanidade da vida.",
  ui_story_5045_50451401_111_dialog_content = "É a necessidade de cuidar um do outro, em vez de fazer o outro se render à submissão.",
  ui_story_5045_50451401_112_dialog_content = "Certo. Temos que agradecer a Fanny e Bacon por nos ensinar isso.",
  ui_story_5045_50451401_113_dialog_content = "Também gostaria de agradecer, PlayerName.",
  ui_story_5045_50451401_114_dialog_content = "Você me ajudou a ver...",
  ui_story_5045_50451401_115_dialog_content = "Huh? Veja o que?",
  ui_story_5045_50451401_116_dialog_content = "Zzz...",
  ui_story_5045_50451401_117_dialog_content = "Ela está dormindo?",
  ui_story_5045_50451401_118_dialog_content = "O que era Tina prestes a dizer?",
  ui_story_5045_50451401_119_dialog_content = "Acho que não terei nenhuma resposta hoje... Boa noite, então.",
  ui_story_5045_50451401_120_dialog_content = "...",
  ui_story_5045_50451401_121_dialog_content = "Eu penso Tina está sonhando.",
  ui_story_5045_50451401_122_dialog_content = "PlayerName, lembre-se de me ajudar a guardar minha obra-prima!",
  ui_story_5045_50451401_123_dialog_content = "T-tudo bem!",
  ui_story_5045_50451401_124_dialog_content = "Huh? Ela está apenas falando durante o sono?",
  ui_story_5045_50451401_125_dialog_content = "Tina realmente não fica preguiçosa quando está sonhando...",
  ui_story_5045_50451501_1_dialog_content = "<color=#737378>Horário: 15h</color>",
  ui_story_5045_50451501_2_dialog_content = "<color=#737378>Localização: Lumo Hall of Justice, Escritório da Divisão Romance</color>",
  ui_story_5045_50451501_3_dialog_content = "(Nunca pensei que terminaria um caso tão cedo.)",
  ui_story_5045_50451501_4_dialog_content = "(Minhas habilidades legais não podem ser melhores do que minhas habilidades psíquicas, podem?)",
  ui_story_5045_50451501_5_dialog_content = "(Se Irridon viu nosso julgamento, ela pode pensar em me pagar mais.)",
  ui_story_5045_50451501_6_dialog_content = "(Quando chegar a hora, heh, eu vou dar Vice e os outros uma surpresa!)",
  ui_story_5045_50451501_7_dialog_content = "(Mas então novamente...)",
  ui_story_5045_50451501_8_dialog_content = "Por que tantas pessoas estão arquivando hoje!?",
  ui_story_5045_50451501_9_dialog_content = "Huh? Perdeu o interesse no trabalho experimental tão cedo?",
  ui_story_5045_50451501_10_dialog_content = "N-De jeito nenhum!",
  ui_story_5045_50451501_11_dialog_content = "Ah, o que traz nossa sempre ocupada Senhora Irridon aqui?",
  ui_story_5045_50451501_12_dialog_content = "Zzz...",
  ui_story_5045_50451501_13_dialog_content = "Tina, acordar!",
  ui_story_5045_50451501_14_dialog_content = "Certo...",
  ui_story_5045_50451501_15_dialog_content = "Angel, o que você está esperando? Vá fazer um chá para o nosso estimado juiz supremo!",
  ui_story_5045_50451501_16_dialog_content = "... Oh.",
  ui_story_5045_50451501_17_dialog_content = "Não há necessidade.",
  ui_story_5045_50451501_18_dialog_content = "Ouvi dizer que você julgou um caso esta manhã, então vim avaliar as consequências.",
  ui_story_5045_50451501_19_dialog_content = "O caso foi conduzido pelo livro.",
  ui_story_5045_50451501_20_dialog_content = "Pelo contrário, meu julgamento amanhã inspirará o mundo e se tornará um precedente para as gerações futuras aprenderem e imitarem.",
  ui_story_5045_50451501_21_dialog_content = "Quando chegar a hora, sinta-se à vontade para voltar e testemunhar por si mesmo.",
  ui_story_5045_50451501_22_dialog_content = "Veremos. Talvez, se eu tiver tempo.",
  ui_story_5045_50451501_23_dialog_content = "Acabei de ouvir que o caso esta manhã causou um grande rebuliço. Eu quero saber os detalhes.",
  ui_story_5045_50451501_24_dialog_content = "Senhora Irridon, PlayerName e eu tentei o caso desta manhã.",
  ui_story_5045_50451501_25_dialog_content = "Registrei os detalhes e o processo de julgamento neste caderno. Por favor, dê uma olhada.",
  ui_story_5045_50451501_26_dialog_content = "Impressionante. Você formou alguns bons hábitos desde que chegou aqui, PlayerName.",
  ui_story_5045_50451501_27_dialog_content = "Você acabou de dizer que este caso causou um rebuliço?",
  ui_story_5045_50451501_28_dialog_content = "De uma vez só.",
  ui_story_5045_50451501_29_dialog_content = "Então, como a opinião pública está atualmente em relação a este caso?",
  ui_story_5045_50451501_30_dialog_content = "O que você achou?",
  ui_story_5045_50451501_31_dialog_content = "Bem... Acho que deve ser bem positivo, não?",
  ui_story_5045_50451501_32_dialog_content = "PlayerName provou ser digno de ser escolhido pessoalmente por você, Juiz Chefe, para nos auxiliar aqui.",
  ui_story_5045_50451501_33_dialog_content = "Com a ajuda de PlayerName, é natural que Tina deve fazer algum progresso também.",
  ui_story_5045_50451501_34_dialog_content = "Talvez não demore muito para que ela se torne a segunda melhor juíza da Divisão de Romance!",
  ui_story_5045_50451501_35_dialog_content = "Tina, são PlayerNameregistros completos?",
  ui_story_5045_50451501_36_dialog_content = "Sim, eu fiz PlayerName anote tudo detalhadamente.",
  ui_story_5045_50451501_37_dialog_content = "A investigação apenas arranhou a superfície, e as partes não foram autorizadas a se explicar totalmente no tribunal...",
  ui_story_5045_50451501_38_dialog_content = "Tina, você tem dormido no tribunal?",
  ui_story_5045_50451501_39_dialog_content = "Eu-eu não fiz nada do tipo... Bocejo—",
  ui_story_5045_50451501_40_dialog_content = "Eu estava lutando contra um ataque de sonolência esta manhã, então eu estava dormindo até agora.",
  ui_story_5045_50451501_41_dialog_content = "A Divisão Romance acabou de ser estabelecida e não há casos para aprendermos.",
  ui_story_5045_50451501_42_dialog_content = "Eu entendo a pressão.",
  ui_story_5045_50451501_43_dialog_content = "Mas lembre-se de que mesmo um pequeno caso aos nossos olhos pode afetar a vida das partes envolvidas.",
  ui_story_5045_50451501_44_dialog_content = "A maneira como você lida com cada caso afetará a atitude do povo de Lumopolis em relação aos relacionamentos amorosos no futuro.",
  ui_story_5045_50451501_45_dialog_content = "Parece que a opinião pública, como resultado de assumir o caso esta manhã, não é muito boa...",
  ui_story_5045_50451501_46_dialog_content = "Aqueles que defendem a liberdade no amor e no casamento estão muito insatisfeitos com o julgamento desta manhã.",
  ui_story_5045_50451501_47_dialog_content = "Podemos ver apelos retaliatórios contra o Tribunal de Justiça em um futuro próximo.",
  ui_story_5045_50451501_48_dialog_content = "Preparem-se.",
  ui_story_5045_50451501_49_dialog_content = "Apelos retaliatórios?",
  ui_story_5045_50451501_50_dialog_content = "Podemos até ver pessoas se casando intencionalmente e depois pedindo o divórcio.",
  ui_story_5045_50451501_51_dialog_content = "Já que Tina é a pessoa que provocou todo esse problema, vamos Tina lidar com tais apelos por si mesma.",
  ui_story_5045_50451501_52_dialog_content = "Zzz...",
  ui_story_5045_50451501_53_dialog_content = "Bem, parece Tina aprova.",
  ui_story_5045_50451501_54_dialog_content = "Huh? E-espere...",
  ui_story_5045_50451501_55_dialog_content = "Então, essencialmente, tenho que lidar com todos os casos de divórcio que chegam aqui?",
  ui_story_5045_50451501_56_dialog_content = "Quantas sessões serão necessárias para concluir cada tentativa?",
  ui_story_5045_50451601_1_dialog_content = "<color=#737378>Horário: 15h</color>",
  ui_story_5045_50451601_2_dialog_content = "<color=#737378>Local: Lumo Hall of Justice, Tribunal</color>",
  ui_story_5045_50451601_3_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451601_4_dialog_content = "<size=45>Tribunal está em sessão!</size>",
  ui_story_5045_50451601_5_dialog_content = "Em primeiro lugar, vamos ouvir o que o autor tem a dizer.",
  ui_story_5045_50451601_6_dialog_content = "Hum? E quem é você?",
  ui_story_5045_50451601_7_dialog_content = "Você pode realmente fazer um bom trabalho ao tentar o meu caso?",
  ui_story_5045_50451601_8_dialog_content = "Ordem!",
  ui_story_5045_50451601_9_dialog_content = "Por favor, não levante questões irrelevantes para este caso.",
  ui_story_5045_50451601_10_dialog_content = "Quanta impudência!",
  ui_story_5045_50451601_11_dialog_content = "Você sabe quem eu sou? Onde um juizzinho patético como você tem o direito de falar assim comigo?",
  ui_story_5045_50451601_12_dialog_content = "Eu deveria denunciá-lo a Irridon!",
  ui_story_5045_50451601_13_dialog_content = "Sou um juiz estagiário, nomeado pessoalmente pelo Juiz Chefe Irridon.",
  ui_story_5045_50451601_14_dialog_content = "Por favor, coopere na manutenção da ordem no Tribunal de Justiça.",
  ui_story_5045_50451601_15_dialog_content = "Hmph! Apenas espere!",
  ui_story_5045_50451601_16_dialog_content = "Huh? Requerente, onde você está indo?",
  ui_story_5045_50451601_17_dialog_content = "<color=#737378>Hora: 16:00</color>",
  ui_story_5045_50451601_18_dialog_content = "<color=#737378>Local: Lumo Hall of Justice</color>",
  ui_story_5045_50451601_19_dialog_content = "Senhora Irridon, você tem me procurado?",
  ui_story_5045_50451601_20_dialog_content = "PlayerName, você está ciente de que alguém apresentou uma queixa contra você?",
  ui_story_5045_50451601_21_dialog_content = "Huh? Aquele cara realmente reclamou de mim agora?",
  ui_story_5045_50451601_22_dialog_content = "Mas acho que não falei nada de errado. Ele mostrou total falta de respeito com a ordem do Tribunal de Justiça!",
  ui_story_5045_50451601_23_dialog_content = "Ele tem seus problemas. Naturalmente, isso é algo que eu entendo muito bem.",
  ui_story_5045_50451601_24_dialog_content = "Mas você...",
  ui_story_5045_50451601_25_dialog_content = "Pedi para você ir à Divisão Romance para ajudar, mas não lhe dei permissão para ouvir os casos sozinho.",
  ui_story_5045_50451601_26_dialog_content = "Eu não acho que seja tão difícil, então talvez, talvez eu possa...",
  ui_story_5045_50451601_27_dialog_content = "Se fosse tão fácil se tornar um juiz de verdade, mesmo Angel teria passado no exame do julgamento simulado.",
  ui_story_5045_50451601_28_dialog_content = "Admito que você tem um dom.",
  ui_story_5045_50451601_29_dialog_content = "Mas isso não significa que você pode pular a etapa de aprendizado e se tornar um juiz imediatamente.",
  ui_story_5045_50451601_30_dialog_content = "Mesmo um gênio nascido em uma família de juízes deveria começar como magistrado assistente.",
  ui_story_5045_50451601_31_dialog_content = "Sinto muito...",
  ui_story_5045_50451601_32_dialog_content = "Eu entendo. Vou voltar e trabalhar ainda mais como assistente agora!",
  ui_story_5045_50451601_33_dialog_content = "...",
  ui_story_5045_50451601_34_dialog_content = "Não há necessidade disso.",
  ui_story_5045_50451601_35_dialog_content = "Sério?",
  ui_story_5045_50451601_36_dialog_content = "Para evitar que esse assunto fermente a ponto de o público entender mal as intenções do Tribunal de Justiça...",
  ui_story_5045_50451601_37_dialog_content = "Eu sinto muito, PlayerName, mas não pode mais continuar trabalhando na Sala da Justiça.",
  ui_story_5045_50451601_38_dialog_content = "Bem, e quanto ao meu pagamento...?",
  ui_story_5045_50451601_39_dialog_content = "O Tribunal de Justiça teve que pagar uma grande quantia para apaziguar o reclamante agora.",
  ui_story_5045_50451601_40_dialog_content = "Seu pagamento está longe de ser suficiente para cobrir essa compensação.",
  ui_story_5045_50451601_41_dialog_content = "Mas, como tenho minha própria responsabilidade neste assunto, não pedirei que você pague nenhuma taxa adicional por essa compensação.",
  ui_story_5045_50451601_42_dialog_content = "Se você estiver disposto a assistir a qualquer um dos julgamentos aqui, as portas do Tribunal de Justiça ainda estão abertas para você.",
  ui_story_5045_50451601_43_dialog_content = "Hum...",
  ui_story_5045_50451601_44_dialog_content = "M-Meu pagamento...",
  ui_story_5045_50451601_45_dialog_content = "Se eu soubesse que isso aconteceria, teria sido assistente deles e nada mais!",
  ui_story_5045_50451601_46_dialog_content = "E quanto a este caderno... Receio que você não possa ficar com ele.",
  ui_story_5045_50451601_47_dialog_content = "Tomei a liberdade de pegá-lo, pois já estou aqui.",
  ui_story_5045_50451601_48_dialog_content = "Senhora Irridon, n-não vá...",
  ui_story_5045_50451601_49_dialog_content = "Desta vez...",
  ui_story_5045_50451601_50_dialog_content = "Eu realmente errei muito dessa vez...",
  ui_story_5045_50451701_1_dialog_content = "<color=#737378>Hora: 8h00</color>",
  ui_story_5045_50451701_2_dialog_content = "<color=#737378>Localização: Lumo Hall of Justice, Escritório da Divisão Romance</color>",
  ui_story_5045_50451701_3_dialog_content = "O casamento deve ser arranjado pela família. Isso é responsabilidade da nobreza!",
  ui_story_5045_50451701_4_dialog_content = "Se sua família arranjasse para você se casar com uma esposa desleixada que se recusasse a tomar banho, você aceitaria seu destino?",
  ui_story_5045_50451701_5_dialog_content = "Acredito que minha família nunca encontraria uma esposa assim para mim.",
  ui_story_5045_50451701_6_dialog_content = "Mas você não pode ter certeza disso.",
  ui_story_5045_50451701_7_dialog_content = "No final, todos vocês só querem maximizar seus interesses e propriedades e não se importam com os sentimentos da parte interessada!",
  ui_story_5045_50451701_8_dialog_content = "Eu sou o juiz que preside este caso! Todos devem respeitar meu julgamento!",
  ui_story_5045_50451701_9_dialog_content = "Se o seu julgamento estiver errado, eu serei o único a ser repreendido como você é...",
  ui_story_5045_50451701_10_dialog_content = "O que está acontecendo com Matthieu e Angel?",
  ui_story_5045_50451701_11_dialog_content = "Obviamente, eles não podem concordar sobre o caso atualmente em julgamento.",
  ui_story_5045_50451701_12_dialog_content = "Por que eles ainda estão lutando? Algumas pessoas estão tentando dormir aqui—Bocejo—",
  ui_story_5045_50451701_13_dialog_content = "A menos que alguém faça algo sobre isso, eles vão continuar lutando até o sol se pôr...",
  ui_story_5045_50451701_14_dialog_content = "Que tal perguntarmos o que está acontecendo? Talvez possamos ajudar.",
  ui_story_5045_50451701_15_dialog_content = "Se você diz, PlayerName...",
  ui_story_5045_50451701_16_dialog_content = "Bem, não podemos simplesmente sentar e não fazer nada.",
  ui_story_5045_50451701_17_dialog_content = "Então... Matthieu, Angel, do que se trata?",
  ui_story_5045_50451701_18_dialog_content = "Você chegou bem na hora. Por favor, me escute e me diga se meu julgamento é razoável.",
  ui_story_5045_50451701_19_dialog_content = "A única filha de um grande nobre está processando seus pais, alegando que eles interferiram em sua liberdade de amar.",
  ui_story_5045_50451701_20_dialog_content = "Senti que o caso não era tão simples quanto parecia, então trouxe Angel para visitá-los e coletar evidências.",
  ui_story_5045_50451701_21_dialog_content = "Acontece que sua única filha se apaixonou por um menino pobre que nem tem um emprego decente.",
  ui_story_5045_50451701_22_dialog_content = "Não, foram aqueles nobres pais que deliberadamente o fizeram perder o emprego! Ele costumava ser um bom cozinheiro.",
  ui_story_5045_50451701_23_dialog_content = "Não confirmamos isso por meio de nossa investigação?",
  ui_story_5045_50451701_24_dialog_content = "Mas ele é um plebeu. De jeito nenhum ele se aproximou de uma garota nobre sem outra intenção!",
  ui_story_5045_50451701_25_dialog_content = "Discordo!",
  ui_story_5045_50451701_26_dialog_content = "Esta nobre garota está disposta a desistir de toda a sua riqueza por ele...",
  ui_story_5045_50451701_27_dialog_content = "Ele também quer desistir de persegui-la para não comprometer o futuro da nobre garota.",
  ui_story_5045_50451701_28_dialog_content = "Este é um amor puro.",
  ui_story_5045_50451701_29_dialog_content = "Como você disse, o pobre menino finalmente percebeu a distância entre suas circunstâncias e estava disposto a desistir desse relacionamento.",
  ui_story_5045_50451701_30_dialog_content = "Então julguei que os nobres pais estavam certos. Existe algum problema com isso?",
  ui_story_5045_50451701_31_dialog_content = "Parece muito complicado...",
  ui_story_5045_50451701_32_dialog_content = "Huh? O que é isso no chão?",
  ui_story_5045_50451701_33_dialog_content = "Acho que já vi isso em algum lugar antes?",
  ui_story_5045_50451701_34_dialog_content = "Acho que não. Mas eu me lembro...",
  ui_story_5045_50451701_35_dialog_content = "Lembro que depois da investigação, definitivamente devolvi isso para Sophie...",
  ui_story_5045_50451701_36_dialog_content = "Acho que não tinha notado antes, mas isso <color=#1875ad>cartão de presença</color> é idêntico ao de Bacon!",
  ui_story_5045_50451701_37_dialog_content = "Eu definitivamente devolvi isso a Bacon após a investigação...",
  ui_story_5045_50451701_38_dialog_content = "Acho que não tinha notado antes, mas isso <color=#1875ad>cartão de presença</color> é idêntico ao da Sophie!",
  ui_story_5045_50451701_39_dialog_content = "Mas...",
  ui_story_5045_50451701_40_dialog_content = "Desculpe, esta é a evidência que acabei de encontrar! Eu não notei um deles antes...",
  ui_story_5045_50451701_41_dialog_content = "Obrigado, PlayerName. Se alguém tivesse pegado, teria sido difícil explicar.",
  ui_story_5045_50451701_42_dialog_content = "Angel, é melhor você terminar seu trabalho e então discutiremos como julgar este caso.",
  ui_story_5045_50451701_43_dialog_content = "...",
  ui_story_5045_50451701_44_dialog_content = "Angel, de quem é este cartão de presença?",
  ui_story_5045_50451701_45_dialog_content = "Eh? Você é bom! Apenas um olhar e você sabia que era um cartão de presença?",
  ui_story_5045_50451701_46_dialog_content = "Isso é o que encontramos em <color=#1875ad>Karl</color>casa de. Segundo ele, estudou direito nesse curso de autoajuda...",
  ui_story_5045_50451701_47_dialog_content = "Parece que ele quer mudar sua situação atual e se esforçar para se tornar um juiz.",
  ui_story_5045_50451701_48_dialog_content = "Não, tem alguma coisa errada aqui...",
  ui_story_5045_50451701_49_dialog_content = "É um cartão... Parece uma espécie de cartão de presença.",
  ui_story_5045_50451701_50_dialog_content = "Oh sim. Comecei a ter algumas aulas de limpeza recentemente.",
  ui_story_5045_50451701_51_dialog_content = "Huh? O que é essa carta aqui na mesa?",
  ui_story_5045_50451701_52_dialog_content = "... Isso é do <color=#1875ad>curso de autoajuda</color>. É um cartão de presença.",
  ui_story_5045_50451701_53_dialog_content = "Eles ajudam as pessoas a desenvolver sua força de vontade para que não tenham mais medo de enfrentar as dificuldades da vida.",
  ui_story_5045_50451701_54_dialog_content = "Ouvi dizer que muitos dos alunos que fizeram este curso se tornaram os mais novos milionários de Lumopolis.",
  ui_story_5045_50451701_55_dialog_content = "Por que os cursos sobre os quais todos estão falando são diferentes?",
  ui_story_5045_50451701_56_dialog_content = "Será que...?",
  ui_story_5045_50451701_57_dialog_content = "<size=45>!!!</size>",
  ui_story_5045_50451701_58_dialog_content = "Matthieu, o nome do pobre rapaz por quem a nobre moça se apaixonou no seu caso...",
  ui_story_5045_50451701_59_dialog_content = "Ele se chama Karl. Oh, realmente, por que devo ser obrigado a dizer o nome de um plebeu?",
  ui_story_5045_50451701_60_dialog_content = "acho que já conheci <color=#1875ad>Karl</color> em algum lugar antes...",
  ui_story_5045_50451701_61_dialog_content = "Não é isso! Eu lembro...",
  ui_story_5045_50451701_62_dialog_content = "Lembro que o vizinho da Sophie se chamava Karl!",
  ui_story_5045_50451701_63_dialog_content = "E o amigo de Bacon e Fanny também se chamava Karl...",
  ui_story_5045_50451701_64_dialog_content = "Eu lembro! Karl era o nome de Bacon e amigo de Fanny!",
  ui_story_5045_50451701_65_dialog_content = "E acho que o vizinho da Sophie também se chamava Karl...",
  ui_story_5045_50451701_66_dialog_content = "Pode ser simplesmente uma coincidência?",
  ui_story_5045_50451701_67_dialog_content = "PlayerName, o que você estava resmungando para si mesmo agora?",
  ui_story_5045_50451701_68_dialog_content = "Não podemos ajudar no caso de Matthieu.",
  ui_story_5045_50451701_69_dialog_content = "Vamos tentar lidar com os casos pelos quais somos responsáveis agora.",
  ui_story_5045_50451701_70_dialog_content = "PlayerName, quem você vai ajudar desta vez?",
  ui_story_5045_50451701_71_dialog_content = "Por que não deixamos PlayerName se revezam para nos ajudar, como no outro dia?",
  ui_story_5045_50451701_72_dialog_content = "Isso seria justo, não?",
  ui_story_5045_50451701_73_dialog_content = "Desculpe, eu quero sair um pouco para investigar algo...",
  ui_story_5045_50451701_74_dialog_content = "Huh? Se você não está investigando o caso, o que está investigando exatamente?",
  ui_story_5045_50451701_75_dialog_content = "É sobre aquele curso de autoajuda... Provavelmente não é nada, espero estar pensando demais.",
  ui_story_5045_50451701_76_dialog_content = "<color=#737378>Hora: 9:00 AM</color>",
  ui_story_5045_50451701_77_dialog_content = "<color=#737378>Localização: Lumopolis, Lower Lumopolis</color>",
  ui_story_5045_50451701_78_dialog_content = "Karl!",
  ui_story_5045_50451701_79_dialog_content = "Huh? Você é...",
  ui_story_5045_50451701_80_dialog_content = "Você não se lembra de mim? Eu sou o assistente dos juízes, PlayerName.",
  ui_story_5045_50451701_81_dialog_content = "Já nos encontramos duas vezes antes.",
  ui_story_5045_50451701_82_dialog_content = "Oh, Meritíssimo! O que posso fazer para você?",
  ui_story_5045_50451701_83_dialog_content = "Sim, na verdade - você sabe onde posso encontrar esse curso de autoajuda?",
  ui_story_5045_50451701_84_dialog_content = "Como posso saber?",
  ui_story_5045_50451701_85_dialog_content = "Porque Fanny disse que você a apresentou a ela, então pensei que talvez você soubesse algo sobre isso.",
  ui_story_5045_50451701_86_dialog_content = "Então, é assim - alguém acabou de mencionar isso para mim.",
  ui_story_5045_50451701_87_dialog_content = "Achei que provavelmente era apenas algum lugar que vendia paz de espírito para pessoas desesperadas.",
  ui_story_5045_50451701_88_dialog_content = "Mas para as pessoas que se sentem sem esperança em suas vidas, paz de espírito é exatamente o que lhes falta.",
  ui_story_5045_50451701_89_dialog_content = "... Eu vejo. Há mais alguma coisa que você possa me dizer?",
  ui_story_5045_50451701_90_dialog_content = "Desculpe, é tudo o que sei.",
  ui_story_5045_50451701_91_dialog_content = "Tudo bem, obrigado pelo seu tempo.",
  ui_story_5045_50451701_92_dialog_content = "Eu vou embora então. Tudo de bom.",
  ui_story_5045_50451701_93_dialog_content = "(Definitivamente há algo errado com esse Karl.)",
  ui_story_5045_50451701_94_dialog_content = "(É melhor eu segui-lo e ver para onde ele está indo. Talvez encontre mais algumas pistas.)",
  ui_story_5045_50451701_95_dialog_content = "(Mas...)",
  ui_story_5045_50451701_96_dialog_content = "Onde ele foi? Ele simplesmente desapareceu em um piscar de olhos assim!",
  ui_story_5045_50451701_97_dialog_content = "<color=#737378>Em algum momento, em algum lugar</color>",
  ui_story_5045_50451701_98_dialog_content = "O que você está fazendo parado como um idiota? Vá encontrar o seu alvo.",
  ui_story_5045_50451701_99_dialog_content = "B-Mas eu...",
  ui_story_5045_50451701_100_dialog_content = "Eu não quero fazer isso!",
  ui_story_5045_50451701_101_dialog_content = "Desculpe, Guru de Autoajuda, me perdoe!",
  ui_story_5045_50451701_102_dialog_content = "Tudo bem, não estou te forçando.",
  ui_story_5045_50451701_103_dialog_content = "Então... posso ir para casa?",
  ui_story_5045_50451701_104_dialog_content = "Espere. Não tão rápido.",
  ui_story_5045_50451701_105_dialog_content = "Embora você esteja aqui há apenas meio dia, certamente você pode fazer mais uma coisa por mim?",
  ui_story_5045_50451701_106_dialog_content = "Caso contrário, sua esposa pode acabar ficando chateada.",
  ui_story_5045_50451801_1_dialog_content = "<color=#737378>Hora: 16:00</color>",
  ui_story_5045_50451801_2_dialog_content = "<color=#737378>Localização: Lumo Hall of Justice, Escritório da Divisão Romance</color>",
  ui_story_5045_50451801_3_dialog_content = "Já de volta, PlayerName?",
  ui_story_5045_50451801_4_dialog_content = "Como está indo sua investigação?",
  ui_story_5045_50451801_5_dialog_content = "A liderança era um beco sem saída, mas ainda não consigo me livrar desse sentimento desconfortável.",
  ui_story_5045_50451801_6_dialog_content = "A propósito, onde estão Matthieu e Angel?",
  ui_story_5045_50451801_7_dialog_content = "Parece Matthieu quer colocar este caso em banho-maria.",
  ui_story_5045_50451801_8_dialog_content = "Angel foi com Matthieu investigar outro caso. Não se preocupe com eles - é melhor você pensar sobre...",
  ui_story_5045_50451801_9_dialog_content = "Quem você planeja ajudar hoje?",
  ui_story_5045_50451801_10_dialog_content = "Eu...",
  ui_story_5045_50451801_11_dialog_content = "Desculpe-me, é PlayerName aqui?",
  ui_story_5045_50451801_12_dialog_content = "Amy? Há algo em que posso ajudá-lo?",
  ui_story_5045_50451801_13_dialog_content = "Eu... estou aqui para <color=#1875ad>prender prisão</color> você!",
  ui_story_5045_50451801_14_dialog_content = "Me prenda!? Pelo que?",
  ui_story_5045_50451801_15_dialog_content = "Alguém o denunciou ao Supremo Tribunal, dizendo que você criou uma organização ilegal em Lumopolis especializada em cometer fraudes.",
  ui_story_5045_50451801_16_dialog_content = "Porque o escopo da alegada fraude é particularmente vasto e a natureza é particularmente grave...",
  ui_story_5045_50451801_17_dialog_content = "O Tribunal de Justiça decidiu prendê-lo e começar o julgamento amanhã!",
  ui_story_5045_50451801_18_dialog_content = "Isso deve ser um erro, não?",
  ui_story_5045_50451801_19_dialog_content = "PlayerName tem nos ajudado com nosso trabalho sem parar recentemente.",
  ui_story_5045_50451801_20_dialog_content = "Não há erro. O autor disse que o réu era um celestita que trabalhava no Tribunal de Justiça.",
  ui_story_5045_50451801_21_dialog_content = "A menos que eu esteja enganado, você é o único celestita por aqui.",
  ui_story_5045_50451801_22_dialog_content = "Hã...",
  ui_story_5045_50451801_23_dialog_content = "<color=#737378>Hora: 9:00 AM, o dia seguinte</color>",
  ui_story_5045_50451801_24_dialog_content = "<color=#737378>Localização: Lumo Hall of Justice, Tribunal Principal</color>",
  ui_story_5045_50451801_25_dialog_content = "(A galeria do Hall of Justice está cheia de audiências sussurrantes.)",
  ui_story_5045_50451801_26_dialog_content = "(Ondas de olhos enojados parecem que estão prestes a me despedaçar.)",
  ui_story_5045_50451801_27_dialog_content = "(Alguns dias atrás, eu ainda era um juiz estagiário sentado no banco, mas hoje...)",
  ui_story_5045_50451801_28_dialog_content = "(Leyn, Tina... Eles não vieram?)",
  ui_story_5045_50451801_29_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451801_30_dialog_content = "<size=45>Noite Branca no alto. Tribunal está agora em sessão!</size>",
  ui_story_5045_50451801_31_dialog_content = "Avante, Noite Branca.",
  ui_story_5045_50451801_32_option_content = "Avante, Noite Branca...",
  ui_story_5045_50451801_33_dialog_content = "Eu não posso acreditar que ele realmente disse isso! Como ele ousa!",
  ui_story_5045_50451801_34_option_content = "Eu fui enganado!",
  ui_story_5045_50451801_35_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451801_36_dialog_content = "O réu é solicitado a observar as regras e regulamentos do tribunal.",
  ui_story_5045_50451801_37_dialog_content = "Observe que você perderá a oportunidade de se defender após receber três advertências.",
  ui_story_5045_50451801_38_dialog_content = "(Eu conheço as regras... Por que de repente eu me esqueci agora!?)",
  ui_story_5045_50451801_39_option_content = "Objeção!",
  ui_story_5045_50451801_40_dialog_content = "PlayerName, você trabalha no Tribunal de Justiça há algum tempo.",
  ui_story_5045_50451801_41_dialog_content = "Você ainda precisa que eu lhe ensine sobre o processo e as medidas disciplinares praticadas aqui no Tribunal de Justiça?",
  ui_story_5045_50451801_42_dialog_content = "(Lembro-me das medidas disciplinares, mas ser réu de repente... Quem não ficaria um pouco afobado...?)",
  ui_story_5045_50451801_43_dialog_content = "Agora, vamos convidar o autor <color=#1875ad>Bacon</color> falar.",
  ui_story_5045_50451801_44_dialog_content = "Meritíssimo, eu sou Bacon.",
  ui_story_5045_50451801_45_dialog_content = "(É Bacon?!? Ele estava descontente com o julgamento Tina e cheguei da última vez?)",
  ui_story_5045_50451801_46_dialog_content = "(Mas depois do julgamento, fomos juntos para o campo. Tudo estava bem então.)",
  ui_story_5045_50451801_47_dialog_content = "Hoje, eu... desejo processar PlayerName em nome de milhares de vítimas em Lumopolis.",
  ui_story_5045_50451801_48_dialog_content = "A razão disso é...",
  ui_story_5045_50451801_49_dialog_content = "Dele <color=#1875ad>curso de autoajuda</color> é supostamente um programa de treinamento que ensina habilidades para pessoas necessitadas.",
  ui_story_5045_50451801_50_dialog_content = "A verdade é que tudo o que ele ensina a seus alunos...",
  ui_story_5045_50451801_51_dialog_content = "... é como manipular as emoções das pessoas para extorquir os ricos!",
  ui_story_5045_50451801_52_dialog_content = "<size=45>O que!?</size>",
  ui_story_5045_50451801_53_dialog_content = "Não acredito que existe tanta sujeira em Lumopolis!",
  ui_story_5045_50451801_54_dialog_content = "Esse canalha deve ter entrado sorrateiramente em Lumopolis!",
  ui_story_5045_50451801_55_dialog_content = "PlayerName, você admite as acusações do autor contra você?",
  ui_story_5045_50451801_56_dialog_content = "Eu não fiz nada disso e nem sei onde está esse curso de autoajuda!",
  ui_story_5045_50451801_57_dialog_content = "Bacon, alguém mandou você vir aqui fazer isso?",
  ui_story_5045_50451801_58_dialog_content = "Ué, eu...",
  ui_story_5045_50451801_59_dialog_content = "Não!",
  ui_story_5045_50451801_60_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451801_61_dialog_content = "O réu é instado a não induzir o autor em erro.",
  ui_story_5045_50451801_62_dialog_content = "(Mas Bacon claramente parece preocupado com alguma coisa.)",
  ui_story_5045_50451801_63_dialog_content = "(Fui preso depois de procurar por Karl ontem... Não pode ser coincidência!)",
  ui_story_5045_50451801_64_dialog_content = "Autor, você disse que tem duas testemunhas que podem provar tudo o que você alegou até agora.",
  ui_story_5045_50451801_65_dialog_content = "Está correto, Meritíssimo.",
  ui_story_5045_50451801_66_dialog_content = "Eu peço que o primeiro <color=#1875ad>testemunha</color> tome posição!",
  ui_story_5045_50451801_67_dialog_content = "Avante, Noite Branca.",
  ui_story_5045_50451801_68_dialog_content = "(Sophie!?)",
  ui_story_5045_50451801_69_dialog_content = "(Bem, bem... É exatamente como eu pensei.)",
  ui_story_5045_50451801_70_option_content = "Objeção!",
  ui_story_5045_50451801_71_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451801_72_dialog_content = "Agora é a vez de Sophie falar. O réu é solicitado a observar as regras e regulamentos do tribunal.",
  ui_story_5045_50451801_73_dialog_content = "Não acabei de dizer que você perderá a oportunidade de se defender depois de receber três advertências?",
  ui_story_5045_50451801_74_dialog_content = "(Oh... não posso deixar meus nervos levarem a melhor sobre mim!)",
  ui_story_5045_50451801_75_dialog_content = "(Mais um aviso e pronto!)",
  ui_story_5045_50451801_76_option_content = "(Fique em silêncio)",
  ui_story_5045_50451801_77_dialog_content = "(Quero ouvir o que ela vai dizer.)",
  ui_story_5045_50451801_78_dialog_content = "Meritíssimo, meu nome é Sophie. Posso provar que o que Bacon disse é verdade.",
  ui_story_5045_50451801_79_dialog_content = "Sou um dos primeiros alunos deste curso de autoajuda.",
  ui_story_5045_50451801_80_dialog_content = "PlayerName me disse que ele era o último celestita e sabia como manipular a mente das pessoas.",
  ui_story_5045_50451801_81_dialog_content = "Nós, estudantes, o reverenciamos como o Guru da Autoajuda.",
  ui_story_5045_50451801_82_dialog_content = "Mas ele usou intimidação, coerção e outros meios para nos fazer sair, manipular as emoções das pessoas e roubar seu dinheiro.",
  ui_story_5045_50451801_83_dialog_content = "Não tínhamos permissão para ficar com o dinheiro que extorquimos das pessoas e tínhamos de entregar tudo a ele.",
  ui_story_5045_50451801_84_dialog_content = "Em outras palavras, você admite que também está envolvido na extorsão ilegal de riqueza?",
  ui_story_5045_50451801_85_dialog_content = "De uma vez só.",
  ui_story_5045_50451801_86_dialog_content = "Isso significa que você será julgado de acordo. Você entende?",
  ui_story_5045_50451801_87_dialog_content = "Eu entendo, mas minha consciência não aguenta mais. Não quero que mais ninguém sofra.",
  ui_story_5045_50451801_88_dialog_content = "Em vez de continuar me atrapalhando pelo resto da minha vida, espero defender algo que valha a pena, só desta vez.",
  ui_story_5045_50451801_89_dialog_content = "(Sophie parece tão sincera... Se ela não estivesse me acusando, eu acreditaria!)",
  ui_story_5045_50451801_90_dialog_content = "PlayerName, Você tem algo a dizer?",
  ui_story_5045_50451801_91_dialog_content = "(Existe alguma evidência para provar que <color=#1875ad>o que a sophia disse é falso</color>...)",
  ui_story_5045_50451801_92_dialog_content = "O que você quer dizer com isso?",
  ui_story_5045_50451801_93_dialog_content = "(Ah, não! Não é?)",
  ui_story_5045_50451801_94_dialog_content = "Senhora Irridon! Este é o caderno do juiz que você me deu?",
  ui_story_5045_50451801_95_dialog_content = "Hum? Embora você ainda possua um caderno de juiz, agora você é um réu no Tribunal de Justiça.",
  ui_story_5045_50451801_96_dialog_content = "Este notebook não irá ajudá-lo.",
  ui_story_5045_50451801_97_dialog_content = "Posso jurar no caderno deste juiz que não sou o Guru de Autoajuda que ela está fazendo de mim!",
  ui_story_5045_50451801_98_dialog_content = "Sinto muito, PlayerName.",
  ui_story_5045_50451801_99_dialog_content = "Se tais juramentos fossem de alguma utilidade, não haveria necessidade do Tribunal de Justiça.",
  ui_story_5045_50451801_100_dialog_content = "(Isso também não vai funcionar?)",
  ui_story_5045_50451801_101_dialog_content = "Meritíssimo, Sophie uma vez forjou provas durante um julgamento!",
  ui_story_5045_50451801_102_dialog_content = "Realmente? Isso é verdade?",
  ui_story_5045_50451801_103_dialog_content = "M-Mas daquela vez, eu tinha que fazer isso.",
  ui_story_5045_50451801_104_dialog_content = "Naquela época, eu estava com medo de que Farrell descobrisse sobre nosso curso de autoajuda...",
  ui_story_5045_50451801_105_dialog_content = "Se isso acontecesse, o Guru de Autoajuda me puniria.",
  ui_story_5045_50451801_106_dialog_content = "Agora que você o capturou, não tenho nada a temer!",
  ui_story_5045_50451801_107_dialog_content = "Bem, isso é realmente desculpável.",
  ui_story_5045_50451801_108_dialog_content = "Então vamos chamar a segunda testemunha.",
  ui_story_5045_50451801_109_dialog_content = "Meritíssimo, meu nome é Karl.",
  ui_story_5045_50451801_110_dialog_content = "Eu tinha um compromisso para jantar com Bacon ontem, mas ele não apareceu.",
  ui_story_5045_50451801_111_dialog_content = "Felizmente, Bacon me disse para onde estava indo. Levei muito tempo para encontrá-lo.",
  ui_story_5045_50451801_112_dialog_content = "Por fim, encontrei o lendário curso de autoajuda.",
  ui_story_5045_50451801_113_dialog_content = "Chegando lá, ouvi Bacon dizer que não queria aceitar a tarefa que lhe fora atribuída pelo Guru da Autoajuda, e insistiu em ir embora comigo.",
  ui_story_5045_50451801_114_dialog_content = "Senti que algo estava muito errado, então acendi uma fogueira em meio ao caos e escapei com Bacon.",
  ui_story_5045_50451801_115_dialog_content = "Para escapar, o lendário Guru de Autoajuda tirou seu manto preto e revelou sua verdadeira face.",
  ui_story_5045_50451801_116_dialog_content = "Em outras palavras, você viu como era o Guru de Autoajuda?",
  ui_story_5045_50451801_117_dialog_content = "De uma vez só.",
  ui_story_5045_50451801_118_dialog_content = "E você vê esse Guru de Autoajuda aqui no tribunal hoje?",
  ui_story_5045_50451801_119_dialog_content = "Sim. O Guru da Autoajuda é o cavalheiro sentado no banco dos réus.",
  ui_story_5045_50451801_120_dialog_content = "(Como pode ser isso? O que esse tal de Karl pensa que está fazendo...?)",
  ui_story_5045_50451801_121_dialog_content = "(Ah sim, eu sei de algo que pode funcionar aqui!)",
  ui_story_5045_50451801_122_option_content = "Conexão mental!",
  ui_story_5045_50451801_123_dialog_content = "(Foi uma jogada inteligente afirmar ser o Celestita ao criar aquele curso de autoajuda.)",
  ui_story_5045_50451801_124_dialog_content = "(Agora todos sabem que o Guru de Autoajuda é o Celestita, e ninguém tem a menor ideia sobre minha verdadeira identidade.)",
  ui_story_5045_50451801_125_dialog_content = "(É uma pena que o curso de autoajuda tenha que terminar aqui... Felizmente, ganhei mais do que o suficiente com ele.)",
  ui_story_5045_50451801_126_dialog_content = "Droga, o verdadeiro Guru de Autoajuda é na verdade Karl!",
  ui_story_5045_50451801_127_dialog_content = "(Meu querido PlayerName, sei que há uma chance de você estar ouvindo minha voz interior agora.)",
  ui_story_5045_50451801_128_dialog_content = "O que? Como ele sabia?",
  ui_story_5045_50451801_129_dialog_content = "(Você pode ouvir os pensamentos das pessoas graças ao seu talento especial...)",
  ui_story_5045_50451801_130_dialog_content = "(Mas posso inferir seus pensamentos através de cada movimento seu.)",
  ui_story_5045_50451801_131_dialog_content = "(Então, qual de nós é mais poderoso?)",
  ui_story_5045_50451801_132_dialog_content = "Meritíssimo!",
  ui_story_5045_50451801_133_dialog_content = "Eu descobri através da minha habilidade psíquica que Karl é o Guru de Autoajuda!",
  ui_story_5045_50451801_134_dialog_content = "Esse réu realmente sabe como manipular as pessoas!",
  ui_story_5045_50451801_135_dialog_content = "Como podemos acreditar em qualquer coisa que ele diz!?",
  ui_story_5045_50451801_136_dialog_content = "Parece que esse método não vai funcionar aqui...",
  ui_story_5045_50451801_137_dialog_content = "Mas deve haver uma contradição escondida em algum lugar <color=#1875ad>testemunho de Karl</color>.",
  ui_story_5045_50451801_138_dialog_content = "O que você quer dizer?",
  ui_story_5045_50451801_139_dialog_content = "Erm, eu só queria dizer...",
  ui_story_5045_50451801_140_dialog_content = "O Karl me disse ontem que nunca tinha ido ao curso de autoajuda e nem sabia onde era!",
  ui_story_5045_50451801_141_dialog_content = "Mas agora há pouco, ele disse que Bacon lhe deu o endereço!",
  ui_story_5045_50451801_142_dialog_content = "Isso porque, quando te vi, ainda não tinha combinado jantar com Bacon.",
  ui_story_5045_50451801_143_dialog_content = "Oh sério? Bacon, a que horas você marcou o encontro com Karl?",
  ui_story_5045_50451801_144_dialog_content = "Dez horas da manhã, nós dois concordamos em...",
  ui_story_5045_50451801_145_dialog_content = "Estou te perguntando, Bacon. Quando você deveria conhecer Karl?",
  ui_story_5045_50451801_146_dialog_content = "Marcamos um encontro às 10h para jantar às 18h...",
  ui_story_5045_50451801_147_dialog_content = "Isso é estranho. Fui preso às quatro horas da tarde de ontem.",
  ui_story_5045_50451801_148_dialog_content = "Como eu poderia estar lá no curso de autoajuda com vocês dois então?",
  ui_story_5045_50451801_149_dialog_content = "Bacon estava morrendo de medo ontem! Ele simplesmente não conseguia se lembrar claramente por um momento fugaz!",
  ui_story_5045_50451801_150_dialog_content = "Tínhamos marcado para almoçar ao meio-dia, certo?",
  ui_story_5045_50451801_151_dialog_content = "Certo, é isso... Lembrei-me incorretamente agora há pouco porque estava com tanto medo ontem...",
  ui_story_5045_50451801_152_dialog_content = "Depois de serem amedrontadas, as vítimas podem de fato desenvolver distúrbios de memória.",
  ui_story_5045_50451801_153_dialog_content = "Mas mais importante, PlayerName...",
  ui_story_5045_50451801_154_dialog_content = "Os Cavaleiros da Justiça descobriram muitos cartões de presença não utilizados em sua residência temporária.",
  ui_story_5045_50451801_155_dialog_content = "O que você tem a dizer em sua defesa?",
  ui_story_5045_50451801_156_option_content = "Alguém os plantou!",
  ui_story_5045_50451801_157_dialog_content = "Todas as evidências apontam para você. É melhor você se explicar da forma mais clara possível.",
  ui_story_5045_50451801_158_dialog_content = "Mas realmente não sei de onde vieram esses cartões de presença.",
  ui_story_5045_50451801_159_dialog_content = "Eu tenho andado como um sonâmbulo ou algo assim!?",
  ui_story_5045_50451801_160_option_content = "Objeção!",
  ui_story_5045_50451801_161_dialog_content = "O que lhe dá o direito de revistar minha residência à vontade?",
  ui_story_5045_50451801_162_dialog_content = "Você é o suspeito número um neste caso. Com tal causa provável, revistar sua residência é legal e razoável.",
  ui_story_5045_50451801_163_dialog_content = "Bom...",
  ui_story_5045_50451801_164_option_content = "Onde estão Tina e Leyn?",
  ui_story_5045_50451801_165_dialog_content = "Eu quero que eles testemunhem por mim!",
  ui_story_5045_50451801_166_dialog_content = "Eles estiveram ocupados investigando seus respectivos casos e não consegui encontrá-los.",
  ui_story_5045_50451801_167_dialog_content = "O que eu faço?",
  ui_story_5045_50451801_168_dialog_content = "Isso é tudo que você tem a dizer?",
  ui_story_5045_50451801_169_dialog_content = "Ué, eu...",
  ui_story_5045_50451801_170_dialog_content = "<color=#737378>Tum!</color>",
  ui_story_5045_50451801_171_dialog_content = "Noite Branca no alto. É hora de...",
  ui_story_5045_50451801_172_dialog_content = "Espere aí!",
  ui_story_5045_50451801_173_dialog_content = "Sério?",
  ui_story_5045_50451801_174_dialog_content = "Meritíssimo, ainda temos testemunhas que não compareceram perante o tribunal!",
  ui_story_5045_50451801_175_dialog_content = "Desculpe, PlayerName... Não estamos muito atrasados, estamos?",
  ui_story_5045_50451801_176_dialog_content = "Leyn, Tina...",
  ui_story_5045_50451801_177_dialog_content = "O julgamento ainda não acabou. Peço que as testemunhas restantes agora se apresentem e testemunhem!",
  ui_story_5045_50451801_178_dialog_content = "Meritíssimo, meu nome é Fanny...",
  ui_story_5045_50451801_179_dialog_content = "F-Fanny? Você está bem!?",
  ui_story_5045_50451801_180_dialog_content = "...?!",
  ui_story_5045_50451801_181_dialog_content = "Estou bem Bacon. Não se preocupe comigo. Podemos contar a verdade ao juiz supremo.",
  ui_story_5045_50451801_182_dialog_content = "Não tenha medo. O Hall da Justiça garantirá sua segurança.",
  ui_story_5045_50451801_183_dialog_content = "Ontem eu estava <color=#1875ad>seqüestrado</color>.",
  ui_story_5045_50451801_184_dialog_content = "Os sequestradores me mantiveram como refém e me usaram para ameaçar Bacon, obrigando-o a testemunhar contra um inocente.",
  ui_story_5045_50451801_185_dialog_content = "Sim! É verdade! Tudo o que eu disse agora foi o que o Guru da Autoajuda me disse para dizer!",
  ui_story_5045_50451801_186_dialog_content = "Eu estava morrendo de medo de que eles machucassem Fanny...",
  ui_story_5045_50451801_187_dialog_content = "Felizmente, os juízes Leyn e Tina me encontrou e me salvou.",
  ui_story_5045_50451801_188_dialog_content = "Agora, posso testemunhar no tribunal.",
  ui_story_5045_50451801_189_dialog_content = "Tem certeza PlayerName É inocente?",
  ui_story_5045_50451801_190_dialog_content = "Ele é, Meritíssimo.",
  ui_story_5045_50451801_191_dialog_content = "Quanto ao verdadeiro Guru da Autoajuda, embora usasse uma máscara, lembro-me de sua voz...",
  ui_story_5045_50451801_192_dialog_content = "Karl, tratamos você como um amigo. Por que você fez isso conosco?",
  ui_story_5045_50451801_193_dialog_content = "...",
  ui_story_5045_50451801_194_dialog_content = "Meritíssimo, isso deve ser algum tipo de mal-entendido! Algum tipo de mal-entendido grosseiro!",
  ui_story_5045_50451801_195_dialog_content = "Senhora Irridon, encontramos a entrada de um porão secreto em sua casa.",
  ui_story_5045_50451801_196_dialog_content = "Se entrarmos e procurarmos, podemos encontrar mais provas.",
  ui_story_5045_50451801_197_dialog_content = "Exatamente, e pedimos aos Lumo Knights para cercar toda a vizinhança.",
  ui_story_5045_50451801_198_dialog_content = "Estamos apenas esperando sua confirmação, Lady Irridon.",
  ui_story_5045_50451801_199_dialog_content = "...",
  ui_story_5045_50451801_200_dialog_content = "Karl está tentando fugir! Atenção!",
  ui_story_5045_50451801_201_dialog_content = "Pare aí mesmo!",
  ui_story_5045_50451801_202_dialog_content = "Você não pode escapar!",
  ui_story_5045_50451801_203_dialog_content = "Ugh...",
  ui_story_5045_50451901_1_dialog_content = "<color=#737378>Hora: 12h00</color>",
  ui_story_5045_50451901_2_dialog_content = "<color=#737378>Localização: Lumo Hall of Justice, Escritório da Divisão Romance</color>",
  ui_story_5045_50451901_3_dialog_content = "Senhora Irridon, esse foi realmente um teste difícil agora!",
  ui_story_5045_50451901_4_dialog_content = "Senhora Irridon está falando com PlayerName. Poupe seu fôlego.",
  ui_story_5045_50451901_5_dialog_content = "... Vou perdoá-lo desta vez, mas apenas porque você realmente levantou um bom ponto.",
  ui_story_5045_50451901_6_dialog_content = "PlayerName, Eu fiz uma grande injustiça com você hoje.",
  ui_story_5045_50451901_7_dialog_content = "Senhora Irridon... Você não sabia que eu estava sendo enganado o tempo todo, não é?",
  ui_story_5045_50451901_8_dialog_content = "Foi isso que eu disse?",
  ui_story_5045_50451901_9_dialog_content = "Meu pensamento é, se você realmente tivesse conseguido tanto dinheiro...",
  ui_story_5045_50451901_10_dialog_content = "Você não estaria disposto a vir ao Tribunal de Justiça para nos ajudar com tal salário.",
  ui_story_5045_50451901_11_dialog_content = "Erm... Eu realmente não sei se devo estar feliz ou triste.",
  ui_story_5045_50451901_12_dialog_content = "Tina, Leyn, seu desempenho hoje realmente me surpreendeu.",
  ui_story_5045_50451901_13_dialog_content = "Como você sabia que Fanny havia sido sequestrada?",
  ui_story_5045_50451901_14_dialog_content = "Encontramos meu cliente, Farrell. Ele não estava disposto a dizer nada a princípio, mas graças a Tina...",
  ui_story_5045_50451901_15_dialog_content = "Eu sei que você não quer testemunhar contra a mulher que ama, mas esta é a única maneira de salvá-la!",
  ui_story_5045_50451901_16_dialog_content = "Se não o fizer, ela será manipulada para sempre por aquele Guru de Autoajuda e viverá uma vida de sofrimento e humilhação!",
  ui_story_5045_50451901_17_dialog_content = "Esta é... a única maneira de salvá-la?",
  ui_story_5045_50451901_18_dialog_content = "Farrell nos disse que notou certas coisas estranhas que Sophie estava fazendo.",
  ui_story_5045_50451901_19_dialog_content = "A razão pela qual ele queria que Sophie se casasse com ele tão desesperadamente era para que ele pudesse salvá-la das garras do Guru de Autoajuda.",
  ui_story_5045_50451901_20_dialog_content = "Ele também nos contou alguns dos lugares que Sophie costumava ir.",
  ui_story_5045_50451901_21_dialog_content = "Este lugar é tão grande. Por onde devemos começar...?",
  ui_story_5045_50451901_21X1_dialog_content = "Huh? Onde está a Leyn?",
  ui_story_5045_50451901_22_dialog_content = "Senhoras, vocês viram um grupo de pessoas suspeitas por aqui?",
  ui_story_5045_50451901_23_dialog_content = "Sim! Nós certamente temos! Deixe-me contar tudo sobre eles, bonitão!",
  ui_story_5045_50451901_24_dialog_content = "Lá encontramos não só Fanny, mas também uma garotinha.",
  ui_story_5045_50451901_25_dialog_content = "Essa garotinha era irmã de Sophie...",
  ui_story_5045_50451901_26_dialog_content = "Ele estava usando vários reféns para dobrar essas boas pessoas à sua vontade. Karl é totalmente incorrigível!",
  ui_story_5045_50451901_27_dialog_content = "No entanto, Sophie teve a chance de se salvar e agora não pode escapar do julgamento do Tribunal de Justiça.",
  ui_story_5045_50451901_28_dialog_content = "Parece que você cresceu muito durante seu tempo na Divisão Romance.",
  ui_story_5045_50451901_29_dialog_content = "O-obrigado por dizer isso, senhora Irridon!",
  ui_story_5045_50451901_30_dialog_content = "Na verdade, devemos nosso sucesso hoje a PlayerNamea intuição de.",
  ui_story_5045_50451901_31_dialog_content = "Hã? Sério?",
  ui_story_5045_50451901_32_dialog_content = "PlayerName nos disse antes de ser preso que talvez as pistas estivessem escondidas nos dois casos que ele havia julgado anteriormente.",
  ui_story_5045_50451901_33_dialog_content = "Isso era basicamente só eu falando comigo mesmo. Eu não tinha certeza de nada na época...",
  ui_story_5045_50451901_34_dialog_content = "De qualquer forma, resolvemos um grande caso desta vez!",
  ui_story_5045_50451901_35_dialog_content = "Senhora Irridon, você está pensando em nos dar uma recompensa?",
  ui_story_5045_50451901_36_dialog_content = "Tina...",
  ui_story_5045_50451901_37_dialog_content = "Como você pode pedir uma coisa dessas de forma tão descarada?",
  ui_story_5045_50451901_38_dialog_content = "Com relação à recompensa, já preparei algo para você.",
  ui_story_5045_50451901_39_dialog_content = "Espere... Faça Angel e eu recebo algo também?",
  ui_story_5045_50451901_40_dialog_content = "PlayerName, obrigado por vir nos ajudar quando o Tribunal de Justiça enfrentou uma terrível falta de pessoal.",
  ui_story_5045_50451901_41_dialog_content = "Durante esse período, você não apenas ajudou os juízes da Divisão Romance a julgar com sucesso dois casos...",
  ui_story_5045_50451901_42_dialog_content = "Você assumiu a responsabilidade de erradicar o mal...",
  ui_story_5045_50451901_43_dialog_content = "E nos ajudou a levar o Guru da Autoajuda que aterrorizava o povo de Lumopolis à justiça.",
  ui_story_5045_50451901_44_dialog_content = "Os membros do Tribunal de Justiça concordaram que um <color=#1875ad>Juiz Honorário</color> troféu será concedido a você.",
  ui_story_5045_50451901_45_dialog_content = "Uau, é uma escultura! Parece tão especial!",
  ui_story_5045_50451901_46_dialog_content = "PlayerName, este troféu tem um peso tremendo.",
  ui_story_5045_50451901_47_dialog_content = "Huh? Serei capaz de carregá-lo?",
  ui_story_5045_50451901_48_dialog_content = "Quero dizer, a honra de receber este troféu não deve ser tomada de ânimo leve.",
  ui_story_5045_50451901_49_dialog_content = "Heehee! Se você não pode lidar com isso, PlayerName, posso usar minha Mão Divina para carregá-lo para você!",
  ui_story_5045_50451901_50_dialog_content = "Você está me dando um troféu...?",
  ui_story_5045_50451901_51_dialog_content = "O que? Você não quer isso?",
  ui_story_5045_50451901_52_dialog_content = "Eu só estou me perguntando se você não precisa mais da minha ajuda?",
  ui_story_5045_50451901_53_dialog_content = "Sim, você pode ver dessa forma.",
  ui_story_5045_50451901_54_dialog_content = "Recentemente, muitos casos em Lumopolis foram, de fato, relacionados ao Guru da Autoajuda.",
  ui_story_5045_50451901_55_dialog_content = "Agora que o Guru de Autoajuda foi preso, os casos da Divisão de Romance diminuirão gradualmente.",
  ui_story_5045_50451901_56_dialog_content = "Além disso, há muitos jovens de Dawn Academia pronta para vir aqui para estágios. Em breve, não teremos mais falta de pessoal.",
  ui_story_5045_50451901_57_dialog_content = "Claro, mas se você ainda quiser ficar...",
  ui_story_5045_50451901_58_dialog_content = "Você pode treinar junto com os jovens, e permanecer depois de passar na avaliação no final do período probatório.",
  ui_story_5045_50451901_59_dialog_content = "Esse processo pode levar de meio ano a um ano.",
  ui_story_5045_50451901_60_dialog_content = "Mas eu preciso voltar e cuidar de Cloud Gardens, e meus amigos sempre precisam que eu saia em aventuras com eles...",
  ui_story_5045_50451901_61_dialog_content = "Talvez seja melhor que meu tempo no Tribunal de Justiça termine aqui.",
  ui_story_5045_50451901_62_dialog_content = "É como eu disse, a vida no Tribunal de Justiça não é para todos.",
  ui_story_5045_50451901_63_dialog_content = "Então, PlayerName, vais embora agora?",
  ui_story_5045_50451901_64_dialog_content = "PlayerName...",
  ui_story_5045_50451901_65_dialog_content = "(Sinto que devo dizer algo agora.)",
  ui_story_5045_50451901_66_dialog_content = "(Mas o que devo dizer?)",
  ui_story_5045_50451901_67_dialog_content = "(Ah! Entendi!)",
  ui_story_5045_50451901_68_dialog_content = "Sim, sim - não há mais necessidade de olhar para isso.",
  ui_story_5045_50451901_69_dialog_content = "(É isso? Sinto que esqueci alguma coisa...)",
  ui_story_5045_50451901_70_dialog_content = "eu ainda tenho isso <color=#1875ad>pipa</color>.",
  ui_story_5045_50451901_71_dialog_content = "PlayerName, o que fazer com essa pipa agora?",
  ui_story_5045_50451901_72_dialog_content = "Devíamos entregá-lo a Farrell, o cavaleiro que espera que Sophie saia da prisão.",
  ui_story_5045_50451901_73_dialog_content = "Acho que depois que Sophie for libertada da prisão, talvez eles tenham a chance de empinar essa pipa juntos.",
  ui_story_5045_50451901_74_dialog_content = "Tudo bem, vou garantir que ele receba.",
  ui_story_5045_50451901_75_dialog_content = "Da próxima vez que você voltar a Lumopolis, talvez também tenhamos a chance de empinar pipas juntos...",
  ui_story_5045_50451901_76_dialog_content = "Claro! Não é como se nunca mais fossemos nos ver!",
  ui_story_5045_50451901_77_dialog_content = "Bom. Então faremos nossas próprias pipas quando você voltar!",
  ui_story_5045_50451901_78_dialog_content = "Eu vou te segurar nisso!",
  ui_story_5045_50451901_79_dialog_content = "da Tina <color=#1875ad>estatuetas de barro</color> ainda estão aqui.",
  ui_story_5045_50451901_80_dialog_content = "PlayerName, eu quero que você tenha isso!",
  ui_story_5045_50451901_81_dialog_content = "Sério?",
  ui_story_5045_50451901_82_dialog_content = "Mas não me interpretem mal, só quero agradecer por tornar meu trabalho muito mais fácil e muito mais divertido enquanto você estava aqui.",
  ui_story_5045_50451901_83_dialog_content = "Como trabalhamos na Divisão de Romance, é claro, desejo-lhe tudo de bom em assuntos do coração no futuro...",
  ui_story_5045_50451901_84_dialog_content = "Quando você conhece alguém de quem gosta e essa pessoa também gosta de você, sei que terá um doce amor que dura para sempre!",
  ui_story_5045_50451901_85_dialog_content = "Como essas duas figurinhas de barro...",
  ui_story_5045_50451901_86_dialog_content = "A imagem do amor, extraída da terra e temperada pelo fogo, torna-se finalmente um vínculo eterno!",
  ui_story_5045_50451901_87_dialog_content = "Muito obrigado, Tina!",
  ui_story_5045_50451901_88_dialog_content = "Embora eu ache que seja muito cedo na minha vida para receber esse tipo de bênção...",
  ui_story_5045_50451901_89_dialog_content = "Não é muito cedo!",
  ui_story_5045_50451901_90_dialog_content = "Quero dizer... se você não conseguir encontrar alguém de quem goste, volte para Lumopolis, ou talvez para o Hall of Justice.",
  ui_story_5045_50451901_91_dialog_content = "Claro, eu prometo que vou voltar.",
  ui_story_5045_50451901_92_dialog_content = "S-Sério?",
  ui_story_5045_50451901_93_dialog_content = "Então podemos ir para o campo e fazer um monte de figurinhas de barro e depois dá-las a todos os amantes por aí!",
  ui_story_5045_50451901_94_dialog_content = "Pode apostar!",
  ui_story_5045_50451901_95_dialog_content = "Sem a Divisão de Romance, eu nunca teria recebido este troféu querido.",
  ui_story_5045_50451901_96_dialog_content = "Quero deixar esse troféu com a Divisão Romance.",
  ui_story_5045_50451901_97_dialog_content = "Esta é uma ótima idéia!",
  ui_story_5045_50451901_98_dialog_content = "Mas onde você quer colocá-lo, PlayerName?",
  ui_story_5045_50451901_99_dialog_content = "Você realmente precisa perguntar? Basta colocá-lo na minha mesa!",
  ui_story_5045_50451901_100_dialog_content = "Dê uma olhada — sou o único com uma mesa limpa o suficiente para isso!",
  ui_story_5045_50451901_101_dialog_content = "Eu acho...",
  ui_story_5045_50451901_102_dialog_content = "Todos devem se revezar colocando-o em suas mesas.",
  ui_story_5045_50451901_103_dialog_content = "Sim, isso é justo!",
  ui_story_5045_50451901_104_dialog_content = "Então, está decidido!",
  ui_story_5045_50451901_105_dialog_content = "Todos?",
  ui_story_5045_50451901_106_dialog_content = "Isso inclui a mim, certo? Ei...",
  ui_story_5045_50451901_107_dialog_content = "neste caderno...",
  ui_story_5045_50451901_108_dialog_content = "Anotei tudo e todos que encontrei depois de vir para a Divisão Romance.",
  ui_story_5045_50451901_109_dialog_content = "Nosso desamparo e mágoa quando nos deparamos com grandes dificuldades juntos...",
  ui_story_5045_50451901_110_dialog_content = "E a felicidade e a sensação de conquista depois de fazerem um julgamento bem-sucedido juntos!",
  ui_story_5045_50451901_111_dialog_content = "Enquanto eu tiver isso, nunca vou esquecer os dias maravilhosos que passei na Divisão Romance!",
  ui_story_5045_50451901_112_dialog_content = "Enquanto eu estiver fora, todos, por favor, escrevam seus sentimentos em seus cadernos para mim.",
  ui_story_5045_50451901_113_dialog_content = "No futuro, quando eu voltar...",
  ui_story_5045_50451901_114_dialog_content = "Poderei ouvir tudo sobre os casos estranhos que tenho perdido!",
  ui_story_5045_50451901_115_dialog_content = "De fato...",
  ui_story_5045_50451901_116_dialog_content = "PlayerName, você é tão mau...",
  ui_story_5045_50451901_117_dialog_content = "Pare de tentar nos fazer chorar!",
  ui_story_5045_50451901_118_dialog_content = "Obrigado pelo conselho, PlayerName...",
  ui_story_5045_50451901_119_dialog_content = "Vou registrar todos os casos mais fascinantes para você!",
  ui_story_5045_50451901_120_dialog_content = "Você vê isso, Angel? Comece a fazer anotações!",
  ui_story_5045_50451901_121_dialog_content = "... OK!",
  ui_story_5045_50451901_122_dialog_content = "Adeus a todos.",
  ui_story_5045_50451901_123_dialog_content = "Adeus, Divisão Romance.",
  ui_story_5045_50451901_124_dialog_content = "Eu sei que um dia...",
  ui_story_5045_50451901_125_option_content = "Vejo você de novo!"
}
return config
